class ModeleFilterProxyModel : public QSortFilterProxyModel
{
public:
    explicit ModeleFilterProxyModel(QObject *parent = nullptr)
        : QSortFilterProxyModel(parent)
    {}

    void setStatusFilter(const QString &status)
    {
        const QString normalized = status.trimmed().isEmpty() ? QString("Tous") : status.trimmed();
        if (m_statusFilter == normalized) {
            return;
        }
        m_statusFilter = normalized;
        invalidateFilter();
    }

protected:
    bool filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const override
    {
        // Col 8 = computed status column in modele list.
        if (m_statusFilter != "Tous") {
            const QModelIndex statusIdx = sourceModel()->index(sourceRow, 8, sourceParent);
            const QString rowStatus = sourceModel()->data(statusIdx).toString();
            if (rowStatus != m_statusFilter) {
                return false;
            }
        }
        return QSortFilterProxyModel::filterAcceptsRow(sourceRow, sourceParent);
    }

private:
    QString m_statusFilter = "Tous";
};

class FabricationFilterProxyModel : public QSortFilterProxyModel
{
public:
    explicit FabricationFilterProxyModel(QObject *parent = nullptr)
        : QSortFilterProxyModel(parent)
    {}

    void setStatusFilter(const QString &status)
    {
        const QString normalized = status.trimmed().isEmpty() ? QString("Tous") : status.trimmed();
        if (m_statusFilter == normalized) {
            return;
        }
        m_statusFilter = normalized;
        invalidateFilter();
    }

protected:
    bool filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const override
    {
        // Col 5 = ETAT_FABRICATION in base FABRICATION table model.
        if (m_statusFilter != "Tous") {
            const QModelIndex statusIdx = sourceModel()->index(sourceRow, 5, sourceParent);
            const QString rowStatus = sourceModel()->data(statusIdx).toString();
            if (rowStatus != m_statusFilter) {
                return false;
            }
        }
        return QSortFilterProxyModel::filterAcceptsRow(sourceRow, sourceParent);
    }

private:
    QString m_statusFilter = "Tous";
};

