constexpr int kArduinoScanLatencyMs = 5000;

QString resolveProjectRootPath()
{
    const QStringList startPaths = {
        QDir::currentPath(),
        QCoreApplication::applicationDirPath()
    };

    for (const QString &startPath : startPaths) {
        QDir dir(startPath);
        for (int depth = 0; depth < 12; ++depth) {
            if (dir.exists("Smartcarpentry.pro") || dir.exists("CMakeLists.txt")) {
                return QDir::cleanPath(dir.absolutePath());
            }
            if (!dir.cdUp()) {
                break;
            }
        }
    }

    return QDir::cleanPath(QCoreApplication::applicationDirPath());
}

QString persistProfilePhotoUpload(const QString &sourcePath, QString *errorMessage = nullptr)
{
    if (errorMessage) {
        errorMessage->clear();
    }

    const QString trimmedSource = sourcePath.trimmed();
    if (trimmedSource.isEmpty()) {
        if (errorMessage) *errorMessage = "Aucune image selectionnee.";
        return QString();
    }

    QFileInfo sourceInfo(trimmedSource);
    if (!sourceInfo.exists() || !sourceInfo.isFile()) {
        if (errorMessage) *errorMessage = "Image source introuvable.";
        return QString();
    }

    QImageReader reader(trimmedSource);
    if (!reader.canRead()) {
        if (errorMessage) *errorMessage = "Fichier image invalide ou format non pris en charge.";
        return QString();
    }

    const QString projectRoot = resolveProjectRootPath();
    QDir photoDir(projectRoot + "/employee_photos");
    if (!photoDir.exists() && !photoDir.mkpath(".")) {
        if (errorMessage) *errorMessage = "Impossible de creer le dossier des photos.";
        return QString();
    }

    const QString extension = sourceInfo.suffix().isEmpty() ? QString("png") : sourceInfo.suffix().toLower();
    const QString fileName = QString("profile_%1_%2.%3")
            .arg(QDateTime::currentDateTimeUtc().toString("yyyyMMddHHmmsszzz"))
            .arg(QRandomGenerator::global()->bounded(1000, 9999))
            .arg(extension);
    const QString targetPath = photoDir.filePath(fileName);

    if (!QFile::copy(trimmedSource, targetPath)) {
        if (errorMessage) *errorMessage = "Echec de copie de la photo dans le stockage local.";
        return QString();
    }

    return QDir::cleanPath(targetPath);
}

void cleanupUnusedManagedProfilePhoto(const QString &storedPath)
{
    const QString path = storedPath.trimmed();
    if (path.isEmpty()) {
        return;
    }

    QFileInfo fi(path);
    if (!fi.exists() || !fi.isFile()) {
        return;
    }

    const QString normalizedPath = QDir::cleanPath(fi.absoluteFilePath()).toLower();
    if (!normalizedPath.contains("employee_photos")) {
        return;
    }

    QFile::remove(fi.absoluteFilePath());
}

