QString canonicalEmployeeSkillLevel(QString rawValue)
{
    QString value = rawValue.trimmed().toUpper();
    value = value.normalized(QString::NormalizationForm_D);
    value.remove(QRegularExpression(QStringLiteral("[\\x{0300}-\\x{036F}]")));
    value.replace('-', '_');
    value.replace(' ', '_');

    // Accept common variants that can appear with mismatched encodings.
    if (value.contains("CERTIFI")) {
        return "CERTIFIE";
    }
    if (value.contains("EN") && value.contains("FORMATION")) {
        return "EN_FORMATION";
    }
    if (value.contains("NON") && value.contains("QUALIF")) {
        return "NON_QUALIFIE";
    }

    return value;
}

int nextEmployeeSkillId()
{
    QSqlQuery query;
    if (!query.exec("SELECT NVL(MAX(IDSKILL), 0) + 1 FROM EMPLOYEE_SKILL") || !query.next()) {
        return 1;
    }
    return qMax(1, query.value(0).toInt());
}

bool insertEmployeeSkillRow(int skillId,
                            int employeeId,
                            const QString &skillName,
                            const QString &skillLevel,
                            const QDate &expirationDate,
                            bool hasExpiration,
                            QString &errorMessage)
{
    errorMessage.clear();

    const QString normalizedSkill = skillName.trimmed();
    const QString normalizedLevel = canonicalEmployeeSkillLevel(skillLevel);

    if (skillId <= 0 || employeeId <= 0 || normalizedSkill.isEmpty()) {
        errorMessage = "Donnes de competence invalides.";
        return false;
    }

    if (normalizedLevel != "CERTIFIE" && normalizedLevel != "EN_FORMATION" && normalizedLevel != "NON_QUALIFIE") {
        errorMessage = "Niveau de competence invalide.";
        return false;
    }

        if (normalizedLevel == "CERTIFIE" && !hasExpiration) {
        errorMessage = QString("La date d'expiration est requise pour la competence %1.").arg(normalizedSkill);
        return false;
    }

    QSqlQuery query;
    query.prepare(
        "INSERT INTO EMPLOYEE_SKILL (idSkill, idEmployee, nom_competence, niveau_maitrise, date_expiration) "
        "VALUES (:idSkill, :idEmployee, :skill, :level, :expiration)");
    query.bindValue(":idSkill", skillId);
    query.bindValue(":idEmployee", employeeId);
    query.bindValue(":skill", normalizedSkill);
    query.bindValue(":level", normalizedLevel);
    if (hasExpiration && expirationDate.isValid()) {
        query.bindValue(":expiration", expirationDate);
    } else {
        query.bindValue(":expiration", QVariant(QMetaType::fromType<QDate>()));
    }

    if (!query.exec()) {
        errorMessage = query.lastError().text();
        return false;
    }

    return true;
}

struct SkillEvidence
{
    int total = 0;
    int certifiedActive = 0;
    int certifiedExpired = 0;
    int inTraining = 0;
    int nonQualified = 0;
};

SkillEvidence fetchSkillEvidence(int employeeId)
{
    SkillEvidence evidence;
    if (employeeId <= 0) {
        return evidence;
    }

    QSqlQuery query;
    query.prepare(
        "SELECT "
        "COUNT(*), "
        "SUM(CASE WHEN UPPER(NIVEAU_MAITRISE) = 'CERTIFIE' "
        "          AND (DATE_EXPIRATION IS NULL OR DATE_EXPIRATION >= TRUNC(SYSDATE)) THEN 1 ELSE 0 END), "
        "SUM(CASE WHEN UPPER(NIVEAU_MAITRISE) = 'CERTIFIE' "
        "          AND DATE_EXPIRATION IS NOT NULL AND DATE_EXPIRATION < TRUNC(SYSDATE) THEN 1 ELSE 0 END), "
        "SUM(CASE WHEN UPPER(NIVEAU_MAITRISE) = 'EN_FORMATION' THEN 1 ELSE 0 END), "
        "SUM(CASE WHEN UPPER(NIVEAU_MAITRISE) = 'NON_QUALIFIE' THEN 1 ELSE 0 END) "
        "FROM EMPLOYEE_SKILL "
        "WHERE IDEMPLOYEE = :id");
    query.bindValue(":id", employeeId);
    if (!query.exec() || !query.next()) {
        return evidence;
    }

    evidence.total = query.value(0).toInt();
    evidence.certifiedActive = query.value(1).toInt();
    evidence.certifiedExpired = query.value(2).toInt();
    evidence.inTraining = query.value(3).toInt();
    evidence.nonQualified = query.value(4).toInt();
    return evidence;
}

bool isStoredPasswordHash(const QString &value)
{
    return value.startsWith("sha256$");
}

bool verifyPasswordAgainstStored(const QString &plainPassword, const QString &storedPassword)
{
    if (isStoredPasswordHash(storedPassword)) {
        const QStringList parts = storedPassword.split('$');
        if (parts.size() != 3 || parts.at(0) != "sha256") {
            return false;
        }

        const QByteArray salt = QByteArray::fromHex(parts.at(1).toLatin1());
        const QByteArray expected = parts.at(2).toLatin1();
        if (salt.isEmpty() || expected.isEmpty()) {
            return false;
        }

        const QByteArray computed = QCryptographicHash::hash(salt + plainPassword.toUtf8(),
                                                             QCryptographicHash::Sha256).toHex();
        return computed == expected;
    }

    // Backward compatibility for legacy plaintext passwords.
    return storedPassword == plainPassword;
}

QString hashPasswordWithSalt(const QString &password)
{
    QByteArray salt(16, '\0');
    for (int i = 0; i < salt.size(); ++i) {
        salt[i] = static_cast<char>(QRandomGenerator::global()->bounded(256));
    }

    const QByteArray hash = QCryptographicHash::hash(salt + password.toUtf8(),
                                                     QCryptographicHash::Sha256);
    return QString("sha256$%1$%2")
        .arg(QString::fromLatin1(salt.toHex()), QString::fromLatin1(hash.toHex()));
}

bool insertEmployeeHistoryEntry(int idEmployee,
                                const QString &action,
                                const QString &actionBy,
                                const QString &details)
{
    if (action.trimmed().isEmpty()) {
        return false;
    }
    int actionById = 1;
    const QString actor = actionBy.trimmed();
    if (!actor.isEmpty()) {
        bool ok = false;
        const int numericActor = actor.toInt(&ok);
        if (ok && numericActor > 0) {
            actionById = numericActor;
        } else {
            QSqlQuery actorQuery;
            actorQuery.prepare(
                "SELECT IDEMPLOYEE FROM EMPLOYEE WHERE LOWER(MAIL) = LOWER(:actor) OR LOWER(NOM || ' ' || PRENOM) = LOWER(:actor) ORDER BY IDEMPLOYEE");
            actorQuery.bindValue(":actor", actor);
            if (actorQuery.exec() && actorQuery.next()) {
                actionById = actorQuery.value(0).toInt();
            }
        }
    }

    QSqlQuery query;
    query.prepare(
        "INSERT INTO AUDIT_LOG (ID_LOG, TABLE_NAME, RECORD_ID, ACTION_TYPE, ACTION_BY, ACTION_AT, DETAILS) "
        "SELECT NVL(MAX(ID_LOG), 0) + 1, 'EMPLOYEE', :recordId, :action, :actionBy, SYSTIMESTAMP, :details "
        "FROM AUDIT_LOG");
    query.bindValue(":recordId", qMax(0, idEmployee));
    query.bindValue(":action", action.trimmed().left(30));
    query.bindValue(":actionBy", actionById);
    query.bindValue(":details", details.left(1000));
    if (query.exec()) {
        return true;
    }

    qWarning() << "Erreur logEmployeeHistory:" << query.lastError().text();
    return false;
}

