bool openModeleEditorDialog(QWidget *parent, ModeleEditorState &state, bool editMode)
{
    QDialog dialog(parent);
    dialog.setWindowTitle(editMode ? "Modifier modele" : "Ajouter modele");
    dialog.setMinimumWidth(520);
    dialog.setStyleSheet(
        "QDialog{background-color:#0f172a;color:#f8fafc;}"
        "QLabel{color:#e2e8f0;font-weight:600;}"
        "QLineEdit,QTextEdit,QComboBox,QDoubleSpinBox{background-color:rgba(255,255,255,0.06);border:1px solid rgba(99,102,241,0.25);border-radius:8px;padding:8px 10px;color:#f8fafc;}"
        "QLineEdit:focus,QTextEdit:focus,QComboBox:focus,QDoubleSpinBox:focus{border:1px solid #6366f1;}"
        "QPushButton{background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #4f46e5,stop:1 #6366f1);border:none;border-radius:8px;color:white;padding:8px 16px;font-weight:700;}"
        "QPushButton:hover{background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #6366f1,stop:1 #818cf8);}");

    QFormLayout form(&dialog);
    form.setLabelAlignment(Qt::AlignLeft);
    form.setFormAlignment(Qt::AlignTop);

    QLineEdit idEdit(QString::number(state.id));
    idEdit.setPlaceholderText("Auto");
    if (editMode) {
        idEdit.setReadOnly(true);
    }

    QLineEdit nomEdit(state.nom);
    QComboBox categorieCombo;
    categorieCombo.setEditable(true);
    categorieCombo.addItems({"Meuble", "Decoration", "Structure", "Cuisine", "Salon", "Chambre", "Bureau", "Autre"});
    categorieCombo.setCurrentText(state.categorie);
    QLineEdit dimEdit(state.dimensions);
    QComboBox typeCombo;
    typeCombo.setEditable(true);
    typeCombo.addItems({"Standard", "Sur mesure", "Premium"});
    typeCombo.setCurrentText(state.type);
    QDoubleSpinBox prixSpin;
    prixSpin.setRange(0.0, 1000000.0);
    prixSpin.setDecimals(2);
    prixSpin.setValue(state.prix);
    QTextEdit descEdit(state.description);
    descEdit.setFixedHeight(72);
    QDoubleSpinBox coutSpin;
    coutSpin.setRange(0.0, 1000000.0);
    coutSpin.setDecimals(2);
    coutSpin.setValue(state.cout);

    form.addRow("ID", &idEdit);
    form.addRow("Nom modele", &nomEdit);
    form.addRow("Categorie", &categorieCombo);
    form.addRow("Dimensions", &dimEdit);
    form.addRow("Type", &typeCombo);
    form.addRow("Prix base", &prixSpin);
    form.addRow("Description", &descEdit);
    form.addRow("Cout estime", &coutSpin);

    QDialogButtonBox buttons(QDialogButtonBox::Ok | QDialogButtonBox::Cancel);
    form.addRow(&buttons);
    QObject::connect(&buttons, &QDialogButtonBox::accepted, &dialog, [&]() {
        const QString nom = nomEdit.text().trimmed();
        const QString cat = categorieCombo.currentText().trimmed();
        const QString dim = dimEdit.text().trimmed();
        const QString type = typeCombo.currentText().trimmed();
        const QString desc = descEdit.toPlainText().trimmed();
        const double prix = prixSpin.value();
        const double cout = coutSpin.value();

        if (!Modele::validerNomModele(nom) || !Modele::validerCategorie(cat) ||
            !Modele::validerDimensions(dim) || !Modele::validerType(type) ||
            !Modele::validerPrix(prix) || !Modele::validerCout(cout) || desc.isEmpty()) {
            QMessageBox::warning(&dialog, "Validation", "Veuillez remplir correctement tous les champs.");
            return;
        }

        if (!editMode && !idEdit.text().trimmed().isEmpty()) {
            bool ok = false;
            const int parsedId = idEdit.text().trimmed().toInt(&ok);
            if (!ok || !Modele::validerId(parsedId)) {
                QMessageBox::warning(&dialog, "Validation", "ID invalide.");
                return;
            }
            state.id = parsedId;
        } else if (!editMode) {
            state.id = 0;
        }

        state.nom = nom;
        state.categorie = cat;
        state.dimensions = dim;
        state.type = type;
        state.prix = prix;
        state.description = desc;
        state.cout = cout;
        dialog.accept();
    });
    QObject::connect(&buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);

    return dialog.exec() == QDialog::Accepted;
}

