void smartcarpentry::applyGlobalPremiumStyle(QTableView *tv, QLineEdit *search, QPushButton *modify, QPushButton *deleteBtn)
{
    if (!tv) return;

    // --- Table Styling ---
    tv->setShowGrid(false);
    tv->setAlternatingRowColors(false);
    tv->setSelectionBehavior(QAbstractItemView::SelectRows);
    tv->setSelectionMode(QAbstractItemView::SingleSelection);
    tv->setEditTriggers(QAbstractItemView::DoubleClicked | QAbstractItemView::EditKeyPressed); // CRITICAL FIX: Unlock editing globally
    tv->setStyleSheet(
        "QTableView { background: #1e293b; border: 1px solid rgba(255,255,255,0.05); border-radius: 15px; gridline-color: transparent; selection-background-color: transparent; color: #e2e8f0; } " "QLineEdit { background: #1e293b; color: white; border: 1px solid #10b981; } "
        "QHeaderView::section { background: rgba(15,23,42,0.6); color: #94a3b8; padding: 12px; border: none; font-weight: bold; font-size: 11px; text-transform: uppercase; } "
        "QTableView::item { padding: 8px; border-bottom: 1px solid rgba(255,255,255,0.02); }"
    );
    tv->verticalHeader()->setVisible(false);
    tv->verticalHeader()->setDefaultSectionSize(45);
    tv->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch); // CRITICAL: Makes columns fill the available width evenly
    
    // Default to CenteredTableDelegate unless it's the Wood table handled separately
    if (tv->objectName() != "tv_bois") {
        tv->setItemDelegate(new CenteredTableDelegate(this));
    }

    // --- Search Bar Styling ---
    if (search) {
        search->setPlaceholderText(" \U0001F50D Rechercher dans la liste...");
        search->setStyleSheet(
            "QLineEdit { background: rgba(30,41,59,0.5); border: 1px solid rgba(255,255,255,0.1); border-radius: 12px; color: #f8fafc; padding: 6px 15px; } "
            "QLineEdit:focus { border: 1px solid #10b981; }"
        );
    }

    // --- Action Button Styling ---
    if (modify) {
        modify->setStyleSheet(
            "QPushButton { background: rgba(79,70,229,0.15); color: #a5b4fc; border: 1px solid rgba(129,140,248,0.3); border-radius: 10px; padding: 8px 25px; font-weight: bold; } "
            "QPushButton:hover { background: rgba(79,70,229,0.25); border: 1px solid #818cf8; color: white; }"
        );
    }
    if (deleteBtn) {
        deleteBtn->setStyleSheet(
            "QPushButton { background: rgba(239,68,68,0.1); color: #fca5a5; border: 1px solid rgba(248,113,113,0.3); border-radius: 10px; padding: 8px 25px; font-weight: bold; } "
            "QPushButton:hover { background: rgba(239,68,68,0.2); border: 1px solid #f87171; color: white; }"
        );
    }
}

