    // ---- RFID Manager initialization ----
    rfidManager = new RfidManager(this);

    // Keep the RFID log browser detached until it is placed in a real layout.
    rfidLogBrowser = new QTextBrowser(this);
    rfidLogBrowser->setReadOnly(true);
    rfidLogBrowser->hide();

    connect(rfidManager, &RfidManager::connectionChanged, this, [this](bool connected) {
        statusBar()->showMessage(connected ? tr("RFID connected") : tr("RFID disconnected"), 5000);
    });
    connect(rfidManager, &RfidManager::statusChanged, this, [this](const QString &status) {
        statusBar()->showMessage(tr("RFID status: %1").arg(status), 5000);
    });
    connect(rfidManager, &RfidManager::cardUpdated, this, [this](const QString &uid) {
        statusBar()->showMessage(tr("RFID card updated: %1").arg(uid), 5000);
    });
    connect(rfidManager, &RfidManager::accessEvent, this, [this](const AccessLog &log) {
        int resolvedEmployeeId = -1;
        const QString employeeName = rfidManager ? rfidManager->resolveEmployeeNameForCard(log.uid, &resolvedEmployeeId) : QString();

        if (resolvedEmployeeId > 0 && !employeeName.isEmpty()) {
            const AccessType accessType = rfidManager->recordAttendance(log.uid, resolvedEmployeeId);
            const QString eventDisplay = (accessType == AccessType::IN_EVENT) ? "Entree" : "Sortie";
            const QString safeEmployeeName = employeeName.left(50);
            const QString logEntry = QString("[%1] %2 - %3")
                .arg(log.timestamp.toString("HH:mm:ss"))
                .arg(eventDisplay)
                .arg(safeEmployeeName);

            if (rfidLogBrowser) {
                rfidLogBrowser->append(logEntry);
                rfidLogBrowser->ensureCursorVisible();
            }
            statusBar()->showMessage(tr("RFID: %1 - %2").arg(eventDisplay, safeEmployeeName), 5000);
        } else {
            const QString logEntry = QString("[%1] Acces refuse - %2")
                .arg(log.timestamp.toString("HH:mm:ss"))
                .arg(log.uid);

            if (rfidLogBrowser) {
                rfidLogBrowser->append(logEntry);
                rfidLogBrowser->ensureCursorVisible();
            }
            statusBar()->showMessage(tr("RFID: Acces refuse - %1").arg(log.uid), 5000);
        }
    });

