    const auto showChangePasswordDialog = [this]() {
        if (this->currentUserEmail.trimmed().isEmpty()) {
            QMessageBox::warning(this,
                                 "Mot de passe",
                                 "Email utilisateur introuvable. Reconnectez-vous puis reessayez.");
            return;
        }

        QDialog dialog(this);
        dialog.setWindowTitle("Changer mon mot de passe");
        dialog.setModal(true);
        dialog.setMinimumWidth(430);

        QVBoxLayout *layout = new QVBoxLayout(&dialog);
        QGridLayout *form = new QGridLayout();

        QLabel *lblOld = new QLabel("Mot de passe actuel", &dialog);
        QLabel *lblNew = new QLabel("Nouveau mot de passe", &dialog);
        QLabel *lblConfirm = new QLabel("Confirmer", &dialog);

        QLineEdit *oldPass = new QLineEdit(&dialog);
        oldPass->setEchoMode(QLineEdit::Password);
        oldPass->setPlaceholderText("Mot de passe actuel");

        QLineEdit *newPass = new QLineEdit(&dialog);
        newPass->setEchoMode(QLineEdit::Password);
        newPass->setPlaceholderText("Nouveau mot de passe");

        QLineEdit *confirmPass = new QLineEdit(&dialog);
        confirmPass->setEchoMode(QLineEdit::Password);
        confirmPass->setPlaceholderText("Confirmer le nouveau mot de passe");

        form->addWidget(lblOld, 0, 0);
        form->addWidget(oldPass, 0, 1);
        form->addWidget(lblNew, 1, 0);
        form->addWidget(newPass, 1, 1);
        form->addWidget(lblConfirm, 2, 0);
        form->addWidget(confirmPass, 2, 1);
        layout->addLayout(form);

        QHBoxLayout *actions = new QHBoxLayout();
        QPushButton *cancelBtn = new QPushButton("Annuler", &dialog);
        QPushButton *saveBtn = new QPushButton("Mettre a jour", &dialog);
        actions->addStretch();
        actions->addWidget(cancelBtn);
        actions->addWidget(saveBtn);
        layout->addLayout(actions);

        connect(cancelBtn, &QPushButton::clicked, &dialog, &QDialog::reject);
        connect(saveBtn, &QPushButton::clicked, &dialog, [this, &dialog, oldPass, newPass, confirmPass]() {
            const QString oldValue = oldPass->text();
            const QString newValue = newPass->text();
            const QString confirmValue = confirmPass->text();

            if (oldValue.isEmpty() || newValue.isEmpty() || confirmValue.isEmpty()) {
                QMessageBox::warning(&dialog, "Mot de passe", "Tous les champs sont obligatoires.");
                return;
            }
            if (!Employee::validerPassword(newValue)) {
                QMessageBox::warning(&dialog,
                                     "Mot de passe",
                                     "Nouveau mot de passe invalide (4 a 255 caracteres).");
                return;
            }
            if (newValue != confirmValue) {
                QMessageBox::warning(&dialog,
                                     "Mot de passe",
                                     "La confirmation ne correspond pas au nouveau mot de passe.");
                return;
            }

            QSqlQuery readQuery;
            readQuery.prepare("SELECT PASSWORD FROM EMPLOYEE WHERE LOWER(MAIL) = LOWER(:mail)");
            readQuery.bindValue(":mail", this->currentUserEmail.trimmed());
            if (!readQuery.exec() || !readQuery.next()) {
                QMessageBox::warning(&dialog,
                                     "Mot de passe",
                                     "Impossible de retrouver l'utilisateur courant.");
                return;
            }

            const QString storedPassword = readQuery.value(0).toString();
            if (!verifyPasswordAgainstStored(oldValue, storedPassword)) {
                QMessageBox::warning(&dialog,
                                     "Mot de passe",
                                     "Mot de passe actuel incorrect.");
                return;
            }

            QSqlQuery updateQuery;
            updateQuery.prepare("UPDATE EMPLOYEE SET PASSWORD = :pwd WHERE LOWER(MAIL) = LOWER(:mail)");
            updateQuery.bindValue(":pwd", hashPasswordWithSalt(newValue));
            updateQuery.bindValue(":mail", this->currentUserEmail.trimmed());
            if (!updateQuery.exec()) {
                QMessageBox::critical(&dialog,
                                      "Mot de passe",
                                      "Echec de mise a jour: " + updateQuery.lastError().text());
                return;
            }
            if (updateQuery.numRowsAffected() <= 0) {
                QMessageBox::warning(&dialog,
                                     "Mot de passe",
                                     "Aucun compte n'a ete mis a jour.");
                return;
            }

            QMessageBox::information(&dialog,
                                     "Mot de passe",
                                     "Mot de passe mis a jour avec succes.");
            dialog.accept();
        });

        dialog.exec();
    };

