    auto buildCircularProfileIcon = [](const QPixmap &source, const QString &fallbackInitials = QString()) {
        constexpr int kAvatarSize = 64;
        QPixmap avatar(kAvatarSize, kAvatarSize);
        avatar.fill(Qt::transparent);

        QPainter painter(&avatar);
        painter.setRenderHint(QPainter::Antialiasing, true);
        painter.setRenderHint(QPainter::SmoothPixmapTransform, true);

        QRectF circleRect(2.0, 2.0, kAvatarSize - 4.0, kAvatarSize - 4.0);

        if (!source.isNull()) {
            QPainterPath clipPath;
            clipPath.addEllipse(circleRect);
            painter.setClipPath(clipPath);

            const QPixmap scaled = source.scaled(kAvatarSize,
                                                 kAvatarSize,
                                                 Qt::KeepAspectRatioByExpanding,
                                                 Qt::SmoothTransformation);
            const QRect targetRect(0, 0, kAvatarSize, kAvatarSize);
            const QPoint topLeft((scaled.width() - kAvatarSize) / 2,
                                 (scaled.height() - kAvatarSize) / 2);
            painter.drawPixmap(targetRect, scaled, QRect(topLeft, QSize(kAvatarSize, kAvatarSize)));
            painter.setClipping(false);
        } else {
            painter.setPen(Qt::NoPen);
            painter.setBrush(QColor("#334155"));
            painter.drawEllipse(circleRect);

            painter.setPen(QColor("#f8fafc"));
            QFont f = painter.font();
            f.setBold(true);
            f.setPointSize(20);
            painter.setFont(f);
            painter.drawText(avatar.rect(), Qt::AlignCenter, fallbackInitials.isEmpty() ? QString("U") : fallbackInitials);
        }

        painter.setPen(QPen(QColor("#94a3b8"), 2));
        painter.setBrush(Qt::NoBrush);
        painter.drawEllipse(circleRect);

        return QIcon(avatar);
    };

    QPixmap profilePixmap;
    QIcon profileIcon;
    const QString profilePath = currentUserImagePath.trimmed();
    if (!profilePath.isEmpty()) {
        QStringList candidates;
        candidates << profilePath;

        if (!QFileInfo(profilePath).isAbsolute()) {
            candidates << QDir::current().filePath(profilePath);
            candidates << QCoreApplication::applicationDirPath() + "/" + profilePath;
        }

        for (const QString &candidate : candidates) {
            if (candidate.startsWith(":/")) {
                QPixmap pix(candidate);
                if (!pix.isNull()) {
                    profilePixmap = pix;
                    break;
                }
            } else if (QFileInfo::exists(candidate)) {
                QPixmap pix(candidate);
                if (!pix.isNull()) {
                    profilePixmap = pix;
                    break;
                }
            }
        }
    }

