//  Helper: Clear the Employee form fields
// ============================================================

void smartcarpentry::clearEmployeeForm()
{
    ui->emp_cin->clear();
    ui->emp_mail->clear();
    ui->emp_password->clear();
    ui->emp_nom->clear();
    ui->emp_prenom->clear();
    ui->emp_date_naissance->setDate(QDate(2000, 1, 1));
    ui->emp_role->setCurrentIndex(0);
    ui->emp_face_id->clear();
    selectedEmpId = -1;
}

// ============================================================
//  CRUD - Add Employee
// ============================================================

void smartcarpentry::on_btn_emp_add_clicked()
{
    // Read form values (ID is auto-generated, not needed)
    QString cin    = ui->emp_cin->text().trimmed();
    QString mail   = ui->emp_mail->text().trimmed();
    QString pass   = ui->emp_password->text().trimmed();
    QString nom    = ui->emp_nom->text().trimmed();
    QString prenom = ui->emp_prenom->text().trimmed();
    QDate   dateN  = ui->emp_date_naissance->date();
    QString role   = ui->emp_role->currentText();
    QString photoPath = ui->emp_face_id->text().trimmed();

    // --- Input validation ---
    if (!Employee::validerCIN(cin)) {
        QMessageBox::warning(this, "Erreur", "CIN invalide (8 chiffres attendus).");
        return;
    }
    if (!Employee::validerMail(mail)) {
        QMessageBox::warning(this, "Erreur", "Adresse e-mail invalide.");
        return;
    }
    if (!Employee::validerPassword(pass)) {
        QMessageBox::warning(this, "Erreur", "Mot de passe invalide (4 a 255 caracteres).");
        return;
    }
    if (!Employee::validerNom(nom)) {
        QMessageBox::warning(this, "Erreur", "Nom invalide (lettres uniquement, 1-50 caracteres).");
        return;
    }
    if (!Employee::validerPrenom(prenom)) {
        QMessageBox::warning(this, "Erreur", "Prenom invalide (lettres uniquement, 1-50 caracteres).");
        return;
    }
    if (!Employee::validerDateNaissance(dateN)) {
        QMessageBox::warning(this, "Erreur", "Date de naissance invalide (age entre 18 et 100 ans).");
        return;
    }
    if (!Employee::validerRole(role)) {
        QMessageBox::warning(this, "Erreur", "Role invalide.");
        return;
    }

    // Build Employee object (ID auto-generated in ajouter())
    Employee e;
    e.setCIN(cin);
    e.setMail(mail);
    e.setPassword(pass);
    e.setNom(nom);
    e.setPrenom(prenom);
    e.setDateNaissance(dateN);
    e.setRole(role);
    e.setFaceId(QString());
    e.setPhotoPath(photoPath);

    if (e.ajouter()) {
        QMessageBox::information(this, "Succes", "Employe ajoute avec succes !");
        refreshEmployeeTable();
        clearEmployeeForm();
        ui->tabWidget_emp->setCurrentIndex(0);
    } else {
        QMessageBox::critical(this, "Erreur",
            "Echec de l'ajout.\n" + e.getLastError());
    }
}

