void smartcarpentry::on_btn_emp_edit_clicked()
{
    QMessageBox::information(
        this,
        "Modification",
        "La modification des employes se fait uniquement dans le tableau (edition des cellules).\n"
        "Le mot de passe se modifie uniquement dans Parametres pour l'utilisateur courant.");
}

// ============================================================
//  CRUD - Delete Employee
// ============================================================

void smartcarpentry::on_btn_emp_del_clicked()
{
    if (selectedEmpId <= 0) {
        QMessageBox::warning(this, "Erreur", "Veuillez selectionner un employe a supprimer.");
        return;
    }

    int id = selectedEmpId;

    // Confirm deletion
    QMessageBox::StandardButton reply = QMessageBox::question(
        this, "Confirmation",
        QString("Voulez-vous vraiment supprimer l'employee #%1 ?").arg(id),
        QMessageBox::Yes | QMessageBox::No
    );
    if (reply != QMessageBox::Yes) return;

    Employee e;
    if (e.supprimer(id)) {
        QMessageBox::information(this, "Succes", "Employe supprime avec succes !");
        QTimer::singleShot(0, this, [this]() { refreshEmployeeTable(); });
        clearEmployeeForm();
    } else {
        QMessageBox::critical(this, "Erreur",
            "Echec de la suppression.\n" + e.getLastError());
    }
}

