    QComboBox *contractInput = new QComboBox();
    contractInput->addItem("(Aucun)", "");
    contractInput->addItem("CDI", "CDI");
    contractInput->addItem("CDD", "CDD");
    contractInput->addItem("STAGE", "STAGE");
