    QDoubleSpinBox *salaryInput = new QDoubleSpinBox();
    salaryInput->setDecimals(2);
    salaryInput->setRange(0.0, 100000000.0);
    salaryInput->setSingleStep(1000.0);

    QComboBox *roleInput = new QComboBox();
    roleInput->addItems({"ADMIN", "DESIGNER", "CHEF_ATELIER", "ENGINEER", "RH", "MENUISIER"});
    const int roleIndex = roleInput->findText(role, Qt::MatchFixedString);
    if (roleIndex >= 0) {
        roleInput->setCurrentIndex(roleIndex);
    }

    QComboBox *skillNameInput = new QComboBox();
    skillNameInput->addItems(allowedEmployeeSkills());

    QComboBox *skillLevelInput = new QComboBox();
    skillLevelInput->addItem("CERTIFIE", "CERTIFIE");
    skillLevelInput->addItem("EN_FORMATION", "EN_FORMATION");
    skillLevelInput->addItem("NON_QUALIFIE", "NON_QUALIFIE");

    QLabel *skillExpirationLabel = new QLabel("Date d'expiration :");
    QDateEdit *skillExpirationInput = new QDateEdit(QDate::currentDate());
    skillExpirationInput->setCalendarPopup(true);
    skillExpirationInput->setDisplayFormat("dd/MM/yyyy");

    QTableWidget *skillTable = new QTableWidget(0, 4);
    skillTable->setHorizontalHeaderLabels({"Competence", "Niveau", "Expiration", "Action"});
    skillTable->setEditTriggers(QAbstractItemView::NoEditTriggers);
    skillTable->setSelectionBehavior(QAbstractItemView::SelectRows);
    skillTable->setSelectionMode(QAbstractItemView::SingleSelection);
    skillTable->horizontalHeader()->setStretchLastSection(true);
    skillTable->verticalHeader()->setVisible(false);
    skillTable->setMinimumHeight(165);

    auto syncSkillExpirationUi = [skillLevelInput, skillExpirationLabel, skillExpirationInput]() {
        const bool isCertified = skillLevelInput->currentData().toString().toUpper() == "CERTIFIE";
        skillExpirationLabel->setVisible(isCertified);
        skillExpirationInput->setVisible(isCertified);
        skillExpirationInput->setEnabled(isCertified);
    };
    syncSkillExpirationUi();
    connect(skillLevelInput, &QComboBox::currentTextChanged, &dialog, [syncSkillExpirationUi]() {
        syncSkillExpirationUi();
    });

    QPushButton *addSkillButton = new QPushButton("Ajouter competence");
    QPushButton *clearSkillsButton = new QPushButton("Vider la liste");

    auto appendSkillRow = [&dialog, skillTable, skillNameInput, skillLevelInput, skillExpirationInput]() {
        const QString skillName = skillNameInput->currentText().trimmed();
        const QString skillLevel = skillLevelInput->currentData().toString().trimmed().toUpper();
        const bool requiresExpiration = skillLevel == "CERTIFIE";

        if (skillName.isEmpty()) {
            QMessageBox::warning(&dialog, "Competence", "Veuillez selectionner une competence.");
            return;
        }

        if (skillTable->findItems(skillName, Qt::MatchExactly).size() > 0) {
            QMessageBox::warning(&dialog, "Competence", "Cette competence est deja ajoutee a la liste.");
            return;
        }

        const int row = skillTable->rowCount();
        skillTable->insertRow(row);
        skillTable->setItem(row, 0, new QTableWidgetItem(skillName));
        skillTable->setItem(row, 1, new QTableWidgetItem(skillLevel));
        skillTable->setItem(row, 2, new QTableWidgetItem(requiresExpiration ? skillExpirationInput->date().toString("dd/MM/yyyy") : QString("-")));

        QWidget *actionContainer = new QWidget(skillTable);
        QHBoxLayout *actionLayout = new QHBoxLayout(actionContainer);
        actionLayout->setContentsMargins(0, 0, 0, 0);
        actionLayout->setSpacing(0);
        QPushButton *removeButton = new QPushButton("X", actionContainer);
        removeButton->setFixedSize(28, 28);
        removeButton->setStyleSheet("QPushButton { background: rgba(239,68,68,0.18); color: #fecaca; border-radius: 6px; border: 1px solid rgba(248,113,113,0.35); font-weight: bold; } QPushButton:hover { background: rgba(239,68,68,0.3); }");
        actionLayout->addWidget(removeButton);
        actionLayout->addStretch();
        skillTable->setCellWidget(row, 3, actionContainer);

        connect(removeButton, &QPushButton::clicked, &dialog, [skillTable, actionContainer]() {
            for (int r = 0; r < skillTable->rowCount(); ++r) {
                if (skillTable->cellWidget(r, 3) == actionContainer) {
                    skillTable->removeRow(r);
                    break;
                }
            }
        });
    };

    connect(addSkillButton, &QPushButton::clicked, &dialog, appendSkillRow);
    connect(clearSkillsButton, &QPushButton::clicked, &dialog, [skillTable]() {
        skillTable->setRowCount(0);
    });

    QString initialPhotoPath;
    QString initialFaceToken;
    const QString trimmedFaceValue = faceId.trimmed();
    if (trimmedFaceValue.startsWith(":/") || trimmedFaceValue.contains('/') || trimmedFaceValue.contains('\\')) {
        initialPhotoPath = trimmedFaceValue;
    } else {
        initialFaceToken = trimmedFaceValue;
    }

    QLineEdit *photoInput = new QLineEdit(initialPhotoPath);
    photoInput->setPlaceholderText("Photo profil (optionnel)");
    QLineEdit *faceTokenInput = new QLineEdit(initialFaceToken);
    faceTokenInput->setPlaceholderText("Face token (optionnel)");
