    formLayout->addWidget(new QLabel("CIN :"), 0, 0);
    formLayout->addWidget(cinInput, 0, 1);
    formLayout->addWidget(new QLabel("Email :"), 1, 0);
    formLayout->addWidget(mailInput, 1, 1);
    formLayout->addWidget(new QLabel("Mot de passe :"), 2, 0);
    formLayout->addWidget(passInput, 2, 1);
    formLayout->addWidget(new QLabel("Nom :"), 3, 0);
    formLayout->addWidget(nomInput, 3, 1);
    formLayout->addWidget(new QLabel("Prenom :"), 4, 0);
    formLayout->addWidget(prenomInput, 4, 1);
    formLayout->addWidget(new QLabel("Date de naissance :"), 5, 0);
    formLayout->addWidget(dateInput, 5, 1);
    formLayout->addWidget(new QLabel("Telephone :"), 6, 0);
    formLayout->addWidget(phoneInput, 6, 1);
    formLayout->addWidget(new QLabel("Date d'embauche :"), 7, 0);
    formLayout->addWidget(hireDateInput, 7, 1);
    formLayout->addWidget(new QLabel("Role :"), 8, 0);
    formLayout->addWidget(roleInput, 8, 1);
    formLayout->addWidget(new QLabel("Contrat :"), 9, 0);
    formLayout->addWidget(contractInput, 9, 1);
