void smartcarpentry::applyAffectationPagination()
{
    auto applyOne = [](QTableView *table,
                       int &currentPage,
                       int pageSize,
                       QLabel *pageLabel,
                       QPushButton *prevButton,
                       QPushButton *nextButton) {
        if (!table || !table->model()) {
            if (pageLabel) pageLabel->setText("Page 0/0");
            if (prevButton) prevButton->setEnabled(false);
            if (nextButton) nextButton->setEnabled(false);
            return;
        }

        const int totalRows = table->model()->rowCount();
        const int safePageSize = qMax(1, pageSize);
        const int totalPages = qMax(1, (totalRows + safePageSize - 1) / safePageSize);
        currentPage = qBound(0, currentPage, totalPages - 1);

        const int startRow = currentPage * safePageSize;
        const int endRowExclusive = qMin(startRow + safePageSize, totalRows);

        for (int row = 0; row < totalRows; ++row) {
            table->setRowHidden(row, row < startRow || row >= endRowExclusive);
        }

        if (pageLabel) {
            if (totalRows <= 0) {
                pageLabel->setText("Page 0/0");
            } else {
                pageLabel->setText(
                    QString("Page %1/%2 (%3-%4/%5)")
                        .arg(currentPage + 1)
                        .arg(totalPages)
                        .arg(startRow + 1)
                        .arg(endRowExclusive)
                        .arg(totalRows));
            }
        }

        if (prevButton) prevButton->setEnabled(currentPage > 0);
        if (nextButton) nextButton->setEnabled(currentPage < (totalPages - 1));
    };

    applyOne(ui->tv_affect_emp,
             affectEmpCurrentPage,
             affectEmpPageSize,
             affectEmpPageLabel,
             affectEmpPrevButton,
             affectEmpNextButton);

    applyOne(ui->tv_affect_fab,
             affectFabCurrentPage,
             affectFabPageSize,
             affectFabPageLabel,
             affectFabPrevButton,
             affectFabNextButton);
}

