void smartcarpentry::refreshAffectationSkillFilters()
{
    if (!affectSkillFilterCombo) {
        return;
    }

    const QString previousData = affectSkillFilterCombo->currentData().toString();
    QSignalBlocker blocker(affectSkillFilterCombo);
    affectSkillFilterCombo->clear();
    affectSkillFilterCombo->addItem("Toutes competences", "");

    QSqlQuery query;
    query.prepare(
        "SELECT DISTINCT UPPER(TRIM(NOM_COMPETENCE)) "
        "FROM EMPLOYEE_SKILL "
        "WHERE NOM_COMPETENCE IS NOT NULL "
        "ORDER BY 1");

    if (query.exec()) {
        while (query.next()) {
            const QString skill = query.value(0).toString().trimmed();
            if (!skill.isEmpty()) {
                affectSkillFilterCombo->addItem(skill, skill);
            }
        }
    }

    int restoreIndex = affectSkillFilterCombo->findData(previousData);
    if (restoreIndex < 0) {
        restoreIndex = 0;
    }
    affectSkillFilterCombo->setCurrentIndex(restoreIndex);
}

void smartcarpentry::refreshAffectationSkillMatrix()
{
    if (!affectSkillMatrixTable) {
        return;
    }

    QStringList skills;
    {
        QSqlQuery skillQuery;
        skillQuery.prepare(
            "SELECT DISTINCT UPPER(TRIM(NOM_COMPETENCE)) "
            "FROM EMPLOYEE_SKILL "
            "WHERE NOM_COMPETENCE IS NOT NULL "
            "ORDER BY 1");
        if (skillQuery.exec()) {
            while (skillQuery.next()) {
                const QString skill = skillQuery.value(0).toString().trimmed();
                if (!skill.isEmpty()) {
                    skills << skill;
                }
            }
        }
    }

    QVector<QPair<int, QString>> employees;
    {
        QSqlQuery empQuery;
        empQuery.prepare(
            "SELECT IDEMPLOYEE, TRIM(NOM) || ' ' || TRIM(PRENOM) "
            "FROM EMPLOYEE "
            "ORDER BY IDEMPLOYEE");
        if (empQuery.exec()) {
            while (empQuery.next()) {
                employees.append({empQuery.value(0).toInt(), empQuery.value(1).toString().trimmed()});
            }
        }
    }

    affectSkillMatrixTable->clear();
    affectSkillMatrixTable->setRowCount(employees.size());
    affectSkillMatrixTable->setColumnCount(skills.size() + 1);

    QStringList headers;
    headers << "Employe";
    headers.append(skills);
    affectSkillMatrixTable->setHorizontalHeaderLabels(headers);

    QHash<int, int> employeeRow;
    for (int r = 0; r < employees.size(); ++r) {
        employeeRow.insert(employees.at(r).first, r);
        QTableWidgetItem *nameItem = new QTableWidgetItem(employees.at(r).second);
        nameItem->setData(Qt::UserRole, employees.at(r).first);
        nameItem->setBackground(QColor("#1f2937"));
        nameItem->setForeground(QColor("#e5e7eb"));
        affectSkillMatrixTable->setItem(r, 0, nameItem);

        for (int c = 0; c < skills.size(); ++c) {
            QTableWidgetItem *emptyItem = new QTableWidgetItem("-");
            emptyItem->setTextAlignment(Qt::AlignCenter);
            emptyItem->setForeground(QColor("#9ca3af"));
            emptyItem->setData(Qt::UserRole, 0);
            affectSkillMatrixTable->setItem(r, c + 1, emptyItem);
        }
    }

    QHash<QString, int> skillCol;
    for (int c = 0; c < skills.size(); ++c) {
        skillCol.insert(skills.at(c), c + 1);
    }

    QSqlQuery matrixQuery;
    matrixQuery.prepare(
        "SELECT IDEMPLOYEE, UPPER(TRIM(NOM_COMPETENCE)), UPPER(NIVEAU_MAITRISE), "
        "CASE WHEN DATE_EXPIRATION IS NOT NULL AND DATE_EXPIRATION < TRUNC(SYSDATE) THEN 1 ELSE 0 END AS EXPIRED, "
        "TO_CHAR(DATE_EXPIRATION, 'DD/MM/YYYY') "
        "FROM EMPLOYEE_SKILL");

    if (matrixQuery.exec()) {
        while (matrixQuery.next()) {
            const int employeeId = matrixQuery.value(0).toInt();
            const QString skill = matrixQuery.value(1).toString().trimmed();
            const QString level = canonicalEmployeeSkillLevel(matrixQuery.value(2).toString());
            const bool expired = matrixQuery.value(3).toInt() == 1;
            const QString expirationText = matrixQuery.value(4).toString().trimmed();

            if (!employeeRow.contains(employeeId) || !skillCol.contains(skill)) {
                continue;
            }

            const int row = employeeRow.value(employeeId);
            const int col = skillCol.value(skill);
            QTableWidgetItem *item = affectSkillMatrixTable->item(row, col);
            if (!item) {
                item = new QTableWidgetItem();
                affectSkillMatrixTable->setItem(row, col, item);
            }

            int rank = 1;
            QColor bg = QColor("#374151");
            QColor fg = QColor("#f3f4f6");
            QString label = level;

            if (level == "CERTIFIE" && !expired) {
                rank = 4;
                bg = QColor("#14532d");
                fg = QColor("#dcfce7");
                label = "CERTIFIE";
            } else if (level == "CERTIFIE" && expired) {
                rank = 3;
                bg = QColor("#7c2d12");
                fg = QColor("#fed7aa");
                label = "CERTIFIE (EXP.)";
            } else if (level == "EN_FORMATION") {
                rank = 2;
                bg = QColor("#713f12");
                fg = QColor("#fef3c7");
            } else if (level == "NON_QUALIFIE") {
                rank = 1;
                bg = QColor("#7f1d1d");
                fg = QColor("#fecaca");
            }

            const int currentRank = item->data(Qt::UserRole).toInt();
            if (rank < currentRank) {
                continue;
            }

            item->setData(Qt::UserRole, rank);
            item->setText(label);
            item->setTextAlignment(Qt::AlignCenter);
            item->setBackground(bg);
            item->setForeground(fg);
            item->setToolTip(expirationText.isEmpty()
                                 ? QString("Niveau %1").arg(level)
                                 : QString("Niveau %1\nExpiration: %2").arg(level, expirationText));
        }
    }
}

void smartcarpentry::refreshAffectationEmployeeSkills(int employeeId)
{
    if (!affectEmployeeSkillsTable) {
        return;
    }

    affectEmployeeSkillsTable->clearContents();
    affectEmployeeSkillsTable->setRowCount(0);

    if (employeeId <= 0) {
        if (affectEmployeeSkillsLabel) {
            affectEmployeeSkillsLabel->setText("Competences de l'employe selectionne : aucune selection");
        }
        return;
    }

    QString employeeLabel = QString("#%1").arg(employeeId);
    QSqlQuery nameQuery;
    nameQuery.prepare("SELECT TRIM(NOM) || ' ' || TRIM(PRENOM) FROM EMPLOYEE WHERE IDEMPLOYEE = :id");
    nameQuery.bindValue(":id", employeeId);
    if (nameQuery.exec() && nameQuery.next()) {
        const QString name = nameQuery.value(0).toString().trimmed();
        if (!name.isEmpty()) {
            employeeLabel = QString("%1 (%2)").arg(name, QString::number(employeeId));
        }
    }

    if (affectEmployeeSkillsLabel) {
        affectEmployeeSkillsLabel->setText(
            QString("Competences de l'employe selectionne : %1").arg(employeeLabel));
    }

    QSqlQuery query;
    query.prepare(
        "SELECT NOM_COMPETENCE, NIVEAU_MAITRISE, "
        "TO_CHAR(DATE_EXPIRATION, 'DD/MM/YYYY'), "
        "CASE WHEN DATE_EXPIRATION IS NOT NULL AND DATE_EXPIRATION < TRUNC(SYSDATE) THEN 'EXPIREE' ELSE 'ACTIVE' END "
        "FROM EMPLOYEE_SKILL WHERE IDEMPLOYEE = :id ORDER BY UPPER(NOM_COMPETENCE)");
    query.bindValue(":id", employeeId);
    if (!query.exec()) {
        qWarning() << "Erreur chargement competences employe:" << query.lastError().text();
        if (affectEmployeeSkillsLabel) {
            affectEmployeeSkillsLabel->setText(
                QString("Competences de l'employe selectionne : %1 - erreur de chargement").arg(employeeLabel));
        }
        return;
    }

    int row = 0;
    while (query.next()) {
        affectEmployeeSkillsTable->insertRow(row);

        const QString skill = query.value(0).toString().trimmed();
        const QString level = canonicalEmployeeSkillLevel(query.value(1).toString());
        const QString expiration = query.value(2).toString().trimmed();
        const QString rawStatus = query.value(3).toString().trimmed().toUpper();
        const QString status = (rawStatus == "EXPIREE") ? QString::fromUtf8("EXPIREE") : QString("ACTIVE");

        QTableWidgetItem *skillItem = new QTableWidgetItem(skill);
        QTableWidgetItem *levelItem = new QTableWidgetItem(level);
        QTableWidgetItem *expirationItem = new QTableWidgetItem(expiration.isEmpty() ? QString("-") : expiration);
        QTableWidgetItem *statusItem = new QTableWidgetItem(status);

        skillItem->setTextAlignment(Qt::AlignCenter);
        levelItem->setTextAlignment(Qt::AlignCenter);
        expirationItem->setTextAlignment(Qt::AlignCenter);
        statusItem->setTextAlignment(Qt::AlignCenter);

        if (rawStatus == "EXPIREE") {
            statusItem->setForeground(QColor("#fca5a5"));
        } else {
            statusItem->setForeground(QColor("#86efac"));
        }

        affectEmployeeSkillsTable->setItem(row, 0, skillItem);
        affectEmployeeSkillsTable->setItem(row, 1, levelItem);
        affectEmployeeSkillsTable->setItem(row, 2, expirationItem);
        affectEmployeeSkillsTable->setItem(row, 3, statusItem);
        ++row;
    }

    if (row == 0 && affectEmployeeSkillsLabel) {
        affectEmployeeSkillsLabel->setText(
            QString("Competences de l'employe selectionne : %1 - aucune competence enregistree").arg(employeeLabel));
    }
}

QString smartcarpentry::inferRequiredSkillForFabrication(int, const QString &modeleName) const
{
    const QString key = modeleName.toLower();
    if (key.contains("finish") || key.contains("fini") || key.contains("vernis")) {
        return "FINISHING";
    }
    if (key.contains("cnc")) {
        return "CNC";
    }
    if (key.contains("join") || key.contains("assembl") || key.contains("menuis")) {
        return "JOINERY";
    }
    if (key.contains("plan")) {
        return "PLANIFICATION";
    }
    if (key.contains("gest")) {
        return "GESTION";
    }
    return QString();
}

bool smartcarpentry::validateEmployeeSkillForAssignment(int employeeId,
                                                        const QString &skillName,
                                                        const QString &requiredLevel,
                                                        QString &errorMessage,
                                                        bool &expiredCertificate) const
{
    errorMessage.clear();
    expiredCertificate = false;

    const QString normalizedSkill = skillName.trimmed().toUpper();
    if (employeeId <= 0 || normalizedSkill.isEmpty()) {
        return true;
    }

    const QString normalizedLevel = requiredLevel.trimmed().toUpper().isEmpty()
                                        ? QString("CERTIFIE")
                                        : requiredLevel.trimmed().toUpper();

    QSqlQuery query;
    query.prepare(
        "SELECT UPPER(NIVEAU_MAITRISE), "
        "CASE WHEN DATE_EXPIRATION IS NOT NULL AND DATE_EXPIRATION < TRUNC(SYSDATE) THEN 1 ELSE 0 END AS EXPIRED, "
        "TO_CHAR(DATE_EXPIRATION, 'DD/MM/YYYY') "
        "FROM EMPLOYEE_SKILL "
        "WHERE IDEMPLOYEE = :empId AND UPPER(TRIM(NOM_COMPETENCE)) = :skill");
    query.bindValue(":empId", employeeId);
    query.bindValue(":skill", normalizedSkill);

    if (!query.exec()) {
        errorMessage = "Impossible de verifier la competence de l'employe.";
        return false;
    }

    bool hasAnySkill = false;
    bool hasRequiredLevel = false;
    bool hasValidCertification = false;
    QString expiredDate;

    while (query.next()) {
        hasAnySkill = true;
        const QString level = query.value(0).toString().trimmed();
        const bool expired = query.value(1).toInt() == 1;
        const QString expiration = query.value(2).toString().trimmed();

        if (level == "CERTIFIE" && expired) {
            expiredCertificate = true;
            if (expiredDate.isEmpty()) {
                expiredDate = expiration;
            }
        }

        if (normalizedLevel == "CERTIFIE") {
            if (level == "CERTIFIE" && !expired) {
                hasValidCertification = true;
            }
        } else if (level == normalizedLevel) {
            hasRequiredLevel = true;
        }
    }

    if (normalizedLevel == "CERTIFIE") {
        if (hasValidCertification) {
            return true;
        }
        if (expiredCertificate) {
            errorMessage = expiredDate.isEmpty()
                               ? QString("Certification expire pour %1.").arg(normalizedSkill)
                               : QString("Certification expire pour %1 (expiration: %2).").arg(normalizedSkill, expiredDate);
            return false;
        }
        errorMessage = hasAnySkill
                           ? QString("Employe non certifie sur %1.").arg(normalizedSkill)
                           : QString("Employe sans competence %1.").arg(normalizedSkill);
        return false;
    }

    if (normalizedLevel.isEmpty() || normalizedLevel == "TOUS") {
        if (hasAnySkill) {
            return true;
        }
        errorMessage = QString("Employe sans competence %1.").arg(normalizedSkill);
        return false;
    }

    if (hasRequiredLevel) {
        return true;
    }

    errorMessage = QString("Niveau %1 requis sur %2.").arg(normalizedLevel, normalizedSkill);
    return false;
}

void smartcarpentry::refreshAffectationTables()
{
    refreshAffectationSkillFilters();

    const QString selectedSkill = affectSkillFilterCombo
                                      ? affectSkillFilterCombo->currentData().toString().trimmed().toUpper()
                                      : QString();
    const QString selectedLevel = affectSkillLevelCombo
                                      ? affectSkillLevelCombo->currentData().toString().trimmed().toUpper()
                                      : QString();

    // ---- Employee table (with current fabrication assignment) ----
    QSqlQueryModel *empModel = new QSqlQueryModel(this);
    QString empSql =
        "SELECT E.IDEMPLOYEE, E.CIN, E.NOM, E.PRENOM, E.ROLE, "
        "E.IDFABRICATION, "
        "CASE WHEN E.IDFABRICATION IS NOT NULL "
        "     THEN 'Fab #' || E.IDFABRICATION "
        "          || ' - ' || NVL(M.NOM_MODELE, '?') "
        "          || ' [' || NVL(F.ETAT_FABRICATION, '?') || ']' "
        "     ELSE 'Non affecte' END AS AFFECTATION, ";

    if (selectedSkill.isEmpty()) {
        empSql += "'Aucun filtre' AS STATUT_COMPETENCE ";
    } else {
        empSql +=
            "CASE "
            " WHEN EXISTS (SELECT 1 FROM EMPLOYEE_SKILL ES "
            "              WHERE ES.IDEMPLOYEE = E.IDEMPLOYEE "
            "                AND UPPER(TRIM(ES.NOM_COMPETENCE)) = :skillName "
            "                AND UPPER(ES.NIVEAU_MAITRISE) = 'CERTIFIE' "
            "                AND (ES.DATE_EXPIRATION IS NULL OR ES.DATE_EXPIRATION >= TRUNC(SYSDATE))) "
            " THEN 'CERTIFIE' "
            " WHEN EXISTS (SELECT 1 FROM EMPLOYEE_SKILL ES "
            "              WHERE ES.IDEMPLOYEE = E.IDEMPLOYEE "
            "                AND UPPER(TRIM(ES.NOM_COMPETENCE)) = :skillName "
            "                AND UPPER(ES.NIVEAU_MAITRISE) = 'CERTIFIE' "
            "                AND ES.DATE_EXPIRATION < TRUNC(SYSDATE)) "
            " THEN 'CERTIFICATION EXPIREE' "
            " WHEN EXISTS (SELECT 1 FROM EMPLOYEE_SKILL ES "
            "              WHERE ES.IDEMPLOYEE = E.IDEMPLOYEE "
            "                AND UPPER(TRIM(ES.NOM_COMPETENCE)) = :skillName "
            "                AND UPPER(ES.NIVEAU_MAITRISE) = 'EN_FORMATION') "
            " THEN 'EN_FORMATION' "
            " WHEN EXISTS (SELECT 1 FROM EMPLOYEE_SKILL ES "
            "              WHERE ES.IDEMPLOYEE = E.IDEMPLOYEE "
            "                AND UPPER(TRIM(ES.NOM_COMPETENCE)) = :skillName "
            "                AND UPPER(ES.NIVEAU_MAITRISE) = 'NON_QUALIFIE') "
            " THEN 'NON_QUALIFIE' "
            " ELSE 'ABSENT' END AS STATUT_COMPETENCE ";
    }

    empSql +=
        "FROM EMPLOYEE E "
        "LEFT JOIN FABRICATION F ON F.IDFABRICATION = E.IDFABRICATION "
        "LEFT JOIN MODELE M ON M.IDMODELE = F.IDMODELE "
        "WHERE 1=1 ";

    if (!selectedSkill.isEmpty()) {
        empSql +=
            "AND EXISTS (SELECT 1 FROM EMPLOYEE_SKILL FS "
            "            WHERE FS.IDEMPLOYEE = E.IDEMPLOYEE "
            "              AND UPPER(TRIM(FS.NOM_COMPETENCE)) = :filterSkill ";
        if (selectedLevel == "CERTIFIE") {
            empSql +=
                "              AND UPPER(FS.NIVEAU_MAITRISE) = 'CERTIFIE' "
                "              AND (FS.DATE_EXPIRATION IS NULL OR FS.DATE_EXPIRATION >= TRUNC(SYSDATE))";
        } else if (!selectedLevel.isEmpty()) {
            empSql += "              AND UPPER(FS.NIVEAU_MAITRISE) = :filterLevel";
        }
        empSql += ") ";
    }

    empSql += "ORDER BY E.IDEMPLOYEE";

    QSqlQuery empQuery;
    empQuery.prepare(empSql);
    if (!selectedSkill.isEmpty()) {
        empQuery.bindValue(":skillName", selectedSkill);
        empQuery.bindValue(":filterSkill", selectedSkill);
        if (!selectedLevel.isEmpty() && selectedLevel != "CERTIFIE") {
            empQuery.bindValue(":filterLevel", selectedLevel);
        }
    }
    empQuery.exec();
    empModel->setQuery(std::move(empQuery));

    empModel->setHeaderData(0, Qt::Horizontal, "ID");
    empModel->setHeaderData(1, Qt::Horizontal, "CIN");
    empModel->setHeaderData(2, Qt::Horizontal, "Nom");
    empModel->setHeaderData(3, Qt::Horizontal, "Prenom");
    empModel->setHeaderData(4, Qt::Horizontal, "Role");
    empModel->setHeaderData(5, Qt::Horizontal, "ID Fab");
    empModel->setHeaderData(6, Qt::Horizontal, "Affectation");
    empModel->setHeaderData(7, Qt::Horizontal, "Statut competence");

    QSortFilterProxyModel *empProxy = new QSortFilterProxyModel(this);
    empProxy->setSourceModel(empModel);
    empProxy->setFilterCaseSensitivity(Qt::CaseInsensitive);
    empProxy->setFilterKeyColumn(-1);

    if (ui->tv_affect_emp->model()) ui->tv_affect_emp->model()->deleteLater();
    ui->tv_affect_emp->setModel(empProxy);
    ui->tv_affect_emp->setColumnHidden(5, true); 
    ui->tv_affect_emp->setSelectionBehavior(QAbstractItemView::SelectRows);
    applyGlobalPremiumStyle(ui->tv_affect_emp, nullptr);
    ui->tv_affect_emp->setSelectionMode(QAbstractItemView::ExtendedSelection);
    ui->tv_affect_emp->resizeColumnsToContents();
    ui->tv_affect_emp->horizontalHeader()->setStretchLastSection(true);

    if (ui->tv_affect_emp->selectionModel()) {
        connect(ui->tv_affect_emp->selectionModel(), &QItemSelectionModel::selectionChanged, this, [this]() {
            int employeeId = 0;
            if (ui->tv_affect_emp && ui->tv_affect_emp->selectionModel()) {
                const QModelIndexList rows = ui->tv_affect_emp->selectionModel()->selectedRows(0);
                if (!rows.isEmpty()) {
                    employeeId = ui->tv_affect_emp->model()->data(rows.first(), Qt::DisplayRole).toInt();
                }
            }
            refreshAffectationEmployeeSkills(employeeId);
        });
    }

    if (affectSkillHintLabel) {
        if (selectedSkill.isEmpty()) {
            affectSkillHintLabel->setText("Filtrez par competence pour pre-valider l'affectation.");
        } else {
            const QString levelLabel = selectedLevel.isEmpty() ? QString("Tous niveaux") : selectedLevel;
            affectSkillHintLabel->setText(
                QString("Filtre actif: %1 (%2). Les certifications expirees sont signalees.")
                    .arg(selectedSkill, levelLabel));
        }
    }

    // ---- Fabrication table ----
    QSqlQueryModel *fabModel = new QSqlQueryModel(this);
    fabModel->setQuery(
        "SELECT F.IDFABRICATION, "
        "TO_CHAR(F.DATE_DEBUT, 'DD/MM/YYYY') AS DATE_DEBUT, "
        "F.ETAT_FABRICATION, F.NB_PERSONNES, "
        "M.NOM_MODELE, "
        "(SELECT COUNT(*) FROM EMPLOYEE E2 WHERE E2.IDFABRICATION = F.IDFABRICATION) AS NB_AFFECTES "
        "FROM FABRICATION F "
        "LEFT JOIN MODELE M ON F.IDMODELE = M.IDMODELE "
        "ORDER BY F.IDFABRICATION"
    );
    fabModel->setHeaderData(0, Qt::Horizontal, "ID fab");
    fabModel->setHeaderData(1, Qt::Horizontal, "Date debut");
    fabModel->setHeaderData(2, Qt::Horizontal, "Etat");
    fabModel->setHeaderData(3, Qt::Horizontal, "Nombre de personnes");
    fabModel->setHeaderData(4, Qt::Horizontal, "Modele");
    fabModel->setHeaderData(5, Qt::Horizontal, "Affectes");

    QSortFilterProxyModel *fabProxy = new QSortFilterProxyModel(this);
    fabProxy->setSourceModel(fabModel);
    fabProxy->setFilterCaseSensitivity(Qt::CaseInsensitive);
    fabProxy->setFilterKeyColumn(-1);

    if (ui->tv_affect_fab->model()) ui->tv_affect_fab->model()->deleteLater();
    ui->tv_affect_fab->setModel(fabProxy);
    ui->tv_affect_fab->setSelectionBehavior(QAbstractItemView::SelectRows);
    ui->tv_affect_fab->setSelectionMode(QAbstractItemView::SingleSelection);
    applyGlobalPremiumStyle(ui->tv_affect_fab, nullptr);
    ui->tv_affect_fab->resizeColumnsToContents();
    ui->tv_affect_fab->horizontalHeader()->setStretchLastSection(true);

    int selectedEmployeeId = 0;
    if (ui->tv_affect_emp && ui->tv_affect_emp->selectionModel()) {
        const QModelIndexList rows = ui->tv_affect_emp->selectionModel()->selectedRows(0);
        if (!rows.isEmpty()) {
            selectedEmployeeId = ui->tv_affect_emp->model()->data(rows.first(), Qt::DisplayRole).toInt();
        }
    }
    refreshAffectationEmployeeSkills(selectedEmployeeId);

    refreshAffectationSkillMatrix();
    applyAffectationPagination();
}

// ============================================================
//  Affectation: Assign employee to fabrication
// ============================================================

void smartcarpentry::on_btn_emp_affect_clicked()
{
    struct EmployeeSelection {
        int id = 0;
        QString nom;
        QString prenom;
    };

    QVector<EmployeeSelection> selectedEmployees;
    if (ui->tv_affect_emp->selectionModel()) {
        const QModelIndexList empRows = ui->tv_affect_emp->selectionModel()->selectedRows(0);
        QSet<int> uniqueIds;
        QAbstractItemModel *empModel = ui->tv_affect_emp->model();
        for (const QModelIndex &rowIndex : empRows) {
            const int empRow = rowIndex.row();
            const int empId = empModel->data(empModel->index(empRow, 0)).toInt();
            if (empId <= 0 || uniqueIds.contains(empId)) {
                continue;
            }
            uniqueIds.insert(empId);

            EmployeeSelection employee;
            employee.id = empId;
            employee.nom = empModel->data(empModel->index(empRow, 2)).toString();
            employee.prenom = empModel->data(empModel->index(empRow, 3)).toString();
            selectedEmployees.append(employee);
        }
    }

    // Get selected fabrication
    QModelIndex fabIndex;
    if (ui->tv_affect_fab->selectionModel()) {
        const QModelIndexList fabRows = ui->tv_affect_fab->selectionModel()->selectedRows(0);
        if (!fabRows.isEmpty()) {
            fabIndex = fabRows.first();
        }
    }

    if (!fabIndex.isValid()) {
        QMessageBox::warning(this, "Erreur", "Veuillez selectionner une tache de fabrication.");
        return;
    }

    QAbstractItemModel *fabModel = ui->tv_affect_fab->model();
    int fabRow = fabIndex.row();
    int fabId = fabModel->data(fabModel->index(fabRow, 0)).toInt();
    const QString modeleName = fabModel->data(fabModel->index(fabRow, 4)).toString().trimmed();

    if (selectedEmployees.isEmpty()) {
        double taskX = 0.0;
        double taskY = 0.0;
        if (!Employee::pointTacheDepuisFabrication(fabId, taskX, taskY)) {
            QMessageBox::warning(this,
                                 "Affectation intelligente",
                                 "Impossible de calculer le profil de la fabrication selectionnee.");
            return;
        }

        QString roleFilter = "Tous";
        if (ui->combo_filter_role) {
            roleFilter = ui->combo_filter_role->currentText();
        }

        EmployeeKnnRecommendation top;
        if (!Employee::proposerTopEmployePourFabrication(fabId, roleFilter, top)) {
            QMessageBox::warning(this,
                                 "Affectation intelligente",
                                 "Aucune suggestion disponible pour cette fabrication.");
            return;
        }

        const QMessageBox::StandardButton autoReply = QMessageBox::question(
            this,
            "Affectation intelligente",
                QString("Aucun employe selectionne.\n\n"
                    "Suggestion Top 1 : %1 %2 (ID %3, role %4)\n"
                    "Distance: %5\n\n"
                    "Voulez-vous l'affecter automatiquement a la fabrication #%6 ?")
                .arg(top.employee.prenom)
                .arg(top.employee.nom)
                .arg(top.employee.idEmployee)
                .arg(top.employee.role)
                .arg(QString::number(top.distance, 'f', 3))
                .arg(fabId),
            QMessageBox::Yes | QMessageBox::No,
            QMessageBox::Yes);

        if (autoReply != QMessageBox::Yes) {
            return;
        }

        EmployeeSelection suggested;
        suggested.id = top.employee.idEmployee;
        suggested.nom = top.employee.nom;
        suggested.prenom = top.employee.prenom;
        selectedEmployees.append(suggested);
    }

    if (selectedEmployees.isEmpty() || fabId <= 0) {
        QMessageBox::warning(this, "Erreur", "Selection invalide.");
        return;
    }

    QString requiredSkill = affectSkillFilterCombo
                                ? affectSkillFilterCombo->currentData().toString().trimmed().toUpper()
                                : QString();
    if (requiredSkill.isEmpty()) {
        requiredSkill = inferRequiredSkillForFabrication(fabId, modeleName);
    }

    const QString requiredLevel = affectSkillLevelCombo
                                      ? affectSkillLevelCombo->currentData().toString().trimmed().toUpper()
                                      : QString("CERTIFIE");

    if (!requiredSkill.isEmpty()) {
        QStringList validationErrors;
        for (const EmployeeSelection &employee : selectedEmployees) {
            QString validationError;
            bool expiredCertificate = false;
            if (!validateEmployeeSkillForAssignment(employee.id,
                                                    requiredSkill,
                                                    requiredLevel,
                                                    validationError,
                                                    expiredCertificate)) {
                const QString fullName = QString("%1 %2").arg(employee.prenom, employee.nom).trimmed();
                validationErrors << QString("- %1 (ID %2): %3")
                                        .arg(fullName.isEmpty() ? QString("Employe") : fullName)
                                        .arg(employee.id)
                                        .arg(validationError);
            }
        }

        if (!validationErrors.isEmpty()) {
            QMessageBox::warning(
                this,
                "Affectation bloquee",
                QString("Competence requise: %1\n\n%2")
                    .arg(requiredSkill)
                    .arg(validationErrors.join("\n")));
            return;
        }
    }

    // Confirm
    QString confirmationText;
    if (selectedEmployees.size() == 1) {
        const EmployeeSelection &employee = selectedEmployees.first();
        confirmationText = QString("Affecter %1 %2 a la fabrication #%3 ?")
                               .arg(employee.prenom, employee.nom)
                               .arg(fabId);
    } else {
        confirmationText = QString("Affecter %1 employes a la fabrication #%2 ?")
                               .arg(selectedEmployees.size())
                               .arg(fabId);
    }

    QMessageBox::StandardButton reply = QMessageBox::question(
        this, "Confirmation", confirmationText, QMessageBox::Yes | QMessageBox::No);
    if (reply != QMessageBox::Yes) return;

    int successCount = 0;
    QStringList failedEmployees;
    for (const EmployeeSelection &employee : selectedEmployees) {
        if (Employee::assignerAFabrication(employee.id, fabId)) {
            ++successCount;
            continue;
        }
        const QString fullName = QString("%1 %2").arg(employee.prenom, employee.nom).trimmed();
        failedEmployees << QString("%1 (ID %2)")
                       .arg(fullName.isEmpty() ? QString("Employe") : fullName)
                               .arg(employee.id);
    }

    if (successCount > 0) {
        refreshAffectationTables();
    }

    if (successCount == selectedEmployees.size()) {
        QMessageBox::information(
            this,
            "Succes",
            QString("%1 employe(s) affecte(s) a la fabrication #%2.")
                .arg(successCount)
                .arg(fabId));
    } else if (successCount > 0) {
        QMessageBox::warning(
            this,
            "Affectation partielle",
                QString("%1/%2 employe(s) affecte(s) a la fabrication #%3.\n\nEchecs:\n%4")
                .arg(successCount)
                .arg(selectedEmployees.size())
                .arg(fabId)
                .arg(failedEmployees.join("\n")));
    } else {
        QMessageBox::critical(
            this,
            "Erreur",
                QString("Echec de l'affectation pour %1 employe(s).")
                    .arg(selectedEmployees.size()));
    }
}

// ============================================================
//  Affectation: Remove employee assignment
// ============================================================

void smartcarpentry::on_btn_emp_unaffect_clicked()
{
    QModelIndex empIndex;
    if (ui->tv_affect_emp->selectionModel()) {
        const QModelIndexList empRows = ui->tv_affect_emp->selectionModel()->selectedRows(0);
        if (!empRows.isEmpty()) {
            empIndex = empRows.first();
        }
    }

    if (!empIndex.isValid()) {
        QMessageBox::warning(this, "Erreur", "Veuillez selectionner un employe a desaffecter.");
        return;
    }

    QAbstractItemModel *empModel = ui->tv_affect_emp->model();
    int empRow = empIndex.row();
    int empId = empModel->data(empModel->index(empRow, 0)).toInt();
    QString empNom = empModel->data(empModel->index(empRow, 2)).toString();
    QString empPrenom = empModel->data(empModel->index(empRow, 3)).toString();
    QVariant currentFab = empModel->data(empModel->index(empRow, 5));

    if (empId <= 0) {
        QMessageBox::warning(this, "Erreur", "Selection invalide.");
        return;
    }

    if (currentFab.isNull() || currentFab.toInt() == 0) {
        QMessageBox::information(this, "Info", "Cet employe n'est affecte a aucune fabrication.");
        return;
    }

    // Confirm
    QMessageBox::StandardButton reply = QMessageBox::question(
        this, "Confirmation",
        QString("Desaffecter %1 %2 de la fabrication #%3 ?")
            .arg(empPrenom, empNom).arg(currentFab.toInt()),
        QMessageBox::Yes | QMessageBox::No
    );
    if (reply != QMessageBox::Yes) return;

    // Remove fabrication assignment using Employee class method
    if (Employee::desaffecter(empId)) {
        QMessageBox::information(this, "Succes",
            QString("%1 %2 desaffecte(e) avec succes.").arg(empPrenom, empNom));
        refreshAffectationTables();
    } else {
        QMessageBox::critical(this, "Erreur",
            "echec de la desaffectation.");
    }
}

