// ============================================================
//  Helper: Refresh the Bois table view
// ============================================================

void smartcarpentry::setupBoisValidation()
{
    if (!ui->bois_nom) return;

    // 1. Name validation (1-50 chars, alphanumeric and some symbols)
    QRegularExpression nameRegex("^[a-zA-Z0-9\\s\\-_/]{1,50}$");
    ui->bois_nom->setValidator(new QRegularExpressionValidator(nameRegex, this));
    ui->bois_nom->setPlaceholderText("Ex: Chene Massif 18mm");

    // 2. Numerical constraints for dimensions
    ui->bois_longueur->setRange(0.01, 10000.0);
    ui->bois_longueur->setSuffix(" mm");

    ui->bois_largeur->setRange(0.01, 10000.0);
    ui->bois_largeur->setSuffix(" mm");

    // 3. Stock constraints
    ui->bois_quantite->setRange(0, 1000000);
    ui->bois_quantite->setSuffix(" pcs");

    // 4. Financial constraints
    ui->bois_prix->setRange(0.0, 1000000.0);
    ui->bois_prix->setSuffix(" TND");

    // 5. Visual feedback for the name field
    connect(ui->bois_nom, &QLineEdit::textChanged, this, [this](const QString &text){
        if (text.trimmed().isEmpty()) {
            ui->bois_nom->setStyleSheet("QLineEdit { border: 2px solid #ef4444; background: rgba(239, 68, 68, 0.05); }");
        } else {
            ui->bois_nom->setStyleSheet("");
        }
    });
}

void smartcarpentry::refreshBoisTable()
{
    // Use QStandardItemModel to allow inline editing on the QTableView
    QSqlQueryModel *queryModel = boisTmp.afficher();
    QStandardItemModel *standardModel = new QStandardItemModel(this);
    
    // Data columns first, then Actions column at the end
    standardModel->setColumnCount(queryModel->columnCount() + 1);
    for (int i = 0; i < queryModel->columnCount(); ++i) {
        QString headerText = queryModel->headerData(i, Qt::Horizontal).toString();
        if (headerText.toLower().contains("longueur")) headerText = "Longueur (m)";
        if (headerText.toLower().contains("largeur")) headerText = "Largeur (m)";
        standardModel->setHeaderData(i, Qt::Horizontal, headerText);
    }
    standardModel->setHeaderData(queryModel->columnCount(), Qt::Horizontal, "Actions");
    
    // Copy data (Actions is last)
    for (int r = 0; r < queryModel->rowCount(); ++r) {
        for (int c = 0; c < queryModel->columnCount(); ++c) {
            QStandardItem *item = new QStandardItem();
            QVariant val = queryModel->data(queryModel->index(r, c));
            item->setData(val, Qt::EditRole);
            item->setTextAlignment(Qt::AlignCenter);
            // Make ID column (index 0) and Date column (index 12) read-only
            if (c == 0 || c == 12) item->setFlags(item->flags() & ~Qt::ItemIsEditable);
            standardModel->setItem(r, c, item);
        }
        // Placeholder for Actions column at the end
        standardModel->setItem(r, queryModel->columnCount(), new QStandardItem()); 
    }

    QSortFilterProxyModel *proxyData = new QSortFilterProxyModel(this);
    proxyData->setSourceModel(standardModel);
    proxyData->setFilterCaseSensitivity(Qt::CaseInsensitive);
    proxyData->setFilterKeyColumn(-1);

    QSortFilterProxyModel *proxyFourn = new QSortFilterProxyModel(this);
    proxyFourn->setSourceModel(proxyData);
    proxyFourn->setFilterCaseSensitivity(Qt::CaseInsensitive);
    proxyFourn->setFilterKeyColumn(6);

    if (ui->tv_bois->model()) ui->tv_bois->model()->deleteLater();
    ui->tv_bois->setModel(proxyFourn);
    ui->tv_bois->setSortingEnabled(true);
    ui->tv_bois->setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Preferred);
    
    // ======== PAGINATION & COLUMNS ========
    boisCurrentPage = 0;
    boisPageSize = 10;
    applyBoisPagination();
    
    int actionsColIdx = standardModel->columnCount() - 1;

    // Hide original redundant Fournisseur filter
    ui->lb_filter_fournisseur->hide();
    ui->combo_filter_fournisseur->hide();
    
    // --- PREMIUM STYLING & DELEGATE ---
    applyGlobalPremiumStyle(ui->tv_bois, ui->search_bois, ui->btn_bois_list_add, ui->btn_bois_list_delete);
    ui->tv_bois->setItemDelegate(new WoodTableDelegate(this)); 

    if (ui->vl_bois_list) {
        ui->vl_bois_list->setContentsMargins(14, 12, 14, 12);
        ui->vl_bois_list->setSpacing(8);
        ui->vl_bois_list->setStretch(0, 0);
        ui->vl_bois_list->setStretch(1, 0);
        ui->vl_bois_list->setStretch(2, 1);
        ui->vl_bois_list->setStretch(3, 0);
        ui->vl_bois_list->setStretch(4, 0);
    }
    if (ui->hl_bois_actions) {
        ui->hl_bois_actions->setContentsMargins(0, 8, 0, 8);
        ui->hl_bois_actions->setSpacing(12);
    }
    if (ui->btn_bois_list_add) {
        ui->btn_bois_list_add->setMinimumHeight(42);
        ui->btn_bois_list_add->setMinimumWidth(130);
        ui->btn_bois_list_add->setMaximumWidth(170);
        ui->btn_bois_list_add->setSizePolicy(QSizePolicy::Preferred, QSizePolicy::Fixed);
    }
    if (ui->btn_bois_list_delete) {
        ui->btn_bois_list_delete->setMinimumHeight(42);
        ui->btn_bois_list_delete->setMinimumWidth(140);
        ui->btn_bois_list_delete->setSizePolicy(QSizePolicy::MinimumExpanding, QSizePolicy::Fixed);
    }
    if (ui->btn_bois_export_pdf) {
        ui->btn_bois_export_pdf->setMinimumHeight(42);
        ui->btn_bois_export_pdf->setMinimumWidth(120);
        ui->btn_bois_export_pdf->setMaximumWidth(155);
        ui->btn_bois_export_pdf->setSizePolicy(QSizePolicy::Preferred, QSizePolicy::Fixed);
    }

    // Corrige l'affichage des accents et des fleches de pagination
    if (ui->cb_bois_sort_field && ui->cb_bois_sort_field->count() > 1) {
        ui->cb_bois_sort_field->setItemText(1, "Quantite");
    }
    if (ui->cb_bois_sort_order && ui->cb_bois_sort_order->count() > 1) {
        ui->cb_bois_sort_order->setItemText(1, "Decroissant");
    }
    if (ui->btn_bois_prev) ui->btn_bois_prev->setText("<");
    if (ui->btn_bois_next) ui->btn_bois_next->setText(">");
    
    // Fix: specifically style the Export PDF button with premium orange gradient and correct padding
    ui->btn_bois_export_pdf->setStyleSheet(
        "QPushButton { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #b45309, stop:1 #f59e0b); color: white; border-radius: 10px; padding: 8px 25px; font-weight: bold; border: none; } "
        "QPushButton:hover { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #92400e, stop:1 #d97706); }"
    );

    // Keep table bounded so bottom action buttons remain visible
    ui->tv_bois->setMinimumHeight(220);
    ui->tv_bois->setMaximumHeight(430);
    ui->tv_bois->setVerticalScrollBarPolicy(Qt::ScrollBarAsNeeded);
    ui->tv_bois->setHorizontalScrollBarPolicy(Qt::ScrollBarAsNeeded);
    
    ui->tv_bois->setColumnHidden(0, true); // Hide ID
    
    // Hide extra columns (keeping Nom, Longueur, Largeur, Epaisseur, Quantite, Prix, Fournisseur)
    // Indexes: 0:ID, 1:Nom, 2:Long, 3:Larg, 4:Ep, 5:Quant, 6:Prix, 7:Fourn
    for (int i = 8; i < actionsColIdx; ++i) {
        ui->tv_bois->setColumnHidden(i, true); 
    }

    // --- HEADER STYLING ---
    QHeaderView *header = ui->tv_bois->horizontalHeader();
    header->setSectionsMovable(true);
    header->setSectionResizeMode(QHeaderView::Stretch); 
    header->setSectionResizeMode(actionsColIdx, QHeaderView::ResizeToContents);
    header->setStretchLastSection(false); 

    // Inline editing connections
    disconnect(standardModel, &QStandardItemModel::dataChanged, this, nullptr);
    connect(standardModel, &QStandardItemModel::dataChanged, this, [this](const QModelIndex &topLeft, const QModelIndex &) {
        QSortFilterProxyModel *p = qobject_cast<QSortFilterProxyModel *>(ui->tv_bois->model());
        if (!p) return;
        this->on_tv_bois_cellChanged(topLeft.row(), topLeft.column());
    });
    applyBoisPagination();

    // --- SORTING BAR CONNECTIONS ---
    auto applySorting = [this]() {
        QString field = ui->cb_bois_sort_field->currentText();
        int col = 1; // Default: Nom
        if (field == "Quantite") col = 5;
        else if (field == "Prix Unitaire") col = 6;
        else if (field == "Fournisseur") col = 7;
        
        Qt::SortOrder order = (ui->cb_bois_sort_order->currentText() == "Croissant") ? Qt::AscendingOrder : Qt::DescendingOrder;
        
        if (ui->tv_bois->model()) {
            ui->tv_bois->model()->sort(col, order);
            // Reset to first page
            boisCurrentPage = 0;
            // Trigger contextual search update with current text
            on_search_bois_textChanged(ui->search_bois->text());
        }
    };

    disconnect(ui->cb_bois_sort_field, nullptr, this, nullptr);
    disconnect(ui->cb_bois_sort_order, nullptr, this, nullptr);
    connect(ui->cb_bois_sort_field, &QComboBox::currentIndexChanged, this, applySorting);
    connect(ui->cb_bois_sort_order, &QComboBox::currentIndexChanged, this, applySorting);

    queryModel->deleteLater();
    loadPieceBoisOptions();
}

// ============================================================
//  Inline Editing (Direct Modification)
// ============================================================
void smartcarpentry::on_tv_bois_cellChanged(int row, int column)
{
    QSortFilterProxyModel *pFourn = qobject_cast<QSortFilterProxyModel *>(ui->tv_bois->model());
    if (!pFourn) return;
    QSortFilterProxyModel *pData = qobject_cast<QSortFilterProxyModel *>(pFourn->sourceModel());
    if (!pData) return;
    QStandardItemModel *model = qobject_cast<QStandardItemModel *>(pData->sourceModel());
    if (!model) return;

    int idBois = model->item(row, 0)->text().toInt();
    QString newValue = model->item(row, column)->text();
    QString colName;

    switch (column) {
        case 1: 
            if (!Bois::validerNomBois(newValue)) { QMessageBox::warning(this, "Erreur", "Nom invalide."); refreshBoisTable(); return; }
            colName = "NOMBOIS"; break;
        case 2: 
            if (!Bois::validerLongueur(newValue.toDouble())) { QMessageBox::warning(this, "Erreur", "Longueur invalide."); refreshBoisTable(); return; }
            colName = "LONGUEUR"; break;
        case 3: 
            if (!Bois::validerLargeur(newValue.toDouble())) { QMessageBox::warning(this, "Erreur", "Largeur invalide."); refreshBoisTable(); return; }
            colName = "LARGEUR"; break;
        case 4: 
            if (!Bois::validerEpaisseur(newValue.toDouble())) { QMessageBox::warning(this, "Erreur", "epaisseur invalide."); refreshBoisTable(); return; }
            colName = "EPAISSEUR"; break;
        case 5: 
            if (!Bois::validerQuantite(newValue.toInt())) { QMessageBox::warning(this, "Erreur", "Quantite invalide."); refreshBoisTable(); return; }
            colName = "QUANTITE"; break;
        case 6: 
            if (!Bois::validerPrixUnitaire(newValue.toDouble())) { QMessageBox::warning(this, "Erreur", "Prix invalide."); refreshBoisTable(); return; }
            colName = "PRIX_UNITAIRE"; break;
        case 7: 
            if (!Bois::validerFournisseur(newValue)) { QMessageBox::warning(this, "Erreur", "Fournisseur invalide."); refreshBoisTable(); return; }
            colName = "FOURNISSEUR"; break;
        case 8: colName = "RESISTANCE"; break;
        case 9: colName = "HUMIDITE_MAX"; break;
        case 10: colName = "USAGE_RECOMMANDE"; break;
        case 11: colName = "NOMBRE_NOEUDS"; break;
        case 12: colName = "CLASSE_QUALITE"; break;
        default: return;
    }

    QSqlQuery query;
    query.prepare(QString("UPDATE BOIS SET %1 = :val WHERE IDBOIS = :id").arg(colName));
    query.bindValue(":val", newValue);
    query.bindValue(":id", idBois);

    if (query.exec()) {
        qDebug() << "Inline edit success for ID:" << idBois << " Col:" << colName; ui->tv_bois->viewport()->update(); ui->tv_bois->repaint();
        QTimer::singleShot(0, this, [this]() { on_btn_bois_stats_refresh_clicked(); });
    } else {
        QMessageBox::warning(this, "Erreur", "Modification echouee: " + query.lastError().text());
        refreshBoisTable(); // Revert change visually
    }
}

// ============================================================
//  Helper: Clear the Bois form fields
// ============================================================

void smartcarpentry::clearBoisForm()
{
    if (ui->bois_nom) ui->bois_nom->clear();
    if (ui->bois_longueur) ui->bois_longueur->setValue(0.0);
    if (ui->bois_largeur) ui->bois_largeur->setValue(0.0);
    if (ui->bois_quantite) ui->bois_quantite->setValue(0);
    if (ui->bois_prix) ui->bois_prix->setValue(0.0);
    if (ui->bois_fournisseur) ui->bois_fournisseur->setCurrentIndex(0);
    selectedBoisId = -1;
}

// ============================================================
//  CRUD - Add Bois
// ============================================================

void smartcarpentry::on_btn_bois_add_clicked()
{
    QString nomBois      = ui->bois_nom->text().trimmed();
    double  longueur     = ui->bois_longueur->value();
    double  largeur      = ui->bois_largeur->value();
    int     quantite     = ui->bois_quantite->value();
    double  prixUnitaire = ui->bois_prix->value();
    QString fournisseur  = ui->bois_fournisseur->currentText().trimmed();

    // --- Input validation ---
    if (!Bois::validerNomBois(nomBois)) {
        QMessageBox::warning(this, "Erreur", "Nom du bois invalide (1-50 caracteres).");
        return;
    }
    if (!Bois::validerLongueur(longueur)) {
        QMessageBox::warning(this, "Erreur", "Longueur invalide (doit etre > 0).");
        return;
    }
    if (!Bois::validerLargeur(largeur)) {
        QMessageBox::warning(this, "Erreur", "Largeur invalide (doit etre > 0).");
        return;
    }
    if (!Bois::validerQuantite(quantite)) {
        QMessageBox::warning(this, "Erreur", "Quantite invalide (doit etre >= 0).");
        return;
    }
    if (!Bois::validerPrixUnitaire(prixUnitaire)) {
        QMessageBox::warning(this, "Erreur", "Prix unitaire invalide (doit etre >= 0).");
        return;
    }
    if (!Bois::validerFournisseur(fournisseur)) {
        QMessageBox::warning(this, "Erreur", "Fournisseur invalide (1-100 caracteres).");
        return;
    }

    Bois b;
    b.setNomBois(nomBois);
    b.setLongueur(longueur);
    b.setLargeur(largeur);
    b.setQuantite(quantite);
    b.setPrixUnitaire(prixUnitaire);
    b.setFournisseur(fournisseur);

    if (b.ajouter()) {
        QMessageBox::information(this, "Succes", "Bois ajoute avec succes !");
        insertEmployeeHistoryEntry(
            -1,
            "BOIS_CREATE",
            currentUserEmail,
            QString("Ajout bois: nom='%1', fournisseur='%2', qte=%3")
                .arg(nomBois)
                .arg(fournisseur)
                .arg(quantite));
        refreshBoisTable();
        clearBoisForm();
        ui->tabWidget_bois->setCurrentIndex(0);
    } else {
        QMessageBox::critical(this, "Erreur de validation",
            "echec de l'ajout :\n\n" + b.getLastError());
    }
}

