void smartcarpentry::setupFabricationAdvancedUi()
{
    if (fabricationAdvancedUiReady || !ui->tabWidget_fab) {
        return;
    }

    QWidget *tabPhases = new QWidget(ui->tabWidget_fab);
    tabPhases->setObjectName("tab_fab_metier_phases");
    ui->tabWidget_fab->addTab(tabPhases, "Pilotage des phases");
    auto *phasesLayout = new QVBoxLayout(tabPhases);
    phasesLayout->setContentsMargins(20, 20, 20, 20);
    phasesLayout->setSpacing(12);

    auto *top = new QHBoxLayout();
    QLabel *label = new QLabel("Fabrication cible:", tabPhases);
    fabricationAdvancedCombo = new QComboBox(tabPhases);
    top->addWidget(label);
    top->addWidget(fabricationAdvancedCombo, 1);
    phasesLayout->addLayout(top);

    fabricationAdvancedProgressLabel = new QLabel("Progression phases: --", tabPhases);
    fabricationAdvancedProgressLabel->setStyleSheet("font-weight:700;color:#c7d2fe;");
    phasesLayout->addWidget(fabricationAdvancedProgressLabel);

    fabricationAdvancedPhaseTable = new QTableView(tabPhases);
    fabricationAdvancedPhaseTable->setMinimumHeight(240);
    fabricationAdvancedPhaseTable->setSelectionBehavior(QAbstractItemView::SelectRows);
    fabricationAdvancedPhaseTable->setSelectionMode(QAbstractItemView::SingleSelection);
    fabricationAdvancedPhaseTable->setEditTriggers(QAbstractItemView::NoEditTriggers);
    phasesLayout->addWidget(fabricationAdvancedPhaseTable, 1);

    auto *actions = new QHBoxLayout();
    phaseAddButton = new QPushButton("Ajouter une phase", tabPhases);
    phaseModifyButton = new QPushButton("Modifier", tabPhases);
    phaseDeleteButton = new QPushButton("Supprimer", tabPhases);
    QPushButton *btnGenerate = new QPushButton("Generer phases standards", tabPhases);
    QPushButton *btnAdvance = new QPushButton("Avancer phase selectionnee", tabPhases);

    phaseAddButton->setStyleSheet("background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #2563eb,stop:1 #3b82f6);padding:10px 20px;");
    phaseModifyButton->setStyleSheet("background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #2563eb,stop:1 #3b82f6);padding:10px 30px;");
    phaseDeleteButton->setStyleSheet("background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #dc2626,stop:1 #ef4444);padding:10px 30px;");

    actions->addWidget(phaseAddButton);
    actions->addWidget(phaseModifyButton);
    actions->addWidget(phaseDeleteButton);
    actions->addWidget(btnGenerate);
    actions->addWidget(btnAdvance);
    actions->addStretch();
    phasesLayout->addLayout(actions);

    connect(fabricationAdvancedCombo, &QComboBox::currentTextChanged, this, [this](const QString &) {
        refreshFabricationAdvancedPanel();
    });
    connect(btnGenerate, &QPushButton::clicked, this, [this]() {
        const int idFab = fabricationAdvancedCombo ? fabricationAdvancedCombo->currentData().toInt() : 0;
        if (idFab <= 0) {
            QMessageBox::warning(this, "Fabrication", "Selectionnez une fabrication.");
            return;
        }
        QString err;
        if (Fabrication::genererPhasesParDefaut(idFab, &err)) {
            QMessageBox::information(
                this,
                "Fabrication",
                err.isEmpty() ? "Phases standards creees." : err);
            refreshFabricationTable();
            refreshFabricationAdvancedPanel();
            refreshPlanificationPanel();
        } else {
            QMessageBox::warning(this, "Fabrication", err.isEmpty() ? "Echec de creation des phases." : err);
        }
    });
    connect(btnAdvance, &QPushButton::clicked, this, [this]() {
        if (!fabricationAdvancedPhaseTable || !fabricationAdvancedPhaseTable->model()) {
            return;
        }
        const QModelIndex idx = fabricationAdvancedPhaseTable->currentIndex();
        if (!idx.isValid()) {
            QMessageBox::warning(this, "Fabrication", "Selectionnez une phase.");
            return;
        }
        const int idPhase = fabricationAdvancedPhaseTable->model()->data(
            fabricationAdvancedPhaseTable->model()->index(idx.row(), 0)).toInt();
        QString err;
        if (Fabrication::avancerPhase(idPhase, &err)) {
            refreshFabricationTable();
            refreshFabricationAdvancedPanel();
            refreshPlanificationPanel();
        } else {
            QMessageBox::warning(this, "Fabrication", err.isEmpty() ? "Impossible d'avancer la phase." : err);
        }
    });

    // Phase CRUD connections
    connect(phaseAddButton, &QPushButton::clicked, this, [this]() {
        showPhaseFormDialog(-1); // -1 for add
    });
    connect(phaseModifyButton, &QPushButton::clicked, this, [this]() {
        if (!fabricationAdvancedPhaseTable || !fabricationAdvancedPhaseTable->model()) {
            QMessageBox::warning(this, "Phase", "Aucune phase selectionnee.");
            return;
        }
        const QModelIndex idx = fabricationAdvancedPhaseTable->currentIndex();
        if (!idx.isValid()) {
            QMessageBox::warning(this, "Phase", "Selectionnez une phase.");
            return;
        }
        const int idPhase = fabricationAdvancedPhaseTable->model()->data(
            fabricationAdvancedPhaseTable->model()->index(idx.row(), 0)).toInt();
        showPhaseFormDialog(idPhase);
    });
    connect(phaseDeleteButton, &QPushButton::clicked, this, [this]() {
        if (!fabricationAdvancedPhaseTable || !fabricationAdvancedPhaseTable->model()) {
            QMessageBox::warning(this, "Phase", "Aucune phase selectionnee.");
            return;
        }
        const QModelIndex idx = fabricationAdvancedPhaseTable->currentIndex();
        if (!idx.isValid()) {
            QMessageBox::warning(this, "Phase", "Selectionnez une phase.");
            return;
        }
        const int idPhase = fabricationAdvancedPhaseTable->model()->data(
            fabricationAdvancedPhaseTable->model()->index(idx.row(), 0)).toInt();

        if (QMessageBox::question(this, "Suppression", "Voulez-vous vraiment supprimer cette phase ?") == QMessageBox::Yes) {
            Phase p;
            if (p.supprimer(idPhase)) {
                QMessageBox::information(this, "Phase", "Phase supprimee.");
                refreshFabricationAdvancedPanel();
            } else {
                QMessageBox::warning(this, "Phase", p.getLastError());
            }
        }
    });

    setupPlanificationTab();
    connect(fabricationAdvancedPhaseTable, &QTableView::clicked, this, [this](const QModelIndex &index) {
        if (!index.isValid() || !fabricationAdvancedPhaseTable || !fabricationAdvancedPhaseTable->model()) {
            return;
        }

        refreshPlanificationPanel();

        const int planTab = planificationTabIndex(ui->tabWidget_fab);
        if (planTab >= 0) {
            ui->tabWidget_fab->setCurrentIndex(planTab);
        }

        const QString phaseName = fabricationAdvancedPhaseTable->model()->data(
            fabricationAdvancedPhaseTable->model()->index(index.row(), 1)).toString();
        if (!planificationPhaseTable) {
            return;
        }
        for (int row = 0; row < planificationPhaseTable->rowCount(); ++row) {
            QTableWidgetItem *phaseItem = planificationPhaseTable->item(row, 0);
            if (!phaseItem) {
                continue;
            }
            if (phaseItem->text().trimmed().compare(phaseName.trimmed(), Qt::CaseInsensitive) == 0) {
                planificationPhaseTable->selectRow(row);
                break;
            }
        }
    });

    fabricationAdvancedUiReady = true;
}

void smartcarpentry::refreshFabricationAdvancedPhases()
{
    if (!fabricationAdvancedPhaseTable || !fabricationAdvancedCombo) {
        return;
    }
    const int idFab = fabricationAdvancedCombo->currentData().toInt();
    if (idFab <= 0) {
        fabricationAdvancedPhaseTable->setModel(nullptr);
        return;
    }
    QSqlQueryModel *model = Phase::afficher(idFab);
    if (!model) {
        fabricationAdvancedPhaseTable->setModel(nullptr);
        return;
    }
    model->setParent(fabricationAdvancedPhaseTable);
    if (fabricationAdvancedPhaseTable->model()) fabricationAdvancedPhaseTable->model()->deleteLater();
    fabricationAdvancedPhaseTable->setModel(model);
    applyGlobalPremiumStyle(fabricationAdvancedPhaseTable);
}

void smartcarpentry::refreshFabricationAdvancedPanel()
{
    if (!fabricationAdvancedUiReady) {
        return;
    }

    if (fabricationAdvancedCombo && fabricationAdvancedCombo->count() == 0) {
        QSignalBlocker advancedBlocker(fabricationAdvancedCombo);
        QSqlQuery fabQuery;
        fabQuery.exec(
            "SELECT F.IDFABRICATION, M.NOM_MODELE "
            "FROM FABRICATION F "
            "LEFT JOIN MODELE M ON M.IDMODELE = F.IDMODELE "
            "ORDER BY F.IDFABRICATION");
        while (fabQuery.next()) {
            const int idFab = fabQuery.value(0).toInt();
            const QString nom = fabQuery.value(1).toString();
            fabricationAdvancedCombo->addItem(
                QString("#%1 - %2").arg(idFab).arg(nom.isEmpty() ? "Sans modele" : nom),
                idFab);
        }
        if (fabricationAdvancedCombo->count() > 0) {
            fabricationAdvancedCombo->setCurrentIndex(0);
        }
    }

    const int idFab = fabricationAdvancedCombo ? fabricationAdvancedCombo->currentData().toInt() : 0;
    if (idFab <= 0) {
        if (fabricationAdvancedProgressLabel) fabricationAdvancedProgressLabel->setText("Progression phases: --");
        if (fabricationAdvancedPhaseTable) fabricationAdvancedPhaseTable->setModel(nullptr);
        refreshPlanificationPanel();
        return;
    }

    int totalPhases = 0;
    int donePhases = 0;
    int inProgressPhases = 0;
    QString progressErr;
    const double progress = Fabrication::calculerProgressionPhases(idFab, &totalPhases, &donePhases, &inProgressPhases, &progressErr);
    if (fabricationAdvancedProgressLabel) {
        fabricationAdvancedProgressLabel->setText(
            QString("Progression phases: %1% (%2/%3 terminees, %4 en cours)")
                .arg(progress, 0, 'f', 1)
                .arg(donePhases)
                .arg(totalPhases)
                .arg(inProgressPhases));
    }

    QSqlQuery q;
    q.prepare("SELECT DATE_FIN_PREVUE, DATE_FIN_REELLE, ETAT_FABRICATION, NB_PERSONNES FROM FABRICATION WHERE IDFABRICATION = :id");
    q.bindValue(":id", idFab);

    refreshFabricationAdvancedPhases();
    refreshPlanificationPanel();
}

// ============================================================
//  Planification (Scheduling) Tab Setup
// ============================================================

namespace {

const QString kPlanificationDateTimeFormat = "dd/MM/yyyy HH:mm";

QString planificationDisplayStatusFromEtat(const QString &etatRaw)
{
    const QString etat = etatRaw.trimmed().toUpper();
    if (etat == "EN_COURS" || etat == "EN COURS" || etat == "ON GOING" || etat == "ONGOING") {
        return "On Going";
    }
    if (etat.startsWith("TERMINE") || etat == "FINISHED") {
        return "Finished";
    }
    if (etat == "NON_COMMENCE" || etat == "JAMAIS COMMENCE" || etat == "NEVER STARTED"
        || etat == "ATTENTE" || etat == "EN_ATTENTE") {
        return "Never Started";
    }
    return QString();
}

QString planificationFormatDateTime(const QDateTime &dateTime)
{
    return dateTime.isValid() ? dateTime.toString(kPlanificationDateTimeFormat) : QString();
}

QDateTime planificationParseDateTime(const QString &value)
{
    const QString trimmed = value.trimmed();
    if (trimmed.isEmpty()) {
        return QDateTime();
    }
    QDateTime parsed = QDateTime::fromString(trimmed, kPlanificationDateTimeFormat);
    if (parsed.isValid()) {
        return parsed;
    }

    // Backward compatibility with date-only values saved in previous versions.
    const QDate dateOnly = QDate::fromString(trimmed, "dd/MM/yyyy");
    if (dateOnly.isValid()) {
        return QDateTime(dateOnly, QTime(0, 0));
    }
    return QDateTime();
}

QString planificationComputeDisplayStatus(const QDateTime &dateDebut,
                                          const QDateTime &dateFinReelle,
                                          const QString &etatRaw)
{
    const QString mappedStatus = planificationDisplayStatusFromEtat(etatRaw);
    if (!mappedStatus.isEmpty()) {
        return mappedStatus;
    }

    if (dateFinReelle.isValid()) {
        return "Finished";
    }

    if (dateDebut.isValid()) {
        return (dateDebut <= QDateTime::currentDateTime()) ? "On Going" : "Never Started";
    }

    return "Never Started";
}

QString planificationStatusToDbState(const QString &displayStatus)
{
    const QString normalized = displayStatus.trimmed().toUpper();
    if (normalized == "ON GOING" || normalized == "ONGOING"
        || normalized == "EN COURS" || normalized == "EN_COURS") {
        return "EN_COURS";
    }
    if (normalized == "FINISHED" || normalized.startsWith("TERMINE")) {
        return "TERMINE_BON";
    }
    return "NON_COMMENCE";
}

QString planificationDefaultCompetenceForPhase(const QString &phaseName)
{
    const QString normalized = phaseName.trimmed().toUpper();
    if (normalized.contains("DECOUP")) {
        return "CNC";
    }
    if (normalized.contains("ASSEMB")) {
        return "Joinery";
    }
    if (normalized.contains("PONC")) {
        return "Milling";
    }
    if (normalized.contains("VERNISS")) {
        return "Finishing";
    }
    if (normalized.contains("FINITION")) {
        return "Assembly";
    }
    return "Planification";
}

int planificationTabIndex(const QTabWidget *tabWidget)
{
    if (!tabWidget) {
        return -1;
    }
    for (int i = 0; i < tabWidget->count(); ++i) {
        const QWidget *tab = tabWidget->widget(i);
        if (tab && tab->objectName() == "tab_fab_planification") {
            return i;
        }
    }
    return -1;
}

}

void smartcarpentry::setupPlanificationTab()
{
    if (!ui->tabWidget_fab || !fabricationAdvancedCombo) {
        return;
    }

    QWidget *tabPlanification = new QWidget(ui->tabWidget_fab);
    tabPlanification->setObjectName("tab_fab_planification");
    ui->tabWidget_fab->addTab(tabPlanification, "Planification");

    auto *planLayout = new QVBoxLayout(tabPlanification);
    planLayout->setContentsMargins(20, 20, 20, 20);
    planLayout->setSpacing(12);

    planificationFabricationLabel = new QLabel("Aucune fabrication selectionnee", tabPlanification);
    planificationFabricationLabel->setStyleSheet("font-weight:700;color:#c7d2fe;");
    planLayout->addWidget(planificationFabricationLabel);

    // Etape scheduling table
    planificationPhaseTable = new QTableWidget(tabPlanification);
    planificationPhaseTable->setMinimumHeight(300);
    planificationPhaseTable->setColumnCount(6);
    planificationPhaseTable->setHorizontalHeaderLabels({
        "Etape", "Date Debut", "Date Fin", "Duree", "Statut", "Temps Restant (h:mm)"
    });
    applyGlobalPremiumStyle(planificationPhaseTable);
    planificationPhaseTable->horizontalHeader()->setStretchLastSection(false);
    planificationPhaseTable->horizontalHeader()->setSectionResizeMode(0, QHeaderView::Stretch);
    planificationPhaseTable->horizontalHeader()->setSectionResizeMode(1, QHeaderView::ResizeToContents);
    planificationPhaseTable->horizontalHeader()->setSectionResizeMode(2, QHeaderView::ResizeToContents);
    planificationPhaseTable->horizontalHeader()->setSectionResizeMode(3, QHeaderView::ResizeToContents);
    planificationPhaseTable->horizontalHeader()->setSectionResizeMode(4, QHeaderView::ResizeToContents);
    planificationPhaseTable->horizontalHeader()->setSectionResizeMode(5, QHeaderView::ResizeToContents);
    planificationPhaseTable->setRowCount(0);
    planificationPhaseTable->setSelectionBehavior(QAbstractItemView::SelectRows);
    planificationPhaseTable->setSelectionMode(QAbstractItemView::SingleSelection);
    planificationPhaseTimers.clear();

    planLayout->addWidget(planificationPhaseTable, 1);

    // Action buttons
    auto *buttonsLayout = new QHBoxLayout();
    QPushButton *saveBtn = new QPushButton("Enregistrer les dates", tabPlanification);
    QPushButton *startPhaseBtn = new QPushButton("Demarrer etape selectionnee", tabPlanification);
    QPushButton *finishPhaseBtn = new QPushButton("Terminer etape selectionnee", tabPlanification);
    QPushButton *generatePhasesBtn = new QPushButton("Generer etapes vides", tabPlanification);

    const QString pilotagePrimaryButtonStyle =
        "background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #2563eb,stop:1 #3b82f6);padding:10px 20px;";
    const QString pilotageDangerButtonStyle =
        "background:qlineargradient(x1:0,y1:0,x2:1,y2:0,stop:0 #dc2626,stop:1 #ef4444);padding:10px 30px;";

    saveBtn->setStyleSheet(pilotagePrimaryButtonStyle);
    startPhaseBtn->setStyleSheet(pilotagePrimaryButtonStyle);
    finishPhaseBtn->setStyleSheet(pilotageDangerButtonStyle);
    generatePhasesBtn->setStyleSheet(pilotagePrimaryButtonStyle);

    buttonsLayout->addWidget(saveBtn);
    buttonsLayout->addWidget(startPhaseBtn);
    buttonsLayout->addWidget(finishPhaseBtn);
    buttonsLayout->addWidget(generatePhasesBtn);
    buttonsLayout->addStretch();
    planLayout->addLayout(buttonsLayout);

    // Connect signals - use fabricationAdvancedCombo for selection
    connect(fabricationAdvancedCombo, QOverload<int>::of(&QComboBox::currentIndexChanged), 
            this, &smartcarpentry::refreshPlanificationPanel);

    auto persistPlanificationRow = [this](int idFab, int row) -> bool {
        if (!planificationPhaseTable || idFab <= 0
            || row < 0 || row >= planificationPhaseTable->rowCount()) {
            return false;
        }

        QTableWidgetItem *phaseItem = planificationPhaseTable->item(row, 0);
        QTableWidgetItem *dateDebutItem = planificationPhaseTable->item(row, 1);
        QTableWidgetItem *dateFinItem = planificationPhaseTable->item(row, 2);
        QTableWidgetItem *statutItem = planificationPhaseTable->item(row, 4);
        if (!phaseItem || !dateDebutItem || !dateFinItem || !statutItem) {
            return false;
        }

        QString phaseName = phaseItem->text().trimmed();
        if (phaseName.isEmpty()) {
            phaseName = QString("Etape %1").arg(row + 1);
            phaseItem->setText(phaseName);
        }
        int idPhase = phaseItem->data(Qt::UserRole).toInt();
        const QString debutText = dateDebutItem->text().trimmed();
        const QString finText = dateFinItem->text().trimmed();

        QDateTime dateDebut;
        if (!debutText.isEmpty()) {
            dateDebut = planificationParseDateTime(debutText);
            if (!dateDebut.isValid()) {
                QMessageBox::warning(this, "Date invalide",
                                     QString("Date debut invalide pour %1 (dd/MM/yyyy HH:mm).").arg(phaseName));
                return false;
            }
        }

        QDateTime dateFinPrevue;
        if (!finText.isEmpty()) {
            dateFinPrevue = planificationParseDateTime(finText);
            if (!dateFinPrevue.isValid()) {
                QMessageBox::warning(this, "Date invalide",
                                     QString("Date fin invalide pour %1 (dd/MM/yyyy HH:mm).").arg(phaseName));
                return false;
            }
        }

        if (dateDebut.isValid() && dateFinPrevue.isValid() && dateFinPrevue < dateDebut) {
            QMessageBox::warning(this, "Planification",
                                 QString("Date fin < date debut pour %1.").arg(phaseName));
            return false;
        }

        QString displayStatus = planificationDisplayStatusFromEtat(statutItem->text());
        if (displayStatus.isEmpty()) {
            displayStatus = (dateDebut.isValid() && dateDebut <= QDateTime::currentDateTime())
                                ? "On Going"
                                : "Never Started";
        }
        const QString dbStatus = planificationStatusToDbState(displayStatus);
        QDateTime dateFinReelle;
        if (displayStatus == "Finished") {
            if (dateFinPrevue.isValid()) {
                dateFinReelle = dateFinPrevue;
            } else {
                dateFinReelle = QDateTime::currentDateTime();
                dateFinPrevue = dateFinReelle;
            }
            if (!dateDebut.isValid()) {
                dateDebut = dateFinReelle;
            }
        }

        {
            QSignalBlocker blocker(planificationPhaseTable);
            dateDebutItem->setText(planificationFormatDateTime(dateDebut));
            dateFinItem->setText(planificationFormatDateTime(dateFinPrevue));
            statutItem->setText(displayStatus);
        }
        updatePlanificationDuration(row);

        if (idPhase > 0) {
            const QString debutStr = dateDebut.isValid() ? dateDebut.toString("yyyy-MM-dd HH:mm:ss") : QString();
            const QString finPrevueStr = dateFinPrevue.isValid() ? dateFinPrevue.toString("yyyy-MM-dd HH:mm:ss") : QString();
            const QString finReelleStr = dateFinReelle.isValid() ? dateFinReelle.toString("yyyy-MM-dd HH:mm:ss") : QString();

            QSqlQuery updateQuery;
            updateQuery.prepare(
                "UPDATE PHASE "
                "SET NOM_PHASE = :nomPhase, "
                "    DATE_DEBUT = TO_DATE(:dateDebut, 'YYYY-MM-DD HH24:MI:SS'), "
                "    DATE_FIN_PREVUE = TO_DATE(:dateFinPrevue, 'YYYY-MM-DD HH24:MI:SS'), "
                "    DATE_FIN_REELLE = TO_DATE(:dateFinReelle, 'YYYY-MM-DD HH24:MI:SS'), "
                "    ETAT = :etat "
                "WHERE ID_PHASE = :idPhase");
            updateQuery.bindValue(":nomPhase", phaseName);
            updateQuery.bindValue(":dateDebut", debutStr.isEmpty() ? QVariant(QMetaType::fromType<QString>()) : QVariant(debutStr));
            updateQuery.bindValue(":dateFinPrevue", finPrevueStr.isEmpty() ? QVariant(QMetaType::fromType<QString>()) : QVariant(finPrevueStr));
            updateQuery.bindValue(":dateFinReelle", finReelleStr.isEmpty() ? QVariant(QMetaType::fromType<QString>()) : QVariant(finReelleStr));
            updateQuery.bindValue(":etat", dbStatus);
            updateQuery.bindValue(":idPhase", idPhase);

            if (!updateQuery.exec()) {
                qWarning() << "Mise a jour phase planification impossible:" << updateQuery.lastError().text();
                return false;
            }
            if (updateQuery.numRowsAffected() <= 0) {
                idPhase = 0;
            } else {
                phaseItem->setData(Qt::UserRole, idPhase);
                return true;
            }
        }

        Phase phase;
        phase.setNomPhase(phaseName);
        phase.setCompetenceRequise(planificationDefaultCompetenceForPhase(phaseName));
        phase.setEtat(dbStatus);
        phase.setDateDebut(dateDebut);
        phase.setDateFinPrevue(dateFinPrevue);
        phase.setDateFinReelle(dateFinReelle);
        phase.setIdFabrication(idFab);
        if (!phase.ajouter()) {
            qWarning() << "Insertion phase planification impossible:" << phase.getLastError();
            return false;
        }

        QSqlQuery idQuery;
        idQuery.prepare(
            "SELECT MAX(ID_PHASE) FROM PHASE "
            "WHERE IDFABRICATION = :idFab AND NOM_PHASE = :phaseName");
        idQuery.bindValue(":idFab", idFab);
        idQuery.bindValue(":phaseName", phaseName);
        if (idQuery.exec() && idQuery.next()) {
            const int insertedId = idQuery.value(0).toInt();
            if (insertedId > 0) {
                phaseItem->setData(Qt::UserRole, insertedId);
            }
        }

        return true;
    };
    
    // Handle date cell editing with date picker on double-click
    connect(planificationPhaseTable, &QTableWidget::cellDoubleClicked, this, [this](int row, int column) {
        if (column != 1 && column != 2) return;  // Only date columns
        
        QTableWidgetItem *cell = planificationPhaseTable->item(row, column);
        if (!cell) return;
        
        // Create a dialog with date-time picker
        QDialog dialog(this);
        dialog.setWindowTitle(column == 1 ? "Selectionner date debut" : "Selectionner date fin");
        dialog.setWindowModality(Qt::ApplicationModal);
        
        QVBoxLayout *dlgLayout = new QVBoxLayout(&dialog);
        QDateTimeEdit *dateEdit = new QDateTimeEdit(&dialog);
        dateEdit->setCalendarPopup(true);
        dateEdit->setDisplayFormat("dd/MM/yyyy HH:mm");
        
        QDateTime currentDateTime = planificationParseDateTime(cell->text());
        if (currentDateTime.isValid()) {
            dateEdit->setDateTime(currentDateTime);
        } else {
            dateEdit->setDateTime(QDateTime::currentDateTime());
        }
        
        QDialogButtonBox *buttons = new QDialogButtonBox(QDialogButtonBox::Ok | QDialogButtonBox::Cancel, &dialog);
        dlgLayout->addWidget(dateEdit);
        dlgLayout->addWidget(buttons);
        
        connect(buttons, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);
        connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
        
        if (dialog.exec() == QDialog::Accepted) {
            cell->setText(dateEdit->dateTime().toString("dd/MM/yyyy HH:mm"));
            updatePlanificationDuration(row);
        }
    });
    
    // Handle text editing for dates
    connect(planificationPhaseTable, &QTableWidget::itemChanged, this, [this](QTableWidgetItem *item) {
        if (!item) return;
        int row = planificationPhaseTable->row(item);
        int col = planificationPhaseTable->column(item);
        if (col == 1 || col == 2) {
            const QDateTime dt = planificationParseDateTime(item->text());
            if (!dt.isValid() && !item->text().trimmed().isEmpty()) {
                QMessageBox::warning(this, "Date invalide", "Format: dd/MM/yyyy HH:mm");
                item->setText("");
            } else if (dt.isValid()) {
                item->setText(planificationFormatDateTime(dt));
            }
            updatePlanificationDuration(row);
        }
    });

    // Save button click handler
    connect(saveBtn, &QPushButton::clicked, this, [this, persistPlanificationRow]() {
        const int idFab = fabricationAdvancedCombo ? fabricationAdvancedCombo->currentData().toInt() : 0;
        if (idFab <= 0) {
            QMessageBox::warning(this, "Planification", "Selectionnez une fabrication.");
            return;
        }

        bool hasError = false;
        for (int i = 0; i < planificationPhaseTable->rowCount(); ++i) {
            if (!persistPlanificationRow(idFab, i)) {
                hasError = true;
            }
        }

        if (hasError) {
            QMessageBox::warning(this, "Planification",
                                 "Certaines etapes n'ont pas pu etre enregistrees.");
        } else {
            QMessageBox::information(this, "Planification", "Dates des etapes enregistrees.");
        }
        refreshPlanificationPanel();
    });

    connect(startPhaseBtn, &QPushButton::clicked, this, [this, persistPlanificationRow]() {
        const int row = planificationPhaseTable->currentRow();
        if (row < 0) {
            QMessageBox::warning(this, "Planification", "Selectionnez une etape.");
            return;
        }

        QTableWidgetItem *statutItem = planificationPhaseTable->item(row, 4);
        QTableWidgetItem *dateDebut = planificationPhaseTable->item(row, 1);
        if (statutItem) {
            statutItem->setText("On Going");
        }
        if (dateDebut && dateDebut->text().trimmed().isEmpty()) {
            dateDebut->setText(QDateTime::currentDateTime().toString("dd/MM/yyyy HH:mm"));
        }
        updatePlanificationDuration(row);

        const int idFab = fabricationAdvancedCombo ? fabricationAdvancedCombo->currentData().toInt() : 0;
        if (idFab > 0 && !persistPlanificationRow(idFab, row)) {
            QMessageBox::warning(this, "Planification", "Impossible de demarrer cette etape.");
            return;
        }
        refreshPlanificationPanel();
    });

    connect(finishPhaseBtn, &QPushButton::clicked, this, [this, persistPlanificationRow]() {
        const int row = planificationPhaseTable->currentRow();
        if (row < 0) {
            QMessageBox::warning(this, "Planification", "Selectionnez une etape.");
            return;
        }

        QTableWidgetItem *statutItem = planificationPhaseTable->item(row, 4);
        QTableWidgetItem *dateDebut = planificationPhaseTable->item(row, 1);
        QTableWidgetItem *dateFin = planificationPhaseTable->item(row, 2);
        if (statutItem) {
            statutItem->setText("Finished");
        }
        if (dateDebut && dateDebut->text().trimmed().isEmpty()) {
            dateDebut->setText(QDateTime::currentDateTime().toString("dd/MM/yyyy HH:mm"));
        }
        if (dateFin && dateFin->text().trimmed().isEmpty()) {
            dateFin->setText(QDateTime::currentDateTime().toString("dd/MM/yyyy HH:mm"));
        }
        updatePlanificationDuration(row);

        const int idFab = fabricationAdvancedCombo ? fabricationAdvancedCombo->currentData().toInt() : 0;
        if (idFab > 0 && !persistPlanificationRow(idFab, row)) {
            QMessageBox::warning(this, "Planification", "Impossible de terminer cette etape.");
            return;
        }

        // Auto-start the next phase when it has no schedule yet.
        const int nextRow = row + 1;
        if (idFab > 0 && nextRow < planificationPhaseTable->rowCount()) {
            QTableWidgetItem *nextStatus = planificationPhaseTable->item(nextRow, 4);
            QTableWidgetItem *nextStart = planificationPhaseTable->item(nextRow, 1);
            if (nextStatus && nextStart) {
                const QString normalizedNext = planificationDisplayStatusFromEtat(nextStatus->text());
                const bool canAutoStart = (normalizedNext.isEmpty() || normalizedNext == "Never Started")
                                          && nextStart->text().trimmed().isEmpty();
                if (canAutoStart) {
                    nextStatus->setText("On Going");
                    nextStart->setText(QDateTime::currentDateTime().toString("dd/MM/yyyy HH:mm"));
                    updatePlanificationDuration(nextRow);
                    if (!persistPlanificationRow(idFab, nextRow)) {
                        QMessageBox::warning(this, "Planification",
                                             "Etape suivante non demarree automatiquement.");
                    }
                }
            }
        }
        refreshPlanificationPanel();
    });

    connect(generatePhasesBtn, &QPushButton::clicked, this, [this, persistPlanificationRow]() {
        const int idFab = fabricationAdvancedCombo ? fabricationAdvancedCombo->currentData().toInt() : 0;
        if (idFab <= 0) {
            QMessageBox::warning(this, "Planification", "Selectionnez une fabrication.");
            return;
        }

        QString creationError;
        if (!Fabrication::genererPhasesParDefaut(idFab, &creationError)) {
            QMessageBox::warning(this, "Planification",
                                 creationError.isEmpty()
                                     ? "Impossible de generer les etapes."
                                     : creationError);
            return;
        }
        refreshPlanificationPanel();

        const int etapeCount = qMax(5, planificationPhaseTable->rowCount());
        if (planificationPhaseTable->rowCount() < etapeCount) {
            planificationPhaseTable->setRowCount(etapeCount);
        }

        bool hasError = false;
        for (int i = 0; i < etapeCount; ++i) {
            {
                QSignalBlocker blocker(planificationPhaseTable);
                if (!planificationPhaseTable->item(i, 0)) {
                    QTableWidgetItem *phaseItem = new QTableWidgetItem();
                    phaseItem->setFlags(phaseItem->flags() | Qt::ItemIsEditable);
                    planificationPhaseTable->setItem(i, 0, phaseItem);
                }
                if (!planificationPhaseTable->item(i, 1)) {
                    planificationPhaseTable->setItem(i, 1, new QTableWidgetItem());
                }
                if (!planificationPhaseTable->item(i, 2)) {
                    planificationPhaseTable->setItem(i, 2, new QTableWidgetItem());
                }
                if (!planificationPhaseTable->item(i, 4)) {
                    QTableWidgetItem *statusItem = new QTableWidgetItem();
                    statusItem->setFlags(statusItem->flags() & ~Qt::ItemIsEditable);
                    planificationPhaseTable->setItem(i, 4, statusItem);
                }
                planificationPhaseTable->item(i, 0)->setText(QString());
                planificationPhaseTable->item(i, 1)->setText(QString());
                planificationPhaseTable->item(i, 2)->setText(QString());
                planificationPhaseTable->item(i, 4)->setText("Never Started");
            }
            updatePlanificationDuration(i);
            if (!persistPlanificationRow(idFab, i)) {
                hasError = true;
            }
        }

        if (hasError) {
            QMessageBox::warning(this, "Planification",
                                 "Etapes creees, mais certaines sauvegardes ont echoue.");
        } else {
            QMessageBox::information(this, "Planification", "Etapes vides generees.");
        }
        refreshPlanificationPanel();
    });

    planificationTimer = new QTimer(this);
    connect(planificationTimer, &QTimer::timeout, this, &smartcarpentry::updatePlanificationTimers);
    planificationTimer->start(1000);
    refreshPlanificationPanel();
}

void smartcarpentry::refreshPlanificationPanel()
{
    if (!planificationPhaseTable || !fabricationAdvancedCombo) {
        return;
    }

    const int idFab = fabricationAdvancedCombo->currentData().toInt();
    if (planificationFabricationLabel) {
        if (idFab <= 0) {
            planificationFabricationLabel->setText("Aucune fabrication selectionnee");
        } else {
            planificationFabricationLabel->setText(QString("Fabrication #%1").arg(idFab));
        }
    }

    if (idFab <= 0) {
        planificationPhaseTable->setRowCount(0);
        planificationPhaseTimers.clear();
        updatePlanificationTimers();
        return;
    }

    QString ensurePhaseError;
    if (!Fabrication::genererPhasesParDefaut(idFab, &ensurePhaseError) && !ensurePhaseError.isEmpty()) {
        qWarning() << "Generation automatique des etapes impossible:" << ensurePhaseError;
    }

    QSqlQuery query;
    query.prepare(
        "SELECT ID_PHASE, NOM_PHASE, DATE_DEBUT, DATE_FIN_PREVUE, DATE_FIN_REELLE, ETAT "
        "FROM PHASE WHERE IDFABRICATION = :idFab ORDER BY ID_PHASE");
    query.bindValue(":idFab", idFab);

    struct PlanificationRowData {
        int idPhase = 0;
        QString phaseName;
        QDateTime dateDebut;
        QDateTime dateFinPrevue;
        QDateTime dateFinReelle;
        QString etat;
    };

    QVector<PlanificationRowData> rows;
    if (query.exec()) {
        while (query.next()) {
            PlanificationRowData rowData;
            rowData.idPhase = query.value(0).toInt();
            rowData.phaseName = query.value(1).toString();
            rowData.dateDebut = query.value(2).toDateTime();
            rowData.dateFinPrevue = query.value(3).toDateTime();
            rowData.dateFinReelle = query.value(4).toDateTime();
            rowData.etat = query.value(5).toString();
            rows.push_back(rowData);
        }
    } else {
        qWarning() << "Chargement planification impossible:" << query.lastError().text();
    }

    if (rows.isEmpty()) {
        rows.resize(5);
    } else if (rows.size() < 5) {
        rows.resize(5);
    }

    QSignalBlocker blocker(planificationPhaseTable);
    planificationPhaseTable->setRowCount(rows.size());
    planificationPhaseTimers.clear();

    for (int i = 0; i < rows.size(); ++i) {
        const PlanificationRowData &rowData = rows[i];
        const QDateTime dateFinAffichee = rowData.dateFinReelle.isValid() ? rowData.dateFinReelle : rowData.dateFinPrevue;

        QTableWidgetItem *phaseItem = planificationPhaseTable->item(i, 0);
        if (!phaseItem) {
            phaseItem = new QTableWidgetItem();
            planificationPhaseTable->setItem(i, 0, phaseItem);
        }
        phaseItem->setText(rowData.phaseName);
        phaseItem->setData(Qt::UserRole, rowData.idPhase);
        phaseItem->setFlags(phaseItem->flags() | Qt::ItemIsEditable);

        QTableWidgetItem *dateDebutItem = planificationPhaseTable->item(i, 1);
        if (!dateDebutItem) {
            dateDebutItem = new QTableWidgetItem();
            planificationPhaseTable->setItem(i, 1, dateDebutItem);
        }
        dateDebutItem->setText(planificationFormatDateTime(rowData.dateDebut));
        dateDebutItem->setFlags(dateDebutItem->flags() | Qt::ItemIsEditable);

        QTableWidgetItem *dateFinItem = planificationPhaseTable->item(i, 2);
        if (!dateFinItem) {
            dateFinItem = new QTableWidgetItem();
            planificationPhaseTable->setItem(i, 2, dateFinItem);
        }
        dateFinItem->setText(planificationFormatDateTime(dateFinAffichee));
        dateFinItem->setFlags(dateFinItem->flags() | Qt::ItemIsEditable);

        QTableWidgetItem *dureeItem = planificationPhaseTable->item(i, 3);
        if (!dureeItem) {
            dureeItem = new QTableWidgetItem();
            planificationPhaseTable->setItem(i, 3, dureeItem);
        }
        dureeItem->setFlags(dureeItem->flags() & ~Qt::ItemIsEditable);
        if (rowData.dateDebut.isValid() && dateFinAffichee.isValid() && dateFinAffichee >= rowData.dateDebut) {
            const qint64 seconds = rowData.dateDebut.secsTo(dateFinAffichee);
            dureeItem->setText(QString("%1h %2m").arg(seconds / 3600).arg((seconds % 3600) / 60, 2, 10, QChar('0')));
        } else {
            dureeItem->setText("");
        }

        QTableWidgetItem *statutItem = planificationPhaseTable->item(i, 4);
        if (!statutItem) {
            statutItem = new QTableWidgetItem();
            planificationPhaseTable->setItem(i, 4, statutItem);
        }
        statutItem->setFlags(statutItem->flags() & ~Qt::ItemIsEditable);
        statutItem->setText(planificationComputeDisplayStatus(rowData.dateDebut, rowData.dateFinReelle, rowData.etat));

        QLabel *timerLabel = qobject_cast<QLabel *>(planificationPhaseTable->cellWidget(i, 5));
        if (!timerLabel) {
            timerLabel = new QLabel("--:--", planificationPhaseTable);
            timerLabel->setStyleSheet("color:#64748b;font-weight:700;");
            planificationPhaseTable->setCellWidget(i, 5, timerLabel);
        }
        planificationPhaseTimers[i] = timerLabel;
    }

    updatePlanificationTimers();
}

void smartcarpentry::updatePlanificationDuration(int row)
{
    if (!planificationPhaseTable || row < 0 || row >= planificationPhaseTable->rowCount()) {
        return;
    }

    QTableWidgetItem *dateDebutItem = planificationPhaseTable->item(row, 1);
    QTableWidgetItem *dateFinItem = planificationPhaseTable->item(row, 2);
    QTableWidgetItem *dureeItem = planificationPhaseTable->item(row, 3);
    QTableWidgetItem *statutItem = planificationPhaseTable->item(row, 4);
    if (!dateDebutItem || !dateFinItem || !dureeItem || !statutItem) {
        return;
    }

    const QDateTime dateDebut = planificationParseDateTime(dateDebutItem->text());
    const QDateTime dateFin = planificationParseDateTime(dateFinItem->text());

    if (dateDebut.isValid() && dateFin.isValid() && dateFin >= dateDebut) {
        const qint64 seconds = dateDebut.secsTo(dateFin);
        const qint64 hours = seconds / 3600;
        const qint64 minutes = (seconds % 3600) / 60;
        dureeItem->setText(QString("%1h %2m").arg(hours).arg(minutes, 2, 10, QChar('0')));
    } else {
        dureeItem->setText("");
    }

    QString displayStatus = planificationDisplayStatusFromEtat(statutItem->text());
    if (displayStatus.isEmpty()) {
        displayStatus = (dateDebut.isValid() && dateDebut <= QDateTime::currentDateTime())
                            ? "On Going"
                            : "Never Started";
    }
    statutItem->setText(displayStatus);
    updatePlanificationTimers();
}

void smartcarpentry::updatePlanificationTimers()
{
    if (!planificationPhaseTable || !planificationTimer || !planificationTimer->isActive()) {
        return;
    }

    QDateTime now = QDateTime::currentDateTime();

    for (int i = 0; i < planificationPhaseTable->rowCount(); ++i) {
        QLabel *timerLabel = planificationPhaseTimers.value(i, nullptr);
        if (!timerLabel) {
            continue;
        }

        QTableWidgetItem *dateFinItem = planificationPhaseTable->item(i, 2);
        QTableWidgetItem *statutItem = planificationPhaseTable->item(i, 4);

        if (!dateFinItem || !statutItem) continue;

        QDateTime dateFin = planificationParseDateTime(dateFinItem->text());
        const QString statut = statutItem->text().trimmed();
        const bool onGoing = (statut.compare("On Going", Qt::CaseInsensitive) == 0)
            || (planificationDisplayStatusFromEtat(statut) == "On Going");

        if (dateFin.isValid() && onGoing) {
            qint64 secondsRemaining = now.secsTo(dateFin);

            if (secondsRemaining < 0) {
                timerLabel->setText("DEPASSEE");
                timerLabel->setStyleSheet("color:#ef4444;font-weight:700;");
            } else {
                int hours = secondsRemaining / 3600;
                int minutes = (secondsRemaining % 3600) / 60;
                QString timeStr = QString("%1:%2").arg(hours, 2, 10, QChar('0')).arg(minutes, 2, 10, QChar('0'));
                timerLabel->setText(timeStr);
                timerLabel->setStyleSheet("color:#10b981;font-weight:700;");
            }
        } else {
            timerLabel->setText("--:--");
            timerLabel->setStyleSheet("color:#64748b;font-weight:700;");
        }
    }
}

