QString budgetExtractJsonObjectText(const QString &raw)
{
    QString t = raw.trimmed();
    if (t.startsWith("```")) {
        const int firstNl = t.indexOf('\n');
        if (firstNl > 0) {
            t = t.mid(firstNl + 1);
        }
        if (t.endsWith("```")) {
            t.chop(3);
        }
        t = t.trimmed();
    }
    const int start = t.indexOf('{');
    const int end = t.lastIndexOf('}');
    if (start >= 0 && end > start) {
        return t.mid(start, end - start + 1);
    }
    return t;
}

struct BudgetAiApiResult {
    bool valid = false;
    QString error;
    QString engineLabel;
    QString nomModele;
    QString categorie;
    QString type;
    QString dimensions;
    QString materiau;
    QString classeBois;
    double prixBase = 0.0;
    double coutEstime = 0.0;
    int tempsHeures = 0;
    double scoreIa01 = 0.0;
    QString searchQuery;
    QString model3dName;
    QString model3dUrl;
    QString previewImage;
};

bool parseBudgetAiJsonObject(const QJsonObject &o,
                             double budgetClient,
                             const QString &modeleChoisi,
                             const QString &categorieEntree,
                             BudgetAiApiResult &out)
{
    auto readString = [&](const QStringList &keys) -> QString {
        for (const QString &k : keys) {
            const QJsonValue v = o.value(k);
            if (v.isString()) {
                const QString s = v.toString().trimmed();
                if (!s.isEmpty()) {
                    return s;
                }
            }
        }
        return QString();
    };
    auto readDouble = [&](const QStringList &keys, double fallback = 0.0) -> double {
        for (const QString &k : keys) {
            const QJsonValue v = o.value(k);
            if (v.isDouble()) {
                return v.toDouble();
            }
            if (v.isString()) {
                QString s = v.toString().trimmed();
                s.replace(',', '.');
                bool ok = false;
                const double d = s.toDouble(&ok);
                if (ok) {
                    return d;
                }
            }
        }
        return fallback;
    };

    out.nomModele = readString({"nom_modele", "nom", "model_name", "name"});
    out.categorie = readString({"categorie", "category"});
    out.type = readString({"type", "modele_type", "furniture_type"});
    out.dimensions = readString({"dimensions", "dimension", "size"});
    out.materiau = readString({"materiau", "materiaux", "material"});
    out.classeBois = readString({"classe_bois", "wood_class", "wood_grade"});
    out.prixBase = readDouble({"prix_base", "prix", "price", "prix_vente"}, budgetClient * 0.85);
    out.coutEstime = readDouble({"cout_estime", "cost_estimate", "cout", "cost"}, out.prixBase * 0.75);
    out.tempsHeures = qRound(readDouble({"temps_realisation_estime", "temps_estime", "time_estimate_hours", "duree_heures"}, 24.0));
    out.scoreIa01 = readDouble({"score_ia", "score", "ai_score"}, 0.78);
    out.searchQuery = readString({"search_query", "query", "model_search_query"});
    out.model3dName = readString({"model_name", "nom_modele_3d", "name_3d"});
    out.model3dUrl = readString({"model_url", "url_modele", "viewer_url", "url"});
    out.previewImage = readString({"preview_image", "thumbnail", "image_url"});

    if (out.nomModele.isEmpty()) {
        out.nomModele = modeleChoisi.trimmed().isEmpty() ? QStringLiteral("Modele IA") : modeleChoisi.trimmed();
    }
    if (out.categorie.isEmpty()) {
        out.categorie = categorieEntree.trimmed();
    }
    if (out.type.isEmpty()) {
        out.type = modeleChoisi.trimmed().isEmpty() ? QStringLiteral("Modele bois") : modeleChoisi.trimmed();
    }
    if (out.dimensions.isEmpty()) {
        out.dimensions = QStringLiteral("120x60x75 cm");
    }
    if (out.materiau.isEmpty()) {
        out.materiau = QStringLiteral("Bois massif");
    }
    if (out.classeBois.isEmpty()) {
        out.classeBois = QStringLiteral("Classe 2");
    }

    out.prixBase = qMin(out.prixBase, budgetClient);
    if (out.prixBase <= 0.0) {
        out.prixBase = qMax(50.0, budgetClient * 0.8);
    }
    if (out.coutEstime >= out.prixBase) {
        out.coutEstime = qMax(1.0, out.prixBase - 10.0);
    }
    out.tempsHeures = qBound(4, out.tempsHeures, 160);
    // LLM often outputs score_ia: 0 in JSON template — treat as "missing"
    if (out.scoreIa01 <= 0.0) {
        out.scoreIa01 = 0.78;
    }
    out.scoreIa01 = qBound(0.0, out.scoreIa01, 1.0);

    if (out.searchQuery.isEmpty()) {
        out.searchQuery = QStringLiteral("modern wooden %1").arg(out.type.toLower());
    }
    out.valid = true;
    return true;
}

static QString buildBudgetAiUserPrompt(double budgetClient,
                                       const QString &modeleChoisi,
                                       const QString &categorie)
{
    return QString::fromUtf8(
        "You are a furniture optimization engine. Return ONLY valid JSON.\n"
        "Input:\n"
        "- budget_client=%1 TND\n"
        "- modele_choisi=%2\n"
        "- categorie=%3\n"
        "Constraints: prix_base <= budget_client, cout_estime < prix_base, realistic manufacturable furniture.\n"
        "Output exactly keys:\n"
        "{"
        "\"nom_modele\":\"\","
        "\"categorie\":\"\","
        "\"type\":\"\","
        "\"dimensions\":\"\","
        "\"materiau\":\"\","
        "\"classe_bois\":\"\","
        "\"prix_base\":0,"
        "\"cout_estime\":0,"
        "\"temps_realisation_estime\":0,"
        "\"score_ia\":0.0,"
        "\"search_query\":\"\","
        "\"model_name\":null,"
        "\"model_url\":null,"
        "\"preview_image\":null"
        "}")
        .arg(budgetClient, 0, 'f', 2)
        .arg(modeleChoisi)
        .arg(categorie);
}

static QString budgetResolveOpenAiApiKey()
{
    const QProcessEnvironment env = QProcessEnvironment::systemEnvironment();
    QString k = env.value(QStringLiteral("WOODIFY_OPENAI_API_KEY")).trimmed();
    if (k.isEmpty()) {
        k = env.value(QStringLiteral("OPENAI_API_KEY")).trimmed();
    }
    return k;
}

static int budgetOllamaTimeoutMs()
{
    bool ok = false;
    const QString raw =
        QProcessEnvironment::systemEnvironment().value(QStringLiteral("WOODIFY_OLLAMA_TIMEOUT_MS")).trimmed();
    const int ms = raw.isEmpty() ? 180000 : raw.toInt(&ok);
    if (!ok || ms < 15000) {
        return 180000;
    }
    return qMin(ms, 600000);
}

bool runBudgetModelingLocalOllama(double budgetClient,
                                  const QString &modeleChoisi,
                                  const QString &categorie,
                                  BudgetAiApiResult &out)
{
    const QProcessEnvironment env = QProcessEnvironment::systemEnvironment();
    QString ollamaModel = env.value(QStringLiteral("WOODIFY_OLLAMA_MODEL")).trimmed();
    if (ollamaModel.isEmpty()) {
        ollamaModel = QStringLiteral("qwen2.5:3b");
    }
    QString generateUrl = env.value(QStringLiteral("WOODIFY_OLLAMA_GENERATE_URL")).trimmed();
    if (generateUrl.isEmpty()) {
        QString host = env.value(QStringLiteral("WOODIFY_OLLAMA_HOST")).trimmed();
        if (host.isEmpty()) {
            host = QStringLiteral("127.0.0.1:11434");
        }
        while (host.endsWith(QLatin1Char('/'))) {
            host.chop(1);
        }
        if (host.startsWith(QStringLiteral("http://"), Qt::CaseInsensitive)
            || host.startsWith(QStringLiteral("https://"), Qt::CaseInsensitive)) {
            generateUrl = QStringLiteral("%1/api/generate").arg(host);
        } else {
            generateUrl = QStringLiteral("http://%1/api/generate").arg(host);
        }
    }

    const int timeoutMs = budgetOllamaTimeoutMs();
    const QString prompt = buildBudgetAiUserPrompt(budgetClient, modeleChoisi, categorie);

    QJsonObject payload;
    payload.insert("model", ollamaModel);
    payload.insert("prompt", prompt);
    payload.insert("stream", false);

    QNetworkAccessManager manager;
    const QUrl ollamaEndpoint(generateUrl);
    QNetworkRequest netRequest(ollamaEndpoint);
    netRequest.setHeader(QNetworkRequest::ContentTypeHeader, QStringLiteral("application/json"));
    netRequest.setTransferTimeout(timeoutMs);
    QNetworkReply *reply =
        manager.post(netRequest, QJsonDocument(payload).toJson(QJsonDocument::Compact));

    QEventLoop loop;
    QTimer timeout;
    timeout.setSingleShot(true);
    timeout.setInterval(timeoutMs);
    QObject::connect(&timeout, &QTimer::timeout, &loop, [&]() { loop.quit(); });
    QObject::connect(reply, &QNetworkReply::finished, &loop, [&]() { loop.quit(); });
    timeout.start();
    loop.exec();

    if (!reply->isFinished()) {
        reply->abort();
        reply->deleteLater();
        out.error = QStringLiteral(
            "Ollama : aucune reponse apres %1 s. Verifiez : 1) fenetre PowerShell avec \"ollama serve\" "
            "2) \"ollama pull %2\" (premier appel peut etre lent) 3) ou definissez OPENAI_API_KEY pour le cloud.")
            .arg(timeoutMs / 1000)
            .arg(ollamaModel);
        return false;
    }

    const QByteArray responseBody = reply->readAll();
    const int statusCode = reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();
    const QNetworkReply::NetworkError netError = reply->error();
    const QString netErrorText = reply->errorString();
    reply->deleteLater();

    QJsonParseError perr;
    const QJsonDocument rootDoc = QJsonDocument::fromJson(responseBody, &perr);
    if (netError != QNetworkReply::NoError || statusCode >= 400) {
        QString ollamaError;
        if (perr.error == QJsonParseError::NoError && rootDoc.isObject()) {
            ollamaError = rootDoc.object().value("error").toString().trimmed();
        }
        if (ollamaError.isEmpty()) {
            ollamaError = netErrorText.trimmed();
        }
        if (ollamaError.isEmpty()) {
            ollamaError = QStringLiteral("Echec HTTP Ollama.");
        }
        out.error = QStringLiteral("Ollama HTTP %1: %2").arg(statusCode).arg(ollamaError);
        return false;
    }

    if (perr.error != QJsonParseError::NoError || !rootDoc.isObject()) {
        out.error = QStringLiteral("Reponse Ollama invalide.");
        return false;
    }
    const QString llmText = rootDoc.object().value("response").toString().trimmed();
    if (llmText.isEmpty()) {
        out.error = QStringLiteral("Ollama a retourne une reponse vide.");
        return false;
    }

    const QString jsonText = budgetExtractJsonObjectText(llmText);
    const QJsonDocument doc = QJsonDocument::fromJson(jsonText.toUtf8(), &perr);
    if (perr.error != QJsonParseError::NoError || !doc.isObject()) {
        out.error = QStringLiteral("JSON Ollama invalide.");
        return false;
    }
    if (!parseBudgetAiJsonObject(doc.object(), budgetClient, modeleChoisi, categorie, out)) {
        return false;
    }
    out.engineLabel = QStringLiteral("Ollama local — %1 @ %2")
                          .arg(ollamaModel,
                               ollamaEndpoint.host().isEmpty() ? generateUrl : ollamaEndpoint.host());
    return true;
}

bool runBudgetModelingOpenAiCompatible(double budgetClient,
                                       const QString &modeleChoisi,
                                       const QString &categorie,
                                       BudgetAiApiResult &out)
{
    const QString apiKey = budgetResolveOpenAiApiKey();
    if (apiKey.isEmpty()) {
        out.error = QStringLiteral(
            "Cle API absente. Definissez la variable d'environnement WOODIFY_OPENAI_API_KEY ou OPENAI_API_KEY.");
        return false;
    }

    const QProcessEnvironment env = QProcessEnvironment::systemEnvironment();
    QString base = env.value(QStringLiteral("WOODIFY_OPENAI_BASE_URL")).trimmed();
    if (base.isEmpty()) {
        base = QStringLiteral("https://api.openai.com/v1");
    }
    while (base.endsWith(QLatin1Char('/'))) {
        base.chop(1);
    }

    QString model = env.value(QStringLiteral("WOODIFY_OPENAI_MODEL")).trimmed();
    if (model.isEmpty()) {
        model = QStringLiteral("gpt-4o-mini");
    }

    const QString prompt = buildBudgetAiUserPrompt(budgetClient, modeleChoisi, categorie);

    QJsonArray messages;
    messages.append(QJsonObject{{QStringLiteral("role"), QStringLiteral("system")},
                                {QStringLiteral("content"),
                                 QStringLiteral("You are a furniture optimization engine. Reply with ONLY one JSON "
                                                "object and no other text (no markdown fences).")}});
    messages.append(
        QJsonObject{{QStringLiteral("role"), QStringLiteral("user")}, {QStringLiteral("content"), prompt}});

    QJsonObject payload;
    payload.insert(QStringLiteral("model"), model);
    payload.insert(QStringLiteral("messages"), messages);
    payload.insert(QStringLiteral("temperature"), 0.15);
    // Groq (et certains autres endpoints) echouent souvent avec response_format json_object.
    const bool skipJsonMode =
        env.value(QStringLiteral("WOODIFY_OPENAI_NO_JSON_MODE")).trimmed() == QStringLiteral("1")
        || base.contains(QStringLiteral("groq.com"), Qt::CaseInsensitive);
    if (!skipJsonMode) {
        payload.insert(QStringLiteral("response_format"),
                       QJsonObject{{QStringLiteral("type"), QStringLiteral("json_object")}});
    }

    QNetworkAccessManager manager;
    const QUrl reqUrl(QStringLiteral("%1/chat/completions").arg(base));
    QNetworkRequest request(reqUrl);
    request.setHeader(QNetworkRequest::ContentTypeHeader, QStringLiteral("application/json"));
    request.setRawHeader("Authorization",
                         QStringLiteral("Bearer %1").arg(apiKey).toUtf8());
    request.setTransferTimeout(120000);

    QNetworkReply *reply = manager.post(request, QJsonDocument(payload).toJson(QJsonDocument::Compact));

    QEventLoop loop;
    QTimer timeout;
    timeout.setSingleShot(true);
    timeout.setInterval(120000);
    QObject::connect(&timeout, &QTimer::timeout, &loop, [&]() { loop.quit(); });
    QObject::connect(reply, &QNetworkReply::finished, &loop, [&]() { loop.quit(); });
    timeout.start();
    loop.exec();

    if (!reply->isFinished()) {
        reply->abort();
        reply->deleteLater();
        out.error = QStringLiteral("API OpenAI-compatible: timeout (120s).");
        return false;
    }

    const QByteArray responseBody = reply->readAll();
    const int statusCode = reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();
    const QNetworkReply::NetworkError netError = reply->error();
    const QString netErrorText = reply->errorString();
    reply->deleteLater();

    QJsonParseError perr;
    const QJsonDocument rootDoc = QJsonDocument::fromJson(responseBody, &perr);

    if (netError != QNetworkReply::NoError || statusCode >= 400) {
        QString detail = netErrorText;
        if (perr.error == QJsonParseError::NoError && rootDoc.isObject()) {
            const QJsonObject eo = rootDoc.object().value(QStringLiteral("error")).toObject();
            const QString msg = eo.value(QStringLiteral("message")).toString().trimmed();
            if (!msg.isEmpty()) {
                detail = msg;
            }
        }
        out.error = QStringLiteral("API HTTP %1: %2").arg(statusCode).arg(detail);
        return false;
    }

    if (perr.error != QJsonParseError::NoError || !rootDoc.isObject()) {
        out.error = QStringLiteral("Reponse API invalide (JSON).");
        return false;
    }

    const QJsonArray choices = rootDoc.object().value(QStringLiteral("choices")).toArray();
    if (choices.isEmpty()) {
        out.error = QStringLiteral("Reponse API sans choices[].");
        return false;
    }

    const QString llmText =
        choices.at(0).toObject().value(QStringLiteral("message")).toObject().value(QStringLiteral("content")).toString().trimmed();
    if (llmText.isEmpty()) {
        out.error = QStringLiteral("Le modele cloud a retourne un contenu vide.");
        return false;
    }

    const QString jsonText = budgetExtractJsonObjectText(llmText);
    const QJsonDocument doc = QJsonDocument::fromJson(jsonText.toUtf8(), &perr);
    if (perr.error != QJsonParseError::NoError || !doc.isObject()) {
        out.error = QStringLiteral("JSON extrait du modele cloud invalide.");
        return false;
    }
    if (!parseBudgetAiJsonObject(doc.object(), budgetClient, modeleChoisi, categorie, out)) {
        return false;
    }

    const QString hostDisplay = reqUrl.host().isEmpty() ? base : reqUrl.host();
    out.engineLabel =
        QStringLiteral("API compatible OpenAI — %1 @ %2").arg(model, hostDisplay);
    return true;
}

bool runBudgetModelingApi(double budgetClient,
                          const QString &modeleChoisi,
                          const QString &categorie,
                          BudgetAiApiResult &out)
{
    const QString mode =
        QProcessEnvironment::systemEnvironment().value(QStringLiteral("WOODIFY_BUDGET_AI")).trimmed().toLower();
    const QString effectiveMode = mode.isEmpty() ? QStringLiteral("auto") : mode;

    if (effectiveMode == QStringLiteral("openai")) {
        return runBudgetModelingOpenAiCompatible(budgetClient, modeleChoisi, categorie, out);
    }
    if (effectiveMode == QStringLiteral("ollama")) {
        if (runBudgetModelingLocalOllama(budgetClient, modeleChoisi, categorie, out)) {
            return true;
        }
        if (out.error.isEmpty()) {
            out.error = QStringLiteral("Ollama local indisponible (serve + modele qwen2.5:3b).");
        }
        return false;
    }

    // auto : cle cloud si presente, sinon Ollama local
    if (!budgetResolveOpenAiApiKey().isEmpty()) {
        if (runBudgetModelingOpenAiCompatible(budgetClient, modeleChoisi, categorie, out)) {
            return true;
        }
        const QString firstErr = out.error;
        out.error.clear();
        if (runBudgetModelingLocalOllama(budgetClient, modeleChoisi, categorie, out)) {
            return true;
        }
        out.error = QStringLiteral("%1 | Fallback Ollama: %2")
                        .arg(firstErr, out.error.isEmpty() ? QStringLiteral("echec") : out.error);
        return false;
    }

    if (runBudgetModelingLocalOllama(budgetClient, modeleChoisi, categorie, out)) {
        return true;
    }
    if (out.error.isEmpty()) {
        out.error = QStringLiteral(
            "Generation IA indisponible. Definissez OPENAI_API_KEY (cloud) ou installez Ollama local "
            "(ollama serve + qwen2.5:3b).");
    }
    return false;
}

QString budgetResultSuccessHtml(int idModele,
                                const QString &nomModele,
                                const QString &categorie,
                                const QString &type,
                                const QString &dimensions,
                                const QString &materiau,
                                const QString &classeBois,
                                double prixBase,
                                double budget,
                                double coutEstime,
                                double marge,
                                double rentabilitePct,
                                int tempsHeures,
                                int scoreIa,
                                double budgetRestant,
                                const QString &noteBd,
                                const QString &searchQuery,
                                const QString &modelName,
                                const QString &modelUrl,
                                const QString &previewImage,
                                const QString &engineLabel)
{
    const QString scoreBg = (scoreIa >= 85)
        ? QStringLiteral("rgba(22,101,52,0.55)")
        : ((scoreIa >= 72) ? QStringLiteral("rgba(12,74,110,0.55)") : QStringLiteral("rgba(113,63,18,0.55)"));
    const QString scoreFg = QStringLiteral("#ecfdf5");

    QString footerNote;
    if (!noteBd.trimmed().isEmpty()) {
        footerNote = QStringLiteral(
                       "<p style=\"margin:12px 0 0 0;padding:10px 12px;border-radius:10px;"
                       "background-color:rgba(120,53,15,0.35);border:1px solid rgba(251,191,36,0.35);"
                       "font-size:11px;color:#fde68a;\"><b>Note technique</b> e %1</p>")
            .arg(budgetHtmlEscape(noteBd));
    }

    const QString effectiveModelUrl = budgetResolve3dViewerUrl(modelUrl, searchQuery, type);

    QString preview3dHtml;
    if (!previewImage.trimmed().isEmpty()) {
        preview3dHtml = QStringLiteral(
            "<div style=\"margin-top:10px;padding:10px;border:1px solid rgba(56,189,248,0.35);"
            "border-radius:10px;background-color:rgba(15,23,42,0.7);\">"
            "<p style=\"margin:0 0 8px 0;font-size:11px;color:#93c5fd;font-weight:700;\">Apercu 3D</p>"
            "<a href=\"%1\" style=\"text-decoration:none;\">"
            "<img src=\"%2\" width=\"260\" style=\"border-radius:8px;border:1px solid rgba(148,163,184,0.4);\"/>"
            "</a>"
            "</div>")
                            .arg(budgetHtmlEscape(effectiveModelUrl), budgetHtmlEscape(previewImage));
    }

    const QString moteurIaAffiche =
        engineLabel.isEmpty()
            ? QStringLiteral("Ollama local — qwen2.5:3b @ 127.0.0.1:11434")
            : engineLabel;

    QString rows;
    rows += budgetMetricRow(QStringLiteral("Moteur IA"), moteurIaAffiche);
    rows += budgetMetricRow(QStringLiteral("Nom du modele"), nomModele);
    rows += budgetMetricRow(QStringLiteral("Categorie"), categorie);
    rows += budgetMetricRow(QStringLiteral("Type"), type);
    rows += budgetMetricRow(QStringLiteral("Dimensions optimisees"), dimensions);
    rows += budgetMetricRow(QStringLiteral("Materiau conseille"), materiau);
    rows += budgetMetricRow(QStringLiteral("Classe bois"), classeBois);
    rows += budgetMetricRow(QStringLiteral("Cout estime fabrication"),
                            QStringLiteral("%1 DT").arg(coutEstime, 0, 'f', 2));
    rows += budgetMetricRow(QStringLiteral("Marge estimee"),
                            QStringLiteral("%1 DT").arg(marge, 0, 'f', 2));
    rows += budgetMetricRow(QStringLiteral("Rentabilite"),
                            QStringLiteral("%1 %").arg(rentabilitePct, 0, 'f', 1));
    rows += budgetMetricRow(QStringLiteral("Delai de realisation estime"),
                            QStringLiteral("%1 h").arg(tempsHeures));
    rows += budgetMetricRow(QStringLiteral("Recherche API 3D"), searchQuery);
    rows += budgetMetricRow(QStringLiteral("Modele 3D"), modelName.isEmpty() ? QStringLiteral("null") : modelName);
    rows += budgetMetricRow(QStringLiteral("Viewer 3D integre"), QStringLiteral("Affichage direct dans l'application"));

    return QStringLiteral(
               "<div style=\"font-family:'Segoe UI',Arial,sans-serif;\">"
               "<div style=\"background-color:rgba(8,13,32,0.95);border:1px solid rgba(56,189,248,0.35);"
               "border-radius:18px;overflow:hidden;\">"
               "<div style=\"padding:14px 18px;background-color:rgba(30,41,59,0.92);"
               "border-bottom:1px solid rgba(51,65,85,0.55);\">"
               "<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"><tr>"
               "<td valign=\"middle\">"
               "<p style=\"margin:0;font-size:11px;letter-spacing:1.2px;color:#64748b;font-weight:700;\">"
               "RESULTAT IA</p>"
               "<p style=\"margin:4px 0 0 0;font-size:17px;font-weight:800;color:#e0f2fe;\">"
               "Proposition optimisee</p>"
               "<p style=\"margin:4px 0 0 0;font-size:12px;color:#94a3b8;\">"
               "Enregistree dans <b style=\"color:#7dd3fc;\">MODELE</b> - ID %1</p>"
               "</td>"
               "<td align=\"right\" valign=\"middle\">"
               "<span style=\"display:inline-block;padding:8px 14px;border-radius:999px;"
               "background-color:%2;color:%3;font-weight:800;font-size:14px;\">Score %4</span>"
               "</td></tr></table>"
               "</div>"
               "<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border-collapse:collapse;\">"
               "%5"
               "</table>"
               "<div style=\"padding:14px 18px;background-color:rgba(15,23,42,0.88);\">"
               "<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"><tr>"
               "<td style=\"width:50%;vertical-align:top;\">"
               "<p style=\"margin:0;font-size:11px;color:#64748b;font-weight:700;\">PRIX DE VENTE</p>"
               "<p style=\"margin:4px 0 0 0;font-size:20px;font-weight:800;color:#38bdf8;\">%6 DT</p>"
               "<p style=\"margin:2px 0 0 0;font-size:11px;color:#64748b;\">Budget client %7 DT</p>"
               "</td>"
               "<td style=\"width:50%;vertical-align:top;text-align:right;\">"
               "<p style=\"margin:0;font-size:11px;color:#64748b;font-weight:700;\">BUDGET RESTANT</p>"
               "<p style=\"margin:4px 0 0 0;font-size:20px;font-weight:800;color:#4ade80;\">%8 DT</p>"
               "<p style=\"margin:2px 0 0 0;font-size:11px;color:#64748b;\">Marge %9% - Cout %10 DT</p>"
               "</td></tr></table>"
               "%11"
               "%12"
               "</div>"
               "</div></div>")
        .arg(idModele)
        .arg(scoreBg)
        .arg(scoreFg)
        .arg(scoreIa)
        .arg(rows)
        .arg(prixBase, 0, 'f', 2)
        .arg(budget, 0, 'f', 2)
        .arg(budgetRestant, 0, 'f', 2)
        .arg(rentabilitePct, 0, 'f', 1)
        .arg(coutEstime, 0, 'f', 2)
        .arg(footerNote)
        .arg(preview3dHtml);
}

