        modelePerfChart->setTitleFont(QFont(QStringLiteral("Segoe UI"), 12, QFont::DemiBold));
        modelePerfChart->setBackgroundRoundness(14);
        modelePerfChart->setBackgroundBrush(QBrush(QColor(15, 23, 42)));
        modelePerfChart->setPlotAreaBackgroundVisible(true);
        modelePerfChart->setPlotAreaBackgroundBrush(QBrush(QColor(11, 17, 34)));
        modelePerfChart->setPlotAreaBackgroundPen(QPen(QColor(71, 85, 105, 90), 1));
        modelePerfChart->legend()->setVisible(false);
        /* Marge basse suffisante pour les annees sur l'axe X */
        modelePerfChart->setMargins(QMargins(16, 16, 16, 36));
