//  Clear Fabrication form
// ============================================================

void smartcarpentry::on_btn_fab_clr_clicked()
{
    clearFabricationForm();
    if (ui->search_fab) {
        ui->search_fab->clear();
    }
    if (ui->combo_filter_etat) {
        ui->combo_filter_etat->setCurrentIndex(0);
    }
    refreshFabricationTable();
}

// ============================================================
//  Fabrication table row click -> populate form
// ============================================================

void smartcarpentry::on_tv_fab_clicked(const QModelIndex &index)
{
    if (!index.isValid()) return;

    QAbstractItemModel *model = ui->tv_fab->model();
    int row = index.row();

    selectedFabId = model->data(model->index(row, 0)).toInt();
    if (ui->fab_id) {
        ui->fab_id->setText(QString::number(selectedFabId));
    }

    // Column order: ID, DATE_DEBUT, DATE_FIN_PREVUE, DATE_FIN_REELLE,
    //               NB_PERSONNES, ETAT_FABRICATION, IDMODELE
    QString dateDebutStr   = model->data(model->index(row, 1)).toString();
    QString dateFinPrevStr = model->data(model->index(row, 2)).toString();
    QString dateFinReelStr = model->data(model->index(row, 3)).toString();

    QDate dateDebut   = QDate::fromString(dateDebutStr,   "dd/MM/yyyy");
    QDate dateFinPrev = QDate::fromString(dateFinPrevStr, "dd/MM/yyyy");
    QDate dateFinReel = QDate::fromString(dateFinReelStr, "dd/MM/yyyy");

    if (dateDebut.isValid())   ui->fab_date_debut->setDate(dateDebut);
    if (dateFinPrev.isValid()) ui->fab_date_fin_prevue->setDate(dateFinPrev);
    if (dateFinReel.isValid()) ui->fab_date_fin_reelle->setDate(dateFinReel);

    ui->fab_nb_personnes->setValue(model->data(model->index(row, 4)).toInt());

    QString etat = model->data(model->index(row, 5)).toString();
    int etatIndex = ui->fab_etat->findText(etat, Qt::MatchFixedString);
    if (etatIndex >= 0) ui->fab_etat->setCurrentIndex(etatIndex);

    // Find the modele in the combo by stored data
    int idMod = model->data(model->index(row, 6)).toInt();
    for (int i = 0; i < ui->fab_idModele->count(); ++i) {
        if (ui->fab_idModele->itemData(i).toInt() == idMod) {
            ui->fab_idModele->setCurrentIndex(i);
            break;
        }
    }

    refreshFabricationTemperatureUi();
}

// ============================================================
//  Fabrication search filter
// ============================================================

void smartcarpentry::on_search_fab_textChanged(const QString &text)
{
    if (!fabricationFilterProxy) {
        fabricationFilterProxy = qobject_cast<QSortFilterProxyModel *>(ui->tv_fab->model());
    }
    if (fabricationFilterProxy) {
        fabricationFilterProxy->setFilterFixedString(text);
        fabricationCurrentPage = 0;
        applyFabricationPagination();
    }
}

// ============================================================
//  List-tab: Modifier -> populate form & switch to form tab
// ============================================================

void smartcarpentry::on_btn_fab_list_modify_clicked()
{
    on_btn_fab_add_clicked();
}

// ============================================================
//  List-tab: Supprimer -> delete selected row
// ============================================================

void smartcarpentry::on_btn_fab_list_delete_clicked()
{
    QModelIndex index = ui->tv_fab->currentIndex();
    if (!index.isValid()) {
        QMessageBox::warning(this, "Erreur", "Veuillez selectionner une fabrication a supprimer.");
        return;
    }

    QAbstractItemModel *model = ui->tv_fab->model();
    int row = index.row();
    int id = model->data(model->index(row, 0)).toInt();

    if (id <= 0) {
        QMessageBox::warning(this, "Erreur", "ID fabrication invalide.");
        return;
    }

    QMessageBox::StandardButton reply = QMessageBox::question(
        this, "Confirmation",
        QString("Voulez-vous vraiment supprimer la fabrication #%1 ?").arg(id),
        QMessageBox::Yes | QMessageBox::No
    );
    if (reply != QMessageBox::Yes) return;

    Fabrication f;
    if (f.supprimer(id)) {
        QMessageBox::information(this, "Succes", "Fabrication supprimee avec succes !");
        refreshFabricationTable();
        if (selectedFabId == id) clearFabricationForm();
    } else {
        QMessageBox::critical(this, "Erreur",
            "echec de la suppression.\n" + f.getLastError());
    }
}

// ============================================================
//  etat filter (tri par etat de fabrication)
// ============================================================

void smartcarpentry::on_combo_filter_etat_currentTextChanged(const QString &etat)
{
    if (!fabricationFilterProxy) {
        fabricationFilterProxy = qobject_cast<QSortFilterProxyModel *>(ui->tv_fab->model());
    }
    auto *proxy = dynamic_cast<FabricationFilterProxyModel *>(fabricationFilterProxy);
    if (!proxy) {
        return;
    }
    proxy->setStatusFilter(etat);
    proxy->setFilterFixedString(ui->search_fab ? ui->search_fab->text() : QString());
    fabricationCurrentPage = 0;
    applyFabricationPagination();
}

