// ============================================================
//  Helper: Refresh the Piece table view
// ============================================================

void smartcarpentry::refreshPieceTable()
{
    loadPieceBoisOptions();
    loadPieceModeleOptions();

    QSqlQueryModel *queryModel = pieceTmp.afficher();
    QStandardItemModel *standardModel = new QStandardItemModel(this);

    standardModel->setColumnCount(queryModel->columnCount());
    for (int i = 0; i < queryModel->columnCount(); ++i)
        standardModel->setHeaderData(i, Qt::Horizontal, queryModel->headerData(i, Qt::Horizontal));

    for (int r = 0; r < queryModel->rowCount(); ++r) {
        for (int c = 0; c < queryModel->columnCount(); ++c) {
            QStandardItem *item = new QStandardItem();
            QVariant val = queryModel->data(queryModel->index(r, c));
            item->setData(val, Qt::EditRole);
            item->setTextAlignment(Qt::AlignCenter);
            const bool editableColumn = (c == 1 || c == 2 || c == 3 || c == 5 || c == 6 || c == 7);
            if (!editableColumn) {
                item->setFlags(item->flags() & ~Qt::ItemIsEditable);
            }

            const QString status = queryModel->data(queryModel->index(r, 8)).toString().trimmed().toUpper();
            if (status == "BROUILLON") {
                item->setBackground(QColor(79, 70, 229, 34));
                item->setForeground(QBrush(QColor("#e0e7ff")));
            } else {
                item->setBackground(QColor(15, 23, 42, 0));
                item->setForeground(QBrush(QColor("#f8fafc")));
            }
            standardModel->setItem(r, c, item);
        }
    }

    if (pieceFilterProxy) {
        pieceFilterProxy->deleteLater();
        pieceFilterProxy = nullptr;
    }

    pieceFilterProxy = new PieceFilterProxyModel(this);
    pieceFilterProxy->setSourceModel(standardModel);
    pieceFilterProxy->setFilterCaseSensitivity(Qt::CaseInsensitive);

    ui->tv_pc->setModel(pieceFilterProxy);
    applyGlobalPremiumStyle(ui->tv_pc, ui->search_pc, ui->btn_pc_list_modify, ui->btn_pc_list_delete);
    ui->tv_pc->setItemDelegateForColumn(3, new IntegerSpinDelegate(1, 999999, this));
    ui->tv_pc->setItemDelegateForColumn(5, new DoubleSpinDelegate(0.01, 99999.99, 2, this));
    ui->tv_pc->setItemDelegateForColumn(6, new DoubleSpinDelegate(0.01, 99999.99, 2, this));
    ui->tv_pc->setItemDelegateForColumn(7, new DoubleSpinDelegate(0.01, 99999.99, 2, this));

    disconnect(standardModel, &QStandardItemModel::dataChanged, this, nullptr);
    connect(standardModel, &QStandardItemModel::dataChanged, this, [this](const QModelIndex &topLeft, const QModelIndex &) {
        if (pieceInlineEditGuard) {
            return;
        }
        this->on_tv_pc_cellChanged(topLeft.row(), topLeft.column());
    });

    queryModel->deleteLater();
    applyPieceCompositeFilter();
    applyPieceListSort();
    refreshPieceStats();
}

// ============================================================
//  Helper: Load available Bois into Piece form/filter
// ============================================================

void smartcarpentry::loadPieceBoisOptions()
{
    const int selectedBoisId = ui->pc_matiere->currentData().toInt();
    const QString selectedFilter = ui->combo_filter_matiere->currentText();
    const int selectedManualBoisId = ui->pc_manual_bois->currentData().toInt();

    {
        QSignalBlocker formBlocker(ui->pc_matiere);
        QSignalBlocker filterBlocker(ui->combo_filter_matiere);
        QSignalBlocker manualBlocker(ui->pc_manual_bois);

        ui->pc_matiere->clear();
        ui->combo_filter_matiere->clear();
        ui->pc_manual_bois->clear();
        ui->combo_filter_matiere->addItem("Toutes");

        QSqlQuery boisQuery;
        if (boisQuery.exec("SELECT IDBOIS, NOMBOIS FROM BOIS ORDER BY NOMBOIS, IDBOIS")) {
            while (boisQuery.next()) {
                const int id = boisQuery.value(0).toInt();
                const QString nomBois = boisQuery.value(1).toString().trimmed();
                const QString displayText = QString("%1 (ID %2)").arg(nomBois, QString::number(id));
                ui->pc_matiere->addItem(displayText, id);
                ui->pc_matiere->setItemData(ui->pc_matiere->count() - 1, nomBois, Qt::UserRole + 1);
                ui->pc_manual_bois->addItem(displayText, id);
                ui->pc_manual_bois->setItemData(ui->pc_manual_bois->count() - 1, nomBois, Qt::UserRole + 1);
            }
        }

        QSqlQuery matiereFilterQuery;
        if (matiereFilterQuery.exec("SELECT DISTINCT NOMBOIS FROM BOIS ORDER BY NOMBOIS")) {
            while (matiereFilterQuery.next()) {
                const QString nomBois = matiereFilterQuery.value(0).toString().trimmed();
                if (!nomBois.isEmpty()) {
                    ui->combo_filter_matiere->addItem(nomBois);
                }
            }
        }

        int formIndex = ui->pc_matiere->findData(selectedBoisId);
        if (formIndex < 0 && ui->pc_matiere->count() > 0) {
            formIndex = 0;
        }
        if (formIndex >= 0) {
            ui->pc_matiere->setCurrentIndex(formIndex);
        }

        int manualIndex = ui->pc_manual_bois->findData(selectedManualBoisId);
        if (manualIndex < 0 && ui->pc_manual_bois->count() > 0) {
            manualIndex = 0;
        }
        if (manualIndex >= 0) {
            ui->pc_manual_bois->setCurrentIndex(manualIndex);
        }

        int filterIndex = ui->combo_filter_matiere->findText(selectedFilter, Qt::MatchFixedString);
        if (filterIndex < 0) {
            filterIndex = 0;
        }
        ui->combo_filter_matiere->setCurrentIndex(filterIndex);
    }

    on_pc_matiere_currentIndexChanged(ui->pc_matiere->currentIndex());
    on_combo_filter_matiere_currentTextChanged(ui->combo_filter_matiere->currentText());
    syncPieceAiGeneratorCombos();
    refreshPieceGenerationContext();
}

// ============================================================
//  Helper: Load available Modeles into Piece form
// ============================================================

void smartcarpentry::loadPieceModeleOptions()
{
    const int selectedModeleId = ui->pc_modele->currentData().toInt();
    const int selectedAiModeleId = ui->pc_ai_modele_source->currentData().toInt();
    const int selectedManualModeleId = ui->pc_manual_modele->currentData().toInt();

    {
        QSignalBlocker blocker(ui->pc_modele);
        QSignalBlocker aiBlocker(ui->pc_ai_modele_source);
        QSignalBlocker manualBlocker(ui->pc_manual_modele);
        ui->pc_modele->clear();
        ui->pc_ai_modele_source->clear();
        ui->pc_manual_modele->clear();

        QSqlQuery query;
        if (query.exec("SELECT IDMODELE, NOM_MODELE FROM MODELE ORDER BY NOM_MODELE, IDMODELE")) {
            while (query.next()) {
                const int id = query.value(0).toInt();
                const QString nomModele = query.value(1).toString().trimmed();
                const QString displayText = QString("%1 (ID %2)").arg(nomModele, QString::number(id));
                ui->pc_modele->addItem(displayText, id);
                ui->pc_modele->setItemData(ui->pc_modele->count() - 1, nomModele, Qt::UserRole + 1);
                ui->pc_ai_modele_source->addItem(displayText, id);
                ui->pc_ai_modele_source->setItemData(ui->pc_ai_modele_source->count() - 1, nomModele, Qt::UserRole + 1);
                ui->pc_manual_modele->addItem(displayText, id);
                ui->pc_manual_modele->setItemData(ui->pc_manual_modele->count() - 1, nomModele, Qt::UserRole + 1);
            }
        }

        int index = ui->pc_modele->findData(selectedModeleId);
        if (index < 0 && ui->pc_modele->count() > 0) {
            index = 0;
        }
        if (index >= 0) {
            ui->pc_modele->setCurrentIndex(index);
        }

        int aiIndex = ui->pc_ai_modele_source->findData(selectedAiModeleId);
        if (aiIndex < 0 && ui->pc_ai_modele_source->count() > 0) {
            aiIndex = 0;
        }
        if (aiIndex >= 0) {
            ui->pc_ai_modele_source->setCurrentIndex(aiIndex);
        }

        int manualIndex = ui->pc_manual_modele->findData(selectedManualModeleId);
        if (manualIndex < 0 && ui->pc_manual_modele->count() > 0) {
            manualIndex = 0;
        }
        if (manualIndex >= 0) {
            ui->pc_manual_modele->setCurrentIndex(manualIndex);
        }
    }

    on_pc_modele_currentIndexChanged(ui->pc_modele->currentIndex());
    syncPieceAiGeneratorCombos();
    refreshPieceGenerationContext();
}

// ============================================================
//  Helper: Refresh statistics widgets on piece page
// ============================================================

void smartcarpentry::refreshPieceStats()
{
    int referenceCount = 0;
    int totalQuantity = 0;
    int weeklyQuantity = 0;
    int weeklyReferenceCount = 0;
    int publishedReferenceCount = 0;
    int draftReferenceCount = 0;
    int publishedQuantity = 0;
    int draftQuantity = 0;
    int materialVariety = 0;
    double totalPieceArea = 0.0;
    double totalBoisArea = 0.0;

    QSqlQuery summaryQuery;
    if (summaryQuery.exec(
            "SELECT COUNT(*), "
            "NVL(SUM(QUANTITE),0), "
            "NVL(SUM(LONGUEUR_MM * LARGEUR_MM * QUANTITE),0), "
            "NVL(SUM(CASE WHEN UPPER(NVL(STATUT, 'PUBLIE')) = 'PUBLIE' THEN 1 ELSE 0 END),0), "
            "NVL(SUM(CASE WHEN UPPER(NVL(STATUT, 'PUBLIE')) = 'BROUILLON' THEN 1 ELSE 0 END),0), "
            "NVL(SUM(CASE WHEN UPPER(NVL(STATUT, 'PUBLIE')) = 'PUBLIE' THEN QUANTITE ELSE 0 END),0), "
            "NVL(SUM(CASE WHEN UPPER(NVL(STATUT, 'PUBLIE')) = 'BROUILLON' THEN QUANTITE ELSE 0 END),0), "
            "COUNT(DISTINCT NVL(MATIERE, 'Non definie')) "
            "FROM PIECE") && summaryQuery.next()) {
        referenceCount = summaryQuery.value(0).toInt();
        totalQuantity = summaryQuery.value(1).toInt();
        totalPieceArea = summaryQuery.value(2).toDouble();
        publishedReferenceCount = summaryQuery.value(3).toInt();
        draftReferenceCount = summaryQuery.value(4).toInt();
        publishedQuantity = summaryQuery.value(5).toInt();
        draftQuantity = summaryQuery.value(6).toInt();
        materialVariety = summaryQuery.value(7).toInt();
    }

    QSqlQuery weeklyQuery;
    if (weeklyQuery.exec(
            "SELECT COUNT(*), NVL(SUM(QUANTITE),0) "
            "FROM PIECE "
            "WHERE DATE_CREATION >= TRUNC(SYSDATE) - 7") && weeklyQuery.next()) {
        weeklyReferenceCount = weeklyQuery.value(0).toInt();
        weeklyQuantity = weeklyQuery.value(1).toInt();
    }

    QSqlQuery boisAreaQuery;
    if (boisAreaQuery.exec(
            "SELECT NVL(SUM(LONGUEUR * LARGEUR * QUANTITE),0) "
            "FROM BOIS") && boisAreaQuery.next()) {
        totalBoisArea = boisAreaQuery.value(0).toDouble();
    }

    const double yieldPercent = (totalBoisArea > 0.0)
        ? qMin(100.0, (totalPieceArea / totalBoisArea) * 100.0)
        : 0.0;
    const double lossPercent = qMax(0.0, 100.0 - yieldPercent);
    const double averageAreaPerPiece = (totalQuantity > 0)
        ? (totalPieceArea / static_cast<double>(totalQuantity))
        : 0.0;

    if (pieceStatsPages) {
        const int overviewIndex = pieceStatsPages->indexOf(pieceStatsOverviewPage);
        if (overviewIndex >= 0) {
            const QString overviewTitle = (referenceCount > 0)
                ? QString("Synthese | %1 refs").arg(formatPieceStatInteger(referenceCount))
                : QString("Synthese");
            pieceStatsPages->setTabText(overviewIndex, overviewTitle);
        }
        const int materialsIndex = pieceStatsPages->indexOf(pieceStatsMaterialsPage);
        if (materialsIndex >= 0) {
            const QString materialsTitle = (materialVariety > 0)
                ? QString("Matieres | %1 profils").arg(formatPieceStatInteger(materialVariety))
                : QString("Matieres");
            pieceStatsPages->setTabText(materialsIndex, materialsTitle);
        }
    }

    ui->lb_pc_stats_total_value->setText(formatPieceStatInteger(totalQuantity));
    ui->lb_pc_stats_total_hint->setText(
        QString("%1 refs publiees | %2 refs brouillon | %3 refs sur 7 jours")
            .arg(formatPieceStatInteger(publishedReferenceCount))
            .arg(formatPieceStatInteger(draftReferenceCount))
            .arg(formatPieceStatInteger(weeklyReferenceCount)));
    ui->lb_pc_stats_yield_value->setText(QString("%1%").arg(formatPieceStatNumber(yieldPercent, 1)));
    ui->pb_pc_stats_yield->setValue(qRound(yieldPercent));
    ui->lb_pc_stats_loss_value->setText(QString("%1%").arg(formatPieceStatNumber(lossPercent, 1)));
    ui->lb_pc_stats_loss_hint->setText(
        QString("Surface utile: %1 | Stock bois: %2")
            .arg(formatPieceAreaText(totalPieceArea))
            .arg(formatPieceAreaText(totalBoisArea)));

    const QString sortBy = ui->pc_stats_sort_by->currentText();
    const QString sortOrder = (ui->pc_stats_sort_order->currentText() == "Croissant")
        ? "ASC" : "DESC";

    QString orderField = "QTY";
    if (sortBy == "Nombre de references") {
        orderField = "NBREF";
    } else if (sortBy == "Surface totale") {
        orderField = "AREA";
    }

    struct MaterialStat {
        QString name;
        double metric = 0.0;
        int quantity = 0;
        int references = 0;
        double area = 0.0;
    };

    QList<MaterialStat> materialStats;
    double totalMetric = 0.0;

    QSqlQuery materialQuery;
    const QString materialSql = QString(
        "SELECT NVL(MATIERE, 'Non definie') AS MAT, "
        "COUNT(*) AS NBREF, "
        "NVL(SUM(QUANTITE),0) AS QTY, "
        "NVL(SUM(LONGUEUR_MM * LARGEUR_MM * QUANTITE),0) AS AREA "
        "FROM PIECE "
        "GROUP BY NVL(MATIERE, 'Non definie') "
        "ORDER BY %1 %2, MAT")
        .arg(orderField, sortOrder);

    if (materialQuery.exec(materialSql)) {
        while (materialQuery.next()) {
            MaterialStat stat;
            stat.name = materialQuery.value(0).toString();
            stat.references = materialQuery.value(1).toInt();
            stat.quantity = materialQuery.value(2).toInt();
            stat.area = materialQuery.value(3).toDouble();

            if (orderField == "NBREF") {
                stat.metric = static_cast<double>(stat.references);
            } else if (orderField == "AREA") {
                stat.metric = stat.area;
            } else {
                stat.metric = static_cast<double>(stat.quantity);
            }

            totalMetric += stat.metric;
            materialStats.append(stat);
        }
    }

    QLabel *labels[3] = {
        ui->lb_pc_stats_mat_1,
        ui->lb_pc_stats_mat_2,
        ui->lb_pc_stats_mat_3
    };
    QProgressBar *bars[3] = {
        ui->pb_pc_stats_mat_1,
        ui->pb_pc_stats_mat_2,
        ui->pb_pc_stats_mat_3
    };
    const int statIndex = qMin(materialStats.size(), 3);

    for (int i = 0; i < 3; ++i) {
        if (i < statIndex) {
            const MaterialStat &stat = materialStats.at(i);
            const double share = (totalMetric > 0.0) ? (stat.metric / totalMetric) * 100.0 : 0.0;
            QString metricText;
            if (orderField == "NBREF") {
                metricText = QString("%1 refs").arg(stat.references);
            } else if (orderField == "AREA") {
                metricText = QString("%1 mm2").arg(QString::number(stat.area, 'f', 0));
            } else {
                metricText = QString("%1 unites").arg(stat.quantity);
            }

            labels[i]->setText(QString("%1  |  %2").arg(stat.name, metricText));
            bars[i]->setValue(qRound(share));
        } else {
            labels[i]->setText("Aucune donnee");
            bars[i]->setValue(0);
        }
    }

    QString topModel = "Aucun";
    int topModelQty = 0;
    QSqlQuery modelQuery;
    if (modelQuery.exec(
            "SELECT NOM_MODELE, TOTAL_QTY FROM ("
            "  SELECT NVL(M.NOM_MODELE, 'Sans modele') AS NOM_MODELE, "
            "         NVL(SUM(P.QUANTITE),0) AS TOTAL_QTY "
            "  FROM PIECE P "
            "  LEFT JOIN MODELE M ON M.IDMODELE = P.IDMODELE "
            "  GROUP BY NVL(M.NOM_MODELE, 'Sans modele') "
            "  ORDER BY TOTAL_QTY DESC"
            ") WHERE ROWNUM = 1") && modelQuery.next()) {
        topModel = modelQuery.value(0).toString();
        topModelQty = modelQuery.value(1).toInt();
    }

    const QString dominantMaterial = (statIndex > 0) ? materialStats.first().name : "Aucune";
    QString busiestDayLabel = "Aucune";
    int busiestDayQty = 0;
    QSqlQuery busiestDayQuery;
    if (busiestDayQuery.exec(
            "SELECT JOUR_LABEL, QTY FROM ("
            "  SELECT TO_CHAR(TRUNC(DATE_CREATION), 'DD/MM') AS JOUR_LABEL, "
            "         NVL(SUM(QUANTITE),0) AS QTY, "
            "         TRUNC(DATE_CREATION) AS JOUR"
            "  FROM PIECE "
            "  WHERE DATE_CREATION >= TRUNC(SYSDATE) - 6 "
            "  GROUP BY TRUNC(DATE_CREATION) "
            "  ORDER BY QTY DESC, JOUR DESC"
            ") WHERE ROWNUM = 1") && busiestDayQuery.next()) {
        busiestDayLabel = busiestDayQuery.value(0).toString();
        busiestDayQty = busiestDayQuery.value(1).toInt();
    }

    QString recommendation;
    if (referenceCount <= 0) {
        recommendation = "Aucune piece disponible. Commencez par publier un premier jeu de references.";
    } else if (draftReferenceCount > 0) {
        recommendation = QString("Finaliser %1 reference(s) en brouillon pour consolider le catalogue avant export atelier.")
            .arg(formatPieceStatInteger(draftReferenceCount));
    } else if (yieldPercent < 18.0) {
        recommendation = "Le rendement theorique reste faible. Relancer un plan de nesting sur les references dominantes.";
    } else {
        recommendation = QString("Le flux est exploitable. Priorite actuelle: %1 (%2 unites).")
            .arg(topModel, formatPieceStatInteger(topModelQty));
    }

    QString badges;
    badges += buildHtmlBadge(QString("%1 refs publiees").arg(formatPieceStatInteger(publishedReferenceCount)),
                             "rgba(16,185,129,0.14)",
                             "rgba(52,211,153,0.24)",
                             "#bbf7d0");
    badges += buildHtmlBadge(QString("%1 refs brouillon").arg(formatPieceStatInteger(draftReferenceCount)),
                             "rgba(79,70,229,0.16)",
                             "rgba(129,140,248,0.28)",
                             "#c7d2fe");
    badges += buildHtmlBadge(QString("%1 matieres").arg(formatPieceStatInteger(materialVariety)),
                             "rgba(14,165,233,0.14)",
                             "rgba(56,189,248,0.24)",
                             "#bae6fd");

    QString pipelineHtml;
    if (referenceCount <= 0) {
        pipelineHtml =
            "<div style=\"font-family:'Segoe UI';color:#e2e8f0;padding:4px 2px 10px 2px;\">"
            "<div style=\"padding:18px;border-radius:18px;background:qlineargradient(x1:0,y1:0,x2:1,y2:1,"
            "stop:0 rgba(15,23,42,0.95),stop:1 rgba(30,41,59,0.82));border:1px solid rgba(99,102,241,0.18);\">"
            "<div style=\"font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#818cf8;font-weight:800;\">"
            "Tableau de bord piece</div>"
            "<div style=\"margin-top:10px;font-size:20px;font-weight:800;color:#f8fafc;\">Aucune donnee exploitable</div>"
            "<div style=\"margin-top:8px;color:#cbd5e1;font-size:13px;line-height:1.55;\">"
            "Publiez un premier catalogue de pieces pour activer les graphiques, les tendances et la lecture du flux.</div>"
            "</div></div>";
    } else {
        pipelineHtml =
            "<div style=\"font-family:'Segoe UI';color:#e2e8f0;padding:4px 2px 12px 2px;\">"
            "<div style=\"padding:18px;border-radius:18px;background:qlineargradient(x1:0,y1:0,x2:1,y2:1,"
            "stop:0 rgba(30,41,59,0.96),stop:1 rgba(49,46,129,0.28));border:1px solid rgba(129,140,248,0.22);\">"
            "<div style=\"font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#818cf8;font-weight:800;\">"
            "Lecture operationnelle</div>"
            "<div style=\"margin-top:8px;font-size:20px;font-weight:800;color:#f8fafc;\">"
            + QString("%1 pieces sur %2 references")
                  .arg(formatPieceStatInteger(totalQuantity), formatPieceStatInteger(referenceCount))
            + "</div>"
            "<div style=\"margin-top:8px;font-size:13px;line-height:1.6;color:#cbd5e1;\">"
            + QString("Catalogue publie: %1 unites | Brouillon actif: %2 unites | Surface moyenne: %3")
                  .arg(formatPieceStatInteger(publishedQuantity))
                  .arg(formatPieceStatInteger(draftQuantity))
                  .arg(formatPieceAreaText(averageAreaPerPiece))
            + "</div>"
            "<div style=\"margin-top:12px;line-height:28px;\">"
            + badges
            + "</div></div>";

        pipelineHtml += buildHtmlSection(
            "Cadence recente",
            {
                QString("%1 refs / %2 pieces enregistrees sur 7 jours.")
                    .arg(formatPieceStatInteger(weeklyReferenceCount))
                    .arg(formatPieceStatInteger(weeklyQuantity)),
                QString("Jour le plus charge: %1 avec %2 piece(s).")
                    .arg(busiestDayLabel)
                    .arg(formatPieceStatInteger(busiestDayQty)),
                QString("Modele dominant: %1 (%2 unites).")
                    .arg(topModel, formatPieceStatInteger(topModelQty))
            },
            "rgba(3,105,161,0.12)",
            "rgba(56,189,248,0.20)",
            "#67e8f9");

        pipelineHtml += buildHtmlSection(
            "Lecture catalogue",
            {
                QString("Matiere dominante selon le tri courant: %1.").arg(dominantMaterial),
                QString("Tri actif: %1 / %2.").arg(sortBy, ui->pc_stats_sort_order->currentText()),
                QString("Surface de pieces exploitees: %1 pour un stock theorique de %2.")
                    .arg(formatPieceAreaText(totalPieceArea))
                    .arg(formatPieceAreaText(totalBoisArea))
            },
            "rgba(67,56,202,0.14)",
            "rgba(129,140,248,0.24)",
            "#c4b5fd");

        pipelineHtml += buildHtmlSection(
            "Action recommandee",
            {
                recommendation,
                QString("Rendement theorique: %1 | Perte residuelle: %2.")
                    .arg(formatPieceStatNumber(yieldPercent, 1) + "%")
                    .arg(formatPieceStatNumber(lossPercent, 1) + "%")
            },
            "rgba(6,78,59,0.18)",
            "rgba(52,211,153,0.24)",
            "#86efac");

        pipelineHtml += "</div>";
    }

    ui->txt_pc_stats_pipeline->setHtml(pipelineHtml);

    if (pieceMaterialChartView) {
        QPieSeries *pieSeries = new QPieSeries();
        pieSeries->setHoleSize(0.35);
        const QList<QColor> palette = {
            QColor("#6366f1"),
            QColor("#22c55e"),
            QColor("#f59e0b"),
            QColor("#38bdf8"),
            QColor("#ec4899"),
            QColor("#94a3b8")
        };

        const int maxSlices = qMin(materialStats.size(), 5);
        double otherMetric = 0.0;
        for (int i = 0; i < materialStats.size(); ++i) {
            const MaterialStat &stat = materialStats.at(i);
            if (i < maxSlices) {
                QPieSlice *slice = pieSeries->append(stat.name, qMax(0.0, stat.metric));
                const double share = (totalMetric > 0.0) ? (stat.metric / totalMetric) * 100.0 : 0.0;
                slice->setBrush(palette.value(i, QColor("#94a3b8")));
                slice->setBorderColor(QColor(15, 23, 42, 220));
                slice->setLabel(QString("%1 - %2%")
                                    .arg(stat.name)
                                    .arg(formatPieceStatNumber(share, 1)));
                slice->setLabelVisible(i < 3);
                slice->setExploded(i == 0);
                slice->setExplodeDistanceFactor(i == 0 ? 0.06 : 0.0);
            } else {
                otherMetric += stat.metric;
            }
        }
        if (otherMetric > 0.0) {
            QPieSlice *otherSlice = pieSeries->append("Autres", otherMetric);
            otherSlice->setBrush(palette.last());
            otherSlice->setBorderColor(QColor(15, 23, 42, 220));
            otherSlice->setLabelVisible(true);
        }

        if (pieSeries->slices().isEmpty()) {
            QPieSlice *emptySlice = pieSeries->append("Aucune donnee", 1.0);
            emptySlice->setBrush(QColor("#334155"));
            emptySlice->setBorderColor(QColor("#334155"));
            emptySlice->setLabel("Aucune donnee");
            emptySlice->setLabelVisible(true);
        }

        QChart *materialChart = new QChart();
        materialChart->addSeries(pieSeries);
        applyPieceStatsChartStyle(materialChart, QString("Repartition matiere (%1)").arg(sortBy), true);
        materialChart->legend()->setAlignment(Qt::AlignBottom);

        QChart *oldChart = pieceMaterialChartView->chart();
        pieceMaterialChartView->setChart(materialChart);
        delete oldChart;
    }

    if (pieceTrendChartView) {
        QMap<QDate, int> dailyValues;
        QSqlQuery trendQuery;
        if (trendQuery.exec(
                "SELECT TRUNC(DATE_CREATION) AS D, NVL(SUM(QUANTITE),0) AS QTY "
                "FROM PIECE "
                "WHERE DATE_CREATION >= TRUNC(SYSDATE) - 6 "
                "GROUP BY TRUNC(DATE_CREATION) "
                "ORDER BY D")) {
            while (trendQuery.next()) {
                dailyValues.insert(trendQuery.value(0).toDate(), trendQuery.value(1).toInt());
            }
        }

        QLineSeries *trendSeries = new QLineSeries();
        trendSeries->setName("Production");
        trendSeries->setPointsVisible(true);
        trendSeries->setPointLabelsColor(QColor("#e2e8f0"));
        trendSeries->setPointLabelsFormat("@yPoint");
        trendSeries->setPen(QPen(QColor("#38bdf8"), 3.0));

        QStringList categories;
        const QDate today = QDate::currentDate();
        int maxDayQty = 0;
        for (int offset = 6, pointIndex = 0; offset >= 0; --offset, ++pointIndex) {
            const QDate day = today.addDays(-offset);
            const int qty = dailyValues.value(day, 0);
            categories << day.toString("dd/MM");
            trendSeries->append(pointIndex, qty);
            maxDayQty = qMax(maxDayQty, qty);
        }
        trendSeries->setPointLabelsVisible(maxDayQty <= 24);

        QChart *trendChart = new QChart();
        trendChart->addSeries(trendSeries);
        applyPieceStatsChartStyle(trendChart, "Cadence de production sur 7 jours", false);
        trendChart->legend()->hide();

        QBarCategoryAxis *axisX = new QBarCategoryAxis();
        axisX->append(categories);
        axisX->setLabelsColor(QColor("#cbd5e1"));
        axisX->setGridLineVisible(false);
        axisX->setLinePenColor(QColor("#475569"));

        QValueAxis *axisY = new QValueAxis();
        axisY->setLabelFormat("%d");
        axisY->setMin(0.0);
        axisY->setMax(qMax(1, static_cast<int>(qCeil(maxDayQty * 1.2))));
        axisY->setTickCount(qMin(6, qMax(2, maxDayQty + 2)));
        axisY->setLabelsColor(QColor("#cbd5e1"));
        axisY->setGridLineColor(QColor(71, 85, 105, 120));
        axisY->setLinePenColor(QColor("#475569"));

        trendChart->addAxis(axisX, Qt::AlignBottom);
        trendChart->addAxis(axisY, Qt::AlignLeft);
        trendSeries->attachAxis(axisX);
        trendSeries->attachAxis(axisY);

        QChart *oldChart = pieceTrendChartView->chart();
        pieceTrendChartView->setChart(trendChart);
        delete oldChart;
    }
}

void smartcarpentry::syncPieceAiGeneratorCombos()
{
    auto copyComboContent = [](QComboBox *source, QComboBox *target) {
        if (!source || !target) {
            return;
        }

        const QVariant previousData = target->currentData();
        QSignalBlocker blocker(target);
        target->clear();
        for (int i = 0; i < source->count(); ++i) {
            target->addItem(source->itemText(i), source->itemData(i));
            target->setItemData(i, source->itemData(i, Qt::UserRole + 1), Qt::UserRole + 1);
        }
        int restoreIndex = target->findData(previousData);
        if (restoreIndex < 0 && target->count() > 0) {
            restoreIndex = 0;
        }
        if (restoreIndex >= 0) {
            target->setCurrentIndex(restoreIndex);
        }
    };

    copyComboContent(ui->pc_modele, pieceAiModeleCombo);
    copyComboContent(ui->pc_matiere, pieceAiBoisCombo);
}

bool smartcarpentry::capturePieceVoiceText(QString &transcribedText) const
{
    transcribedText.clear();
    const QMessageBox::StandardButton ready = QMessageBox::information(
        const_cast<smartcarpentry *>(this),
        "Dictee Vosk",
        "La reconnaissance vocale Vosk va enregistrer votre microphone puis transcrire l'audio localement.\n\n"
        "Assurez-vous que le micro est autorise et que le modele Vosk est present.",
        QMessageBox::Ok | QMessageBox::Cancel,
        QMessageBox::Ok);
    if (ready != QMessageBox::Ok) {
        return false;
    }

    QByteArray pcmData;
    int sampleRate = 0;
    int channelCount = 0;
    QString errorMessage;
    if (!recordPieceVoiceSample(pcmData, sampleRate, channelCount, errorMessage)) {
        QMessageBox::warning(const_cast<smartcarpentry *>(this), "Dictee Vosk", errorMessage);
        return false;
    }

    if (!transcribePieceVoiceWithVosk(pcmData, sampleRate, channelCount, transcribedText, errorMessage)) {
        QMessageBox::warning(const_cast<smartcarpentry *>(this), "Dictee Vosk", errorMessage);
        return false;
    }

    if (pieceAiStatusLabel) {
        pieceAiStatusLabel->setText(
            QString("Audio transcrit localement par Vosk (%1 Hz, %2 canal(aux)).")
                .arg(sampleRate)
                .arg(channelCount));
    }
    return true;
}

bool smartcarpentry::recordPieceVoiceSample(QByteArray &pcmData,
                                            int &sampleRate,
                                            int &channelCount,
                                            QString &errorMessage) const
{
    pcmData.clear();
    sampleRate = 0;
    channelCount = 0;
    errorMessage.clear();

    const QAudioDevice inputDevice = QMediaDevices::defaultAudioInput();
    if (inputDevice.isNull()) {
        errorMessage = "Aucun microphone par defaut n'est disponible sur cette machine.";
        return false;
    }

    QAudioFormat selectedFormat;
    const QList<int> sampleRates = {16000, 44100, 48000};
    const QList<int> channelCounts = {1, 2};
    for (int rate : sampleRates) {
        for (int channels : channelCounts) {
            QAudioFormat candidate;
            candidate.setSampleRate(rate);
            candidate.setChannelCount(channels);
            candidate.setSampleFormat(QAudioFormat::Int16);
            if (inputDevice.isFormatSupported(candidate)) {
                selectedFormat = candidate;
                break;
            }
        }
        if (selectedFormat.isValid()) {
            break;
        }
    }

    if (!selectedFormat.isValid()) {
        const QAudioFormat preferred = inputDevice.preferredFormat();
        if (preferred.sampleFormat() == QAudioFormat::Int16
            && (preferred.channelCount() == 1 || preferred.channelCount() == 2)) {
            selectedFormat = preferred;
        }
    }

    if (!selectedFormat.isValid()) {
        errorMessage = "Le microphone ne propose pas un format PCM 16 bits compatible pour Vosk.";
        return false;
    }

    sampleRate = selectedFormat.sampleRate();
    channelCount = selectedFormat.channelCount();

    QBuffer audioBuffer;
    audioBuffer.open(QIODevice::WriteOnly);

    QAudioSource audioSource(inputDevice, selectedFormat);
    audioSource.setBufferSize(sampleRate * channelCount * static_cast<int>(sizeof(qint16)) * 2);
    audioSource.start(&audioBuffer);
    if (audioSource.error() != QtAudio::NoError) {
        errorMessage = "Impossible de demarrer l'enregistrement audio depuis le microphone.";
        return false;
    }

    const int recordDurationMs = 9000;
    QProgressDialog progress(
        "Enregistrement du microphone en cours...\nParlez clairement, a 15-25 cm du micro.",
        "Annuler",
        0,
        recordDurationMs,
        const_cast<smartcarpentry *>(this));
    progress.setWindowTitle("Capture audio");
    progress.setWindowModality(Qt::ApplicationModal);
    progress.setMinimumDuration(0);
    progress.setValue(0);
    progress.show();

    int elapsed = 0;
    while (elapsed < recordDurationMs) {
        if (progress.wasCanceled()) {
            audioSource.stop();
            audioBuffer.close();
            errorMessage = "L'enregistrement audio a ete annule.";
            return false;
        }

        QThread::msleep(100);
        elapsed += 100;
        progress.setValue(elapsed);
        QCoreApplication::processEvents(QEventLoop::AllEvents, 100);
    }

    audioSource.stop();
    progress.setValue(recordDurationMs);
    audioBuffer.close();

    pcmData = audioBuffer.data();
    if (pcmData.isEmpty()) {
        errorMessage = "Aucune donnee audio n'a ete capturee depuis le microphone.";
        return false;
    }

    const int peakLevel = computePcmPeakLevel(pcmData);
    if (peakLevel < 250) {
        errorMessage =
            "Le signal micro capture est trop faible pour une transcription fiable.\n"
            "Rapprochez-vous du microphone et augmentez le volume d'entree Windows.";
        return false;
    }

    return true;
}

QString smartcarpentry::resolveVoskPythonExecutable() const
{
    const auto normalizeExecutable = [](const QString &candidate) -> QString {
        const QString trimmed = candidate.trimmed();
        if (trimmed.isEmpty()) {
            return QString();
        }

        const QString fromPath = QStandardPaths::findExecutable(trimmed);
        if (!fromPath.isEmpty()) {
            return QDir::fromNativeSeparators(QFileInfo(fromPath).absoluteFilePath());
        }

        const QFileInfo fileInfo(trimmed);
        if (fileInfo.exists() && fileInfo.isFile()) {
            return QDir::fromNativeSeparators(fileInfo.absoluteFilePath());
        }

        return QString();
    };

    const auto hasVoskModule = [](const QString &pythonExecutable) -> bool {
        if (pythonExecutable.trimmed().isEmpty()) {
            return false;
        }

        QProcess probe;
        probe.setProgram(pythonExecutable);
        probe.setArguments({"-c", "import vosk;print('ok')"});
        probe.start();
        if (!probe.waitForStarted(1500)) {
            return false;
        }
        if (!probe.waitForFinished(5000)) {
            probe.kill();
            probe.waitForFinished(500);
            return false;
        }
        if (probe.exitStatus() != QProcess::NormalExit || probe.exitCode() != 0) {
            return false;
        }
        const QString output = QString::fromUtf8(probe.readAllStandardOutput()).trimmed();
        return output.contains("ok");
    };

    QStringList candidates;
    QSet<QString> seen;

    const auto addCandidate = [&](const QString &candidate) {
        const QString normalized = normalizeExecutable(candidate);
        if (normalized.isEmpty() || seen.contains(normalized)) {
            return;
        }
        seen.insert(normalized);
        candidates << normalized;
    };

    const QString explicitPython = qEnvironmentVariable("VOSK_PYTHON_EXECUTABLE").trimmed();
    if (!explicitPython.isEmpty()) {
        addCandidate(explicitPython);
    }

    addCandidate("python");
    addCandidate("python3");

    const QStringList roots = {
        QDir::currentPath(),
        QCoreApplication::applicationDirPath()
    };
    for (const QString &root : roots) {
        addCandidate(QDir(root).filePath(".venv/Scripts/python.exe"));
        addCandidate(QDir(root).filePath("venv/Scripts/python.exe"));
    }

    addCandidate(QDir::home().filePath("AppData/Local/Programs/Python/Python312/python.exe"));
    addCandidate(QDir::home().filePath("AppData/Local/Programs/Python/Python311/python.exe"));
    addCandidate(QDir::home().filePath("AppData/Local/Programs/Python/Python310/python.exe"));
    addCandidate(QDir::home().filePath("AppData/Local/Programs/Python/Python39/python.exe"));
    addCandidate(QDir::home().filePath("AppData/Local/Programs/Python/Python38/python.exe"));
    addCandidate(QDir::home().filePath("AppData/Local/Programs/Python/Python37/python.exe"));
    addCandidate("C:/Program Files (x86)/ThonnyTN/python.exe");
    addCandidate("C:/Program Files/Autodesk/3ds Max 2021/Python37/python.exe");

    for (const QString &candidate : candidates) {
        if (hasVoskModule(candidate)) {
            return candidate;
        }
    }

    if (!candidates.isEmpty()) {
        return candidates.first();
    }

    return "python";
}

namespace {

QStringList buildVoskSearchRoots()
{
    QStringList roots;
    QSet<QString> seen;

    const auto addPath = [&](const QString &path) {
        if (path.trimmed().isEmpty()) {
            return;
        }

        const QFileInfo info(path);
        QString normalized = info.exists()
                                 ? info.canonicalFilePath()
                                 : QDir::cleanPath(info.absoluteFilePath());
        if (normalized.isEmpty()) {
            normalized = QDir::cleanPath(path);
        }

        if (!seen.contains(normalized)) {
            seen.insert(normalized);
            roots << normalized;
        }
    };

    addPath(QDir::currentPath());
    addPath(QCoreApplication::applicationDirPath());

    QDir appDir(QCoreApplication::applicationDirPath());
    for (int depth = 0; depth < 6; ++depth) {
        addPath(appDir.absolutePath());
        if (!appDir.cdUp()) {
            break;
        }
    }

    QDir sourceDir(QFileInfo(QString::fromUtf8(__FILE__)).absolutePath());
    for (int depth = 0; depth < 6; ++depth) {
        addPath(sourceDir.absolutePath());
        if (!sourceDir.cdUp()) {
            break;
        }
    }

    return roots;
}

QString resolveExistingVoskModelDir(const QString &basePath)
{
    const QFileInfo baseInfo(basePath);
    if (!baseInfo.exists()) {
        return QString();
    }

    const QStringList preferredModels = {
        "vosk-model-fr-0.22",
        "vosk-model-small-fr-0.22",
        "vosk-model-small-en-us-0.15"
    };

    const auto looksLikeModelDir = [](const QString &candidatePath) -> bool {
        const QDir dir(candidatePath);
        return dir.exists("am") && dir.exists("conf") && dir.exists("graph");
    };

    if (baseInfo.isDir() && looksLikeModelDir(baseInfo.absoluteFilePath())) {
        return QDir::cleanPath(baseInfo.absoluteFilePath());
    }

    const QStringList rootsToScan = {
        QDir::cleanPath(baseInfo.absoluteFilePath()),
        QDir(QDir::cleanPath(baseInfo.absoluteFilePath())).filePath("models")
    };

    for (const QString &rootPath : rootsToScan) {
        const QDir rootDir(rootPath);
        if (!rootDir.exists()) {
            continue;
        }

        for (const QString &modelName : preferredModels) {
            const QString candidate = rootDir.filePath(modelName);
            if (looksLikeModelDir(candidate)) {
                return QDir::cleanPath(candidate);
            }
        }

        const QFileInfoList entries = rootDir.entryInfoList(QStringList() << "vosk-model*",
                                                            QDir::Dirs | QDir::NoDotAndDotDot);
        for (const QFileInfo &entry : entries) {
            if (looksLikeModelDir(entry.absoluteFilePath())) {
                return QDir::cleanPath(entry.absoluteFilePath());
            }
        }
    }

    return QString();
}

} // namespace

QString smartcarpentry::resolveVoskModelPath(QString &errorMessage) const
{
    errorMessage.clear();

    const QString explicitModel = qEnvironmentVariable("VOSK_MODEL_PATH").trimmed();
    if (!explicitModel.isEmpty()) {
        const QString resolvedExplicitModel = resolveExistingVoskModelDir(explicitModel);
        if (!resolvedExplicitModel.isEmpty()) {
            return QDir::fromNativeSeparators(resolvedExplicitModel);
        }
    }

    const QStringList roots = buildVoskSearchRoots();
    QStringList triedLocations;
    QSet<QString> reported;

    for (const QString &root : roots) {
        const QString normalizedRoot = QDir::cleanPath(root);
        if (!reported.contains(normalizedRoot)) {
            reported.insert(normalizedRoot);
            triedLocations << normalizedRoot;
        }

        const QString resolvedModel = resolveExistingVoskModelDir(normalizedRoot);
        if (!resolvedModel.isEmpty()) {
            return resolvedModel;
        }
    }

    errorMessage =
        "Aucun modele Vosk n'a ete trouve.\n"
        "Placez un modele dans le dossier models/ ou configurez VOSK_MODEL_PATH.\n\n"
        "Chemins verifies :\n - " + triedLocations.join("\n - ");
    return QString();
}

QString smartcarpentry::resolveVoskScriptPath(QString &errorMessage) const
{
    errorMessage.clear();

    const QString explicitScript = qEnvironmentVariable("VOSK_SCRIPT_PATH").trimmed();
    if (!explicitScript.isEmpty() && QFileInfo::exists(explicitScript)) {
        return QDir::fromNativeSeparators(explicitScript);
    }

    const QStringList roots = buildVoskSearchRoots();
    QStringList triedLocations;
    QSet<QString> reported;

    for (const QString &root : roots) {
        const QDir baseDir(QDir::cleanPath(root));
        const QStringList candidates = {
            baseDir.filePath("tools/vosk_transcribe.py"),
            baseDir.filePath("vosk_transcribe.py")
        };

        for (const QString &candidate : candidates) {
            const QString normalizedCandidate = QDir::cleanPath(candidate);
            if (!reported.contains(normalizedCandidate)) {
                reported.insert(normalizedCandidate);
                triedLocations << normalizedCandidate;
            }

            if (QFileInfo::exists(normalizedCandidate)) {
                return normalizedCandidate;
            }
        }
    }

    errorMessage =
        "Le script tools/vosk_transcribe.py est introuvable.\n"
        "Verifiez l'integration Vosk locale.\n\n"
        "Chemins verifies :\n - " + triedLocations.join("\n - ");
    return QString();
}

bool smartcarpentry::transcribePieceVoiceWithVosk(const QByteArray &pcmData,
                                                  int sampleRate,
                                                  int channelCount,
                                                  QString &transcribedText,
                                                  QString &errorMessage) const
{
    transcribedText.clear();
    errorMessage.clear();

    QString pathError;
    const QString modelPath = resolveVoskModelPath(pathError);
    if (modelPath.isEmpty()) {
        errorMessage = pathError;
        return false;
    }

    const QString scriptPath = resolveVoskScriptPath(pathError);
    if (scriptPath.isEmpty()) {
        errorMessage = pathError;
        return false;
    }

    const QString pythonExecutable = resolveVoskPythonExecutable();

    QTemporaryFile pcmFile(QDir::tempPath() + QDir::separator() + "piece-vosk-XXXXXX.pcm");
    pcmFile.setAutoRemove(true);
    if (!pcmFile.open()) {
        errorMessage = "Impossible de preparer un fichier temporaire pour la transcription Vosk.";
        return false;
    }
    if (pcmFile.write(pcmData) != pcmData.size()) {
        errorMessage = "Impossible d'ecrire l'audio temporaire pour Vosk.";
        return false;
    }
    pcmFile.flush();
    const QString pcmPath = pcmFile.fileName();
    pcmFile.close();

    QProcess process;
    process.setProgram(pythonExecutable);
    process.setArguments({
        scriptPath,
        "--model", modelPath,
        "--pcm", pcmPath,
        "--rate", QString::number(sampleRate),
        "--channels", QString::number(channelCount)
    });

    QProgressDialog progress(
        "Transcription Vosk en cours...\nAnalyse locale de l'audio.",
        "Annuler",
        0,
        0,
        const_cast<smartcarpentry *>(this));
    progress.setWindowTitle("Transcription Vosk");
    progress.setWindowModality(Qt::ApplicationModal);
    progress.setMinimumDuration(0);
    progress.setAutoClose(false);
    progress.setAutoReset(false);
    progress.show();

    process.start();
    if (!process.waitForStarted(3000)) {
        errorMessage = "Impossible de lancer Python pour la transcription Vosk.";
        return false;
    }

    while (process.state() != QProcess::NotRunning) {
        if (progress.wasCanceled()) {
            process.kill();
            process.waitForFinished(2000);
            errorMessage = "La transcription Vosk a ete annulee.";
            return false;
        }
        QCoreApplication::processEvents(QEventLoop::AllEvents, 100);
        process.waitForFinished(100);
    }
    progress.close();

    const QString stdOut = QString::fromUtf8(process.readAllStandardOutput()).trimmed();
    const QString stdErr = QString::fromUtf8(process.readAllStandardError()).trimmed();
    if (process.exitStatus() != QProcess::NormalExit || process.exitCode() != 0) {
        errorMessage = stdErr.isEmpty() ? "La transcription Vosk a echoue." : stdErr;
        return false;
    }

    QJsonParseError parseError;
    const QJsonDocument jsonDoc = QJsonDocument::fromJson(stdOut.toUtf8(), &parseError);
    if (parseError.error != QJsonParseError::NoError || !jsonDoc.isObject()) {
        errorMessage = stdErr.isEmpty()
            ? QString("Reponse Vosk invalide : %1").arg(parseError.errorString())
            : stdErr;
        return false;
    }

    const QJsonObject root = jsonDoc.object();
    if (!root.value("ok").toBool()) {
        errorMessage = root.value("error").toString().trimmed();
        if (errorMessage.isEmpty()) {
            errorMessage = stdErr.isEmpty() ? "La transcription Vosk a echoue." : stdErr;
        }
        return false;
    }

    transcribedText = root.value("text").toString().trimmed();
    if (transcribedText.isEmpty()) {
        errorMessage = "La transcription Vosk recue est vide.";
        return false;
    }

    return true;
}

bool smartcarpentry::processPieceVoiceInput(bool autoInsert)
{
    QString transcribedText;
    if (!capturePieceVoiceText(transcribedText)) {
        return false;
    }

    const QString normalizedTranscript = normalizeSpokenPieceInput(transcribedText);

    if (pieceAiPromptEdit) {
        pieceAiPromptEdit->setPlainText(normalizedTranscript);
    }

    PieceDraft parsedDraft;
    QString parseError;
    QStringList warnings;
    int suggestedBoisId = 0;
    if (!extractPieceFromNaturalLanguage(normalizedTranscript,
                                         parsedDraft,
                                         parseError,
                                         &warnings,
                                         &suggestedBoisId)) {
        updatePieceAiPreview(parseError, true);
        QMessageBox::warning(this, "Dictee Vosk", parseError);
        return false;
    }

    if (pieceAiBoisCombo && suggestedBoisId > 0) {
        const int comboIndex = pieceAiBoisCombo->findData(suggestedBoisId);
        if (comboIndex >= 0) {
            pieceAiBoisCombo->setCurrentIndex(comboIndex);
        }
    }

    QString preview = QString("Nom : %1\nType / matiere : %2\nLongueur : %3 mm\nLargeur : %4 mm\nQuantite estimee : %5")
        .arg(parsedDraft.nom,
             parsedDraft.matiere,
             formatPieceStatNumber(parsedDraft.longueurMm, 0),
             formatPieceStatNumber(parsedDraft.largeurMm, 0),
             formatPieceStatInteger(parsedDraft.quantite));
    if (!warnings.isEmpty()) {
        preview += "\n\nNotes :\n- " + warnings.join("\n- ");
    }
    updatePieceAiPreview(preview, false);

    if (!autoInsert) {
        QMessageBox::information(
            this,
            "Dictee Vosk",
            "La transcription Vosk a ete chargee et analysee.\n"
            "Verifiez l'apercu puis cliquez sur Inserer dans PIECE si le resultat vous convient.");
        return true;
    }

    if (false) {
        QMessageBox::information(
            this,
            "Vosk obsolete",
            "La transcription vocale a ete chargee et analysee.\n"
            "Verifiez l'apercu puis cliquez sur Inserer dans PIECE si le resultat vous convient.");
        return true;
    }

    QString insertError;
    if (!insertGeneratedPieceFromText(normalizedTranscript, insertError)) {
        updatePieceAiPreview(insertError, true);
        QMessageBox::warning(this, "Insertion Vosk", insertError);
        return false;
    }

    QString confirmationText =
        QString("Piece inseree avec succes depuis Vosk.\n\n"
                "Nom : %1\n"
                "Type / matiere : %2\n"
                "Dimensions : %3 x %4 mm\n"
                "Quantite : %5")
            .arg(parsedDraft.nom,
                 parsedDraft.matiere,
                 formatPieceStatNumber(parsedDraft.longueurMm, 0),
                 formatPieceStatNumber(parsedDraft.largeurMm, 0),
                 formatPieceStatInteger(parsedDraft.quantite));
    if (!warnings.isEmpty()) {
        confirmationText += "\n\nNotes :\n- " + warnings.join("\n- ");
    }

    QMessageBox::information(this, "Insertion Vosk", confirmationText);
    return true;
}

bool smartcarpentry::extractPieceFromNaturalLanguage(const QString &input,
                                                     PieceDraft &draft,
                                                     QString &errorMessage,
                                                     QStringList *warnings,
                                                     int *suggestedBoisId) const
{
    errorMessage.clear();
    draft = PieceDraft();
    if (warnings) {
        warnings->clear();
    }
    if (suggestedBoisId) {
        *suggestedBoisId = 0;
    }

    const QString rawInput = input.trimmed();
    if (rawInput.isEmpty()) {
        errorMessage = "Saisissez d'abord une description naturelle de la piece.";
        return false;
    }

    const QString workingInput = normalizeSpokenPieceInput(rawInput);
    const QString normalizedInput = normalizeLookupText(workingInput);

    int quantity = 1;
    QRegularExpressionMatch quantityMatch = QRegularExpression(
        "\\b(?:quantite|qte|nombre)\\s*[:=]?\\s*(\\d+)\\b",
        QRegularExpression::CaseInsensitiveOption).match(workingInput);
    if (quantityMatch.hasMatch()) {
        quantity = qMax(1, quantityMatch.captured(1).toInt());
    } else {
        quantityMatch = QRegularExpression(
            "\\b(\\d+)\\s*(?:piece|pieces|panneau|panneaux|planche|planches|traverse|traverses|element|elements|unite|unites|lot|lots|pied|pieds)\\b",
            QRegularExpression::CaseInsensitiveOption).match(workingInput);
        if (quantityMatch.hasMatch()) {
            quantity = qMax(1, quantityMatch.captured(1).toInt());
        } else {
            const QStringList tokens = normalizedInput.split(' ', Qt::SkipEmptyParts);
            for (int i = 0; i + 1 < tokens.size(); ++i) {
                const int wordQty = parseFrenchQuantityWord(tokens.at(i));
                if (wordQty > 0) {
                    quantity = wordQty;
                    break;
                }
            }
        }
    }

    double longueurMm = 0.0;
    double largeurMm = 0.0;
    bool explicitUnitFound = false;

    QRegularExpressionMatch dimsMatch = QRegularExpression(
        "(\\d+(?:[\\.,]\\d+)?)\\s*(?:x|-|par|sur|fois)\\s*(\\d+(?:[\\.,]\\d+)?)\\s*(mm|millimetres|cm|centimetres|m|metres)?",
        QRegularExpression::CaseInsensitiveOption).match(workingInput);
    if (dimsMatch.hasMatch()) {
        const QString unit = dimsMatch.captured(3);
        longueurMm = toMillimeters(dimsMatch.captured(1).replace(',', '.').toDouble(), unit, &explicitUnitFound);
        bool widthUnitExplicit = false;
        largeurMm = toMillimeters(dimsMatch.captured(2).replace(',', '.').toDouble(), unit, &widthUnitExplicit);
        explicitUnitFound = explicitUnitFound || widthUnitExplicit;
    } else {
        const QRegularExpression lengthRegex(
            "\\b(?:longueur|long|l)\\s*[:=]?\\s*(\\d+(?:[\\.,]\\d+)?)\\s*(mm|millimetres|millimetres|cm|centimetres|centimetres|m|metres|metres)?",
            QRegularExpression::CaseInsensitiveOption);
        const QRegularExpression widthRegex(
            "\\b(?:largeur|larg|la)\\s*[:=]?\\s*(\\d+(?:[\\.,]\\d+)?)\\s*(mm|millimetres|millimetres|cm|centimetres|centimetres|m|metres|metres)?",
            QRegularExpression::CaseInsensitiveOption);
        const QRegularExpressionMatch lengthMatch = lengthRegex.match(workingInput);
        const QRegularExpressionMatch widthMatch = widthRegex.match(workingInput);

        if (lengthMatch.hasMatch()) {
            bool localExplicitUnit = false;
            longueurMm = toMillimeters(lengthMatch.captured(1).replace(',', '.').toDouble(),
                                       lengthMatch.captured(2),
                                       &localExplicitUnit);
            explicitUnitFound = explicitUnitFound || localExplicitUnit;
        }
        if (widthMatch.hasMatch()) {
            bool localExplicitUnit = false;
            largeurMm = toMillimeters(widthMatch.captured(1).replace(',', '.').toDouble(),
                                      widthMatch.captured(2),
                                      &localExplicitUnit);
            explicitUnitFound = explicitUnitFound || localExplicitUnit;
        }
    }

    if (longueurMm <= 0.0 || largeurMm <= 0.0) {
        errorMessage = "Impossible d'extraire une longueur et une largeur valides. Exemple attendu: 1200 x 450 mm.";
        return false;
    }

    if (!explicitUnitFound && warnings) {
        warnings->append("Aucune unite detectee. Les dimensions ont ete interpretees en millimetres.");
    }

    QString detectedMaterial;
    int detectedBoisId = 0;
    int bestMatchLength = 0;
    auto evaluateMaterialCandidate = [&](const QString &candidate, int boisId) {
        const QString normalizedCandidate = normalizeLookupText(candidate);
        if (normalizedCandidate.isEmpty()) {
            return;
        }
        if (normalizedInput.contains(normalizedCandidate) && normalizedCandidate.size() > bestMatchLength) {
            bestMatchLength = normalizedCandidate.size();
            detectedMaterial = candidate.trimmed();
            detectedBoisId = boisId;
        }
    };

    auto scanComboCandidates = [&](QComboBox *combo) {
        if (!combo) {
            return;
        }
        for (int i = 0; i < combo->count(); ++i) {
            const QString displayMaterial = combo->itemData(i, Qt::UserRole + 1).toString().trimmed();
            const QString fallbackMaterial = combo->itemText(i).trimmed();
            evaluateMaterialCandidate(displayMaterial.isEmpty() ? fallbackMaterial : displayMaterial,
                                      combo->itemData(i).toInt());
            evaluateMaterialCandidate(fallbackMaterial, combo->itemData(i).toInt());
        }
    };

    scanComboCandidates(pieceAiBoisCombo);
    scanComboCandidates(ui->pc_matiere);

    const QList<QPair<QString, QString>> genericMaterials = {
        {"contreplaque", "Contreplaque"},
        {"contre plaque", "Contreplaque"},
        {"mdf", "MDF"},
        {"hdf", "HDF"},
        {"osb", "OSB"},
        {"agglomere", "Agglomere"},
        {"melamine", "Melamine"},
        {"bois massif", "Bois massif"},
        {"chene", "Chene"},
        {"hetre", "Hetre"},
        {"pin", "Pin"}
    };
    for (const auto &entry : genericMaterials) {
        if (normalizedInput.contains(entry.first) && entry.first.size() > bestMatchLength) {
            bestMatchLength = entry.first.size();
            detectedMaterial = entry.second;
        }
    }

    if (detectedMaterial.isEmpty()) {
        if (pieceAiBoisCombo && pieceAiBoisCombo->count() > 0) {
            detectedMaterial = pieceAiBoisCombo->currentData(Qt::UserRole + 1).toString().trimmed();
            if (detectedMaterial.isEmpty()) {
                detectedMaterial = pieceAiBoisCombo->currentText().trimmed();
            }
            detectedBoisId = pieceAiBoisCombo->currentData().toInt();
            if (warnings) {
                warnings->append("Aucune matiere explicite detectee. Le bois cible courant a ete reutilise.");
            }
        } else {
            detectedMaterial = "Non definie";
        }
    }

    if (suggestedBoisId) {
        *suggestedBoisId = detectedBoisId;
    }

    QString nameCandidate = workingInput;
    nameCandidate.remove(QRegularExpression(
        "(\\d+(?:[\\.,]\\d+)?)\\s*(?:x|-|par|sur|fois)\\s*(\\d+(?:[\\.,]\\d+)?)\\s*(mm|millimetres|cm|centimetres|m|metres)?",
        QRegularExpression::CaseInsensitiveOption));
    nameCandidate.remove(QRegularExpression(
        "\\b(?:longueur|long|largeur|larg|quantite|qte|nombre)\\s*[:=]?\\s*\\d+(?:[\\.,]\\d+)?\\s*(?:mm|cm|m)?",
        QRegularExpression::CaseInsensitiveOption));
    nameCandidate.remove(QRegularExpression(
        "\\b\\d+\\s*(?:piece|pieces|panneau|panneaux|planche|planches|traverse|traverses|element|elements|unite|unites|lot|lots|pied|pieds)\\b",
        QRegularExpression::CaseInsensitiveOption));
    for (const auto &entry : genericMaterials) {
        nameCandidate.remove(QRegularExpression(QString("\\b%1\\b").arg(QRegularExpression::escape(entry.first)),
                                               QRegularExpression::CaseInsensitiveOption));
    }
    if (!detectedMaterial.isEmpty()) {
        nameCandidate.remove(QRegularExpression(QString("\\b%1\\b").arg(QRegularExpression::escape(detectedMaterial)),
                                               QRegularExpression::CaseInsensitiveOption));
    }
    nameCandidate.remove(QRegularExpression(
        "\\b(?:ajouter|ajoute|cree|creer|creez|genere|generer|inserer|insere|je|veux|voudrais|svp|sil|te|plait|merci|en|avec|pour|sur|dans|du|des|de|la|le|les|une|un|bois|type|matiere)\\b",
        QRegularExpression::CaseInsensitiveOption));
    nameCandidate.replace(QRegularExpression("[,:;_\\-]+"), " ");
    nameCandidate = toTitleCaseWords(nameCandidate);
    if (nameCandidate.isEmpty()) {
        nameCandidate = detectedMaterial.isEmpty() ? QString("Piece IA") : QString("Piece %1").arg(detectedMaterial);
    }

    draft.nom = nameCandidate.left(100);
    draft.code = buildAiPieceCode(draft.nom, detectedMaterial);
    draft.quantite = qMax(1, quantity);
    draft.matiere = detectedMaterial.left(50);
    draft.longueurMm = longueurMm;
    draft.largeurMm = largeurMm;
    draft.epaisseurMm = 18.0;
    draft.sourceGeneration = "AUTO_IA";

    if (!PieceWorkflowService::validateDraft(draft, errorMessage)) {
        return false;
    }
    return true;
}

bool smartcarpentry::insertGeneratedPieceFromText(const QString &input, QString &errorMessage)
{
    errorMessage.clear();

    if (!pieceAiModeleCombo || !pieceAiBoisCombo) {
        errorMessage = "Le generateur IA n'est pas initialise.";
        return false;
    }

    const int modeleId = pieceAiModeleCombo->currentData().toInt();
    int boisId = pieceAiBoisCombo->currentData().toInt();
    if (!Piece::validerForeignKey(modeleId) || !Piece::validerForeignKey(boisId)) {
        errorMessage = "Selectionnez un modele cible et un bois cible valides.";
        return false;
    }

    PieceDraft draft;
    QStringList warnings;
    int suggestedBoisId = 0;
    if (!extractPieceFromNaturalLanguage(input, draft, errorMessage, &warnings, &suggestedBoisId)) {
        return false;
    }

    if (suggestedBoisId > 0) {
        const int comboIndex = pieceAiBoisCombo->findData(suggestedBoisId);
        if (comboIndex >= 0) {
            pieceAiBoisCombo->setCurrentIndex(comboIndex);
            boisId = suggestedBoisId;
        }
    }

    QString boisError;
    const BoisPieceContext boisContext = loadBoisPieceContext(boisId, &boisError);
    if (!boisError.isEmpty()) {
        errorMessage = boisError;
        return false;
    }

    Piece piece;
    piece.setNomPiece(draft.nom);
    piece.setCodePiece(draft.code);
    piece.setQuantite(draft.quantite);
    piece.setMatiere(draft.matiere.isEmpty() ? boisContext.nom : draft.matiere);
    piece.setLongueurMm(draft.longueurMm);
    piece.setLargeurMm(draft.largeurMm);
    piece.setEpaisseurMm(boisContext.epaisseur > 0.0 ? boisContext.epaisseur : 18.0);
    piece.setDateCreation(QDate::currentDate());
    piece.setIdModele(modeleId);
    piece.setIdBois(boisId);
    piece.setStatus(PieceStatus::Published);
    piece.setSourceGeneration("AUTO_IA");
    piece.setUpdatedAt(QDateTime::currentDateTime());

    QString insertError;
    if (!PieceRepository::addPublishedPiece(piece, insertError)) {
        errorMessage = insertError;
        return false;
    }

    const QString modeleLabel = pieceAiModeleCombo->currentText().trimmed();
    const QString boisLabel = pieceAiBoisCombo->currentText().trimmed();
    appendPieceAiHistoryRow(piece, modeleLabel, boisLabel);
    refreshPieceTable();
    refreshPieceGenerationContext();
    if (modeleId == pieceContextModeleId && boisId == pieceContextBoisId) {
        restorePieceWorkflowState(PieceWorkflowStateRepository::loadWorkflowState(modeleId, boisId, nullptr));
    }

    QString preview = QString("Insertion reussie.\nNom : %1\nType / matiere : %2\nLongueur : %3 mm\nLargeur : %4 mm\nQuantite : %5")
        .arg(piece.getNomPiece(),
             piece.getMatiere(),
             formatPieceStatNumber(piece.getLongueurMm(), 0),
             formatPieceStatNumber(piece.getLargeurMm(), 0),
             formatPieceStatInteger(piece.getQuantite()));
    if (!warnings.isEmpty()) {
        preview += "\n\nNotes :\n- " + warnings.join("\n- ");
    }
    updatePieceAiPreview(preview, false);
    if (pieceAiPromptEdit) {
        pieceAiPromptEdit->clear();
    }
    return true;
}

void smartcarpentry::updatePieceAiPreview(const QString &message, bool isError)
{
    if (pieceAiPreviewLabel) {
        pieceAiPreviewLabel->setText(message);
        pieceAiPreviewLabel->setStyleSheet(QString(
            "background: %1;"
            "border: 1px solid %2;"
            "border-radius: 14px;"
            "padding: 14px 16px;"
            "color: %3;"
            "font-size: 13px;"
            "font-weight: 600;")
            .arg(isError ? "rgba(127,29,29,0.30)" : "rgba(30,41,59,0.72)",
                 isError ? "rgba(248,113,113,0.28)" : "rgba(99,102,241,0.16)",
                 isError ? "#fecaca" : "#e2e8f0"));
    }
    if (pieceAiStatusLabel) {
        pieceAiStatusLabel->setText(isError
            ? QString("Insertion bloquee: %1").arg(message)
            : "Extraction validee. Vous pouvez enrichir le texte ou inserer une nouvelle piece.");
        pieceAiStatusLabel->setStyleSheet(QString(
            "background: %1;"
            "border: 1px solid %2;"
            "border-radius: 14px;"
            "padding: 12px 14px;"
            "color: %3;"
            "font-size: 12px;")
            .arg(isError ? "rgba(127,29,29,0.22)" : "rgba(15,23,42,0.56)",
                 isError ? "rgba(248,113,113,0.24)" : "rgba(52,211,153,0.14)",
                 isError ? "#fecaca" : "#bbf7d0"));
    }
}

void smartcarpentry::appendPieceAiHistoryRow(const Piece &piece,
                                             const QString &modeleLabel,
                                             const QString &boisLabel)
{
    if (!pieceWidget) {
        return;
    }

    pieceWidget->insertRow(0);
    const QStringList values = {
        piece.getNomPiece(),
        piece.getMatiere(),
        QString("%1 mm").arg(formatPieceStatNumber(piece.getLongueurMm(), 0)),
        QString("%1 mm").arg(formatPieceStatNumber(piece.getLargeurMm(), 0)),
        formatPieceStatInteger(piece.getQuantite()),
        modeleLabel,
        boisLabel,
        piece.getSourceGeneration()
    };

    for (int column = 0; column < values.size(); ++column) {
        QTableWidgetItem *item = new QTableWidgetItem(values.at(column));
        item->setTextAlignment(Qt::AlignCenter);
        item->setForeground(QBrush(QColor("#e2e8f0")));
        if (column == 7) {
            item->setForeground(QBrush(QColor("#a5b4fc")));
        }
        pieceWidget->setItem(0, column, item);
    }

    while (pieceWidget->rowCount() > 12) {
        pieceWidget->removeRow(pieceWidget->rowCount() - 1);
    }

    if (ui->tabWidget_pc && pieceAiGeneratorTab) {
        const int aiTabIndex = ui->tabWidget_pc->indexOf(pieceAiGeneratorTab);
        if (aiTabIndex >= 0) {
            ui->tabWidget_pc->setTabText(aiTabIndex,
                                         QString("Insertion par voix | %1 inserts")
                                             .arg(formatPieceStatInteger(pieceWidget->rowCount())));
            ui->tabWidget_pc->setTabToolTip(aiTabIndex,
                                            "Description naturelle, extraction automatique et insertion directe dans PIECE.");
        }
    }
}

// ============================================================
//  Helper: Clear the Piece form fields
// ============================================================

void smartcarpentry::clearPieceForm()
{
    ui->pc_id->clear();
    ui->pc_nom->clear();
    ui->pc_code->clear();
    ui->pc_qty->setMinimum(1);
    ui->pc_qty->setValue(1);
    ui->pc_long->setValue(0.0);
    ui->pc_larg->setValue(0.0);
    ui->pc_epais->setValue(0.0);
    if (ui->pc_matiere->count() > 0) {
        ui->pc_matiere->setCurrentIndex(0);
    } else {
        ui->pc_idBois->setValue(0);
    }
    if (ui->pc_modele->count() > 0) {
        ui->pc_modele->setCurrentIndex(0);
    } else {
        ui->pc_idModele->setValue(0);
    }
    selectedPieceId = -1;
}

// ============================================================
//  CRUD - Add Piece
// ============================================================

void smartcarpentry::on_btn_pc_add_clicked()
{
    QString nomPiece = ui->pc_nom->text().trimmed();
    QString codePiece = ui->pc_code->text().trimmed();
    int quantite = ui->pc_qty->value();
    QString matiere = ui->pc_matiere->currentData(Qt::UserRole + 1).toString().trimmed();
    double longueur = ui->pc_long->value();
    double largeur = ui->pc_larg->value();
    double epaisseur = ui->pc_epais->value();
    int idModele = ui->pc_modele->currentData().toInt();
    int idBois = ui->pc_matiere->currentData().toInt();

    ui->pc_idModele->setValue(idModele);
    ui->pc_idBois->setValue(idBois);

    if (ui->pc_matiere->count() == 0) {
        QMessageBox::warning(this, "Erreur", "Aucun bois disponible dans la base.");
        return;
    }
    if (ui->pc_modele->count() == 0) {
        QMessageBox::warning(this, "Erreur", "Aucun modele disponible dans la base.");
        return;
    }

    if (!Piece::validerNomPiece(nomPiece)) {
        QMessageBox::warning(this, "Erreur", "Nom de piece invalide (1-100 caracteres).");
        return;
    }
    if (!Piece::validerCodePiece(codePiece)) {
        QMessageBox::warning(this, "Erreur", "Code de piece invalide (1-50 caracteres).");
        return;
    }
    if (!Piece::validerQuantite(quantite)) {
        QMessageBox::warning(this, "Erreur", "Quantite invalide (doit etre > 0).");
        return;
    }
    if (!Piece::validerMatiere(matiere)) {
        QMessageBox::warning(this, "Erreur", "Matiere invalide.");
        return;
    }
    if (!Piece::validerDimension(longueur) || !Piece::validerDimension(largeur) || !Piece::validerDimension(epaisseur)) {
        QMessageBox::warning(this, "Erreur", "Les dimensions doivent etre superieures a 0.");
        return;
    }
    if (!Piece::validerForeignKey(idModele) || !Piece::validerForeignKey(idBois)) {
        QMessageBox::warning(this, "Erreur", "ID Modele et ID Bois doivent etre superieurs a 0.");
        return;
    }

    Piece p;
    p.setNomPiece(nomPiece);
    p.setCodePiece(codePiece);
    p.setQuantite(quantite);
    p.setMatiere(matiere);
    p.setLongueurMm(longueur);
    p.setLargeurMm(largeur);
    p.setEpaisseurMm(epaisseur);
    p.setDateCreation(QDate::currentDate());
    p.setIdModele(idModele);
    p.setIdBois(idBois);

    if (p.ajouter()) {
        QMessageBox::information(this, "Succes", "Piece ajoutee avec succes !");
        insertEmployeeHistoryEntry(
            -1,
            "PIECE_CREATE",
            currentUserEmail,
            QString("Ajout piece: code='%1', nom='%2', modele=%3, bois=%4, qte=%5")
                .arg(codePiece)
                .arg(nomPiece)
                .arg(idModele)
                .arg(idBois)
                .arg(quantite));
        refreshPieceTable();
        clearPieceForm();
        ui->tabWidget_pc->setCurrentIndex(0);
    } else {
        QMessageBox::critical(this, "Erreur",
            "Echec de l'ajout.\n" + p.getLastError());
    }
}

