// ============================================================
//  Piece table row click -> populate form
// ============================================================

void smartcarpentry::on_tv_pc_clicked(const QModelIndex &index)
{
    if (!index.isValid()) return;

    QAbstractItemModel *model = ui->tv_pc->model();
    const int row = index.row();

    selectedPieceId = model->data(model->index(row, 0)).toInt();

    ui->pc_id->setText(model->data(model->index(row, 0)).toString());
    ui->pc_nom->setText(model->data(model->index(row, 1)).toString());
    ui->pc_code->setText(model->data(model->index(row, 2)).toString());
    ui->pc_qty->setValue(model->data(model->index(row, 3)).toInt());

    ui->pc_long->setValue(model->data(model->index(row, 5)).toDouble());
    ui->pc_larg->setValue(model->data(model->index(row, 6)).toDouble());
    ui->pc_epais->setValue(model->data(model->index(row, 7)).toDouble());

    const int idModele = model->data(model->index(row, 12)).toInt();
    const int idBois = model->data(model->index(row, 13)).toInt();

    int matiereIndex = ui->pc_matiere->findData(idBois);
    if (matiereIndex >= 0) {
        ui->pc_matiere->setCurrentIndex(matiereIndex);
    } else {
        ui->pc_idBois->setValue(idBois);
    }

    int modeleIndex = ui->pc_modele->findData(idModele);
    if (modeleIndex >= 0) {
        ui->pc_modele->setCurrentIndex(modeleIndex);
    } else {
        ui->pc_idModele->setValue(idModele);
    }
}

