// ============================================================
//  List-tab: Ajouter une piece via popup dialog
// ============================================================

void smartcarpentry::on_btn_pc_list_modify_clicked()
{
    openPieceCatalogDialog(-1);
}

bool smartcarpentry::openPieceCatalogDialog(int pieceId)
{
    loadPieceBoisOptions();
    loadPieceModeleOptions();

    if (ui->pc_matiere->count() == 0) {
        QMessageBox::warning(this, "Piece", "Aucun bois disponible dans la base.");
        return false;
    }
    if (ui->pc_modele->count() == 0) {
        QMessageBox::warning(this, "Piece", "Aucun modele disponible dans la base.");
        return false;
    }

    const bool editMode = pieceId > 0;
    Piece currentPiece;
    QString loadError;
    if (editMode && !PieceRepository::loadById(pieceId, currentPiece, &loadError)) {
        QMessageBox::warning(this, "Piece", loadError.isEmpty() ? "Impossible de charger la piece." : loadError);
        return false;
    }
    if (editMode && currentPiece.getStatus() == PieceStatus::Published) {
        const PieceWorkflowState workflowState = PieceWorkflowStateRepository::loadWorkflowState(currentPiece.getIdModele(),
                                                                                                 currentPiece.getIdBois(),
                                                                                                 nullptr);
        if (workflowState.stockConsumedAt.isValid()) {
            QMessageBox::warning(this, "Piece", pieceWorkflowLockMessage());
            return false;
        }
    }

    QDialog dialog(this);
    dialog.setWindowTitle(editMode ? "Modifier la piece" : "Ajouter une piece");
    dialog.setMinimumWidth(580);
    dialog.setStyleSheet(
        "QDialog { background-color: #0f172a; color: white; } "
        "QLabel { color: #94a3b8; font-weight: bold; } "
        "QLineEdit, QDoubleSpinBox, QSpinBox, QComboBox { "
        "background: rgba(30,41,59,0.7); border: 1px solid rgba(255,255,255,0.1); "
        "border-radius: 8px; padding: 8px; color: white; } "
        "QComboBox QAbstractItemView { background-color: #1e293b; color: white; selection-background-color: #4f46e5; } "
        "QPushButton { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #10b981, stop:1 #059669); "
        "color: white; font-weight: bold; border-radius: 10px; padding: 12px; }");

    auto cloneComboItems = [](QComboBox *source, QComboBox *target) {
        for (int i = 0; i < source->count(); ++i) {
            target->addItem(source->itemText(i), source->itemData(i));
            target->setItemData(i, source->itemData(i, Qt::UserRole + 1), Qt::UserRole + 1);
        }
    };

    QVBoxLayout *mainLayout = new QVBoxLayout(&dialog);
    QGridLayout *formLayout = new QGridLayout();

    QLineEdit *nomInput = new QLineEdit(editMode ? currentPiece.getNomPiece() : QString(), &dialog);
    nomInput->setMaxLength(100);
    QLineEdit *codeInput = new QLineEdit(editMode ? currentPiece.getCodePiece() : QString(), &dialog);
    codeInput->setMaxLength(50);

    QSpinBox *quantiteInput = new QSpinBox(&dialog);
    quantiteInput->setRange(1, 999999);
    quantiteInput->setValue(editMode ? currentPiece.getQuantite() : 1);

    QComboBox *boisInput = new QComboBox(&dialog);
    QComboBox *modeleInput = new QComboBox(&dialog);
    cloneComboItems(ui->pc_matiere, boisInput);
    cloneComboItems(ui->pc_modele, modeleInput);

    const int boisIndex = boisInput->findData(editMode ? currentPiece.getIdBois() : ui->pc_matiere->currentData().toInt());
    if (boisIndex >= 0) {
        boisInput->setCurrentIndex(boisIndex);
    }
    const int modeleIndex = modeleInput->findData(editMode ? currentPiece.getIdModele() : ui->pc_modele->currentData().toInt());
    if (modeleIndex >= 0) {
        modeleInput->setCurrentIndex(modeleIndex);
    }

    QDoubleSpinBox *longueurInput = new QDoubleSpinBox(&dialog);
    longueurInput->setRange(0.0, 99999.99);
    longueurInput->setDecimals(2);
    longueurInput->setSuffix(" mm");
    longueurInput->setValue(editMode ? currentPiece.getLongueurMm() : 0.0);

    QDoubleSpinBox *largeurInput = new QDoubleSpinBox(&dialog);
    largeurInput->setRange(0.0, 99999.99);
    largeurInput->setDecimals(2);
    largeurInput->setSuffix(" mm");
    largeurInput->setValue(editMode ? currentPiece.getLargeurMm() : 0.0);

    QDoubleSpinBox *epaisseurInput = new QDoubleSpinBox(&dialog);
    epaisseurInput->setRange(0.0, 99999.99);
    epaisseurInput->setDecimals(2);
    epaisseurInput->setSuffix(" mm");
    epaisseurInput->setValue(editMode ? currentPiece.getEpaisseurMm() : 0.0);

    QLabel *statusHint = new QLabel(editMode
                                        ? QString("Statut courant : %1").arg(currentPiece.getStatus() == PieceStatus::Draft ? "BROUILLON" : "PUBLIE")
                                        : QString("La piece sera ajoutee directement dans le catalogue publie."),
                                    &dialog);
    statusHint->setWordWrap(true);

    formLayout->addWidget(new QLabel("Nom :", &dialog), 0, 0);
    formLayout->addWidget(nomInput, 0, 1);
    formLayout->addWidget(new QLabel("Code :", &dialog), 1, 0);
    formLayout->addWidget(codeInput, 1, 1);
    formLayout->addWidget(new QLabel("Quantite :", &dialog), 2, 0);
    formLayout->addWidget(quantiteInput, 2, 1);
    formLayout->addWidget(new QLabel("Bois / Matiere :", &dialog), 3, 0);
    formLayout->addWidget(boisInput, 3, 1);
    formLayout->addWidget(new QLabel("Longueur :", &dialog), 4, 0);
    formLayout->addWidget(longueurInput, 4, 1);
    formLayout->addWidget(new QLabel("Largeur :", &dialog), 5, 0);
    formLayout->addWidget(largeurInput, 5, 1);
    formLayout->addWidget(new QLabel("Epaisseur :", &dialog), 6, 0);
    formLayout->addWidget(epaisseurInput, 6, 1);
    formLayout->addWidget(new QLabel("Modele :", &dialog), 7, 0);
    formLayout->addWidget(modeleInput, 7, 1);

    mainLayout->addLayout(formLayout);
    mainLayout->addWidget(statusHint);

    QPushButton *saveButton = new QPushButton(editMode ? "Enregistrer la piece" : "Ajouter la piece", &dialog);
    mainLayout->addWidget(saveButton);

    connect(saveButton, &QPushButton::clicked, &dialog, [&, this]() {
        const QString nomPiece = nomInput->text().trimmed();
        const QString codePiece = codeInput->text().trimmed();
        const int quantite = quantiteInput->value();
        const int idBois = boisInput->currentData().toInt();
        const int idModele = modeleInput->currentData().toInt();
        const QString matiere = boisInput->currentData(Qt::UserRole + 1).toString().trimmed();

        if (!Piece::validerNomPiece(nomPiece)) {
            QMessageBox::warning(&dialog, "Piece", "Nom de piece invalide.");
            return;
        }
        if (!Piece::validerCodePiece(codePiece)) {
            QMessageBox::warning(&dialog, "Piece", "Code de piece invalide.");
            return;
        }
        if (!Piece::validerQuantite(quantite)) {
            QMessageBox::warning(&dialog, "Piece", "Quantite invalide.");
            return;
        }
        if (!Piece::validerDimension(longueurInput->value())
            || !Piece::validerDimension(largeurInput->value())
            || !Piece::validerDimension(epaisseurInput->value())) {
            QMessageBox::warning(&dialog, "Piece", "Les dimensions doivent etre superieures a 0.");
            return;
        }
        if (!Piece::validerForeignKey(idModele) || !Piece::validerForeignKey(idBois) || !Piece::validerMatiere(matiere)) {
            QMessageBox::warning(&dialog, "Piece", "Le modele ou le bois selectionne est invalide.");
            return;
        }

        Piece piece = editMode ? currentPiece : Piece();
        piece.setIdPiece(pieceId);
        piece.setNomPiece(nomPiece);
        piece.setCodePiece(codePiece);
        piece.setQuantite(quantite);
        piece.setMatiere(matiere);
        piece.setLongueurMm(longueurInput->value());
        piece.setLargeurMm(largeurInput->value());
        piece.setEpaisseurMm(epaisseurInput->value());
        piece.setIdModele(idModele);
        piece.setIdBois(idBois);
        piece.setUpdatedAt(QDateTime::currentDateTime());
        if (!editMode) {
            piece.setDateCreation(QDate::currentDate());
            piece.setStatus(PieceStatus::Published);
            piece.setSourceGeneration("FORMULAIRE");
        }

        QString errorMessage;
        const bool ok = editMode
            ? PieceRepository::updatePiece(piece, errorMessage)
            : PieceRepository::addPublishedPiece(piece, errorMessage);
        if (!ok) {
            QMessageBox::warning(&dialog, "Piece", errorMessage);
            return;
        }
        dialog.accept();
    });

    if (dialog.exec() != QDialog::Accepted) {
        return false;
    }

    refreshPieceTable();
    const int savedModeleId = modeleInput->currentData().toInt();
    const int savedBoisId = boisInput->currentData().toInt();
    const bool currentContextWasTouched =
        (savedModeleId == pieceContextModeleId && savedBoisId == pieceContextBoisId)
        || (editMode
            && currentPiece.getIdModele() == pieceContextModeleId
            && currentPiece.getIdBois() == pieceContextBoisId);
    if (currentContextWasTouched) {
        restorePieceWorkflowState(PieceWorkflowStateRepository::loadWorkflowState(pieceContextModeleId,
                                                                                  pieceContextBoisId,
                                                                                  nullptr));
    }
    refreshPieceGenerationContext();
    if (ui->tv_pc) {
        ui->tv_pc->clearSelection();
        ui->tv_pc->setCurrentIndex(QModelIndex());
    }
    return true;
}

// ============================================================
//  List-tab: Supprimer -> delete selected row
// ============================================================

void smartcarpentry::on_btn_pc_list_delete_clicked()
{
    QModelIndex index = ui->tv_pc->currentIndex();
    if (!index.isValid()) {
        QMessageBox::warning(this, "Erreur", "Veuillez selectionner une piece a supprimer.");
        return;
    }

    QAbstractItemModel *model = ui->tv_pc->model();
    const int row = index.row();
    const int id = model->data(model->index(row, 0)).toInt();
    const QString deletedStatus = model->data(model->index(row, 8)).toString().trimmed().toUpper();
    const int deletedModeleId = model->data(model->index(row, 12)).toInt();
    const int deletedBoisId = model->data(model->index(row, 13)).toInt();

    if (id <= 0) {
        QMessageBox::warning(this, "Erreur", "ID piece invalide.");
        return;
    }

    QMessageBox::StandardButton reply = QMessageBox::question(
        this, "Confirmation",
        QString("Voulez-vous vraiment supprimer la piece #%1 ?").arg(id),
        QMessageBox::Yes | QMessageBox::No
    );
    if (reply != QMessageBox::Yes) return;

    QString deleteError;
    if (PieceRepository::deletePiece(id, deleteError)) {
        const bool hasDraftsForContext = deletedModeleId > 0 && deletedBoisId > 0
            ? PieceRepository::hasDraftPieces(deletedModeleId, deletedBoisId, nullptr)
            : false;
        const int publishedCountForContext = deletedModeleId > 0 && deletedBoisId > 0
            ? PieceRepository::countPublishedPieces(deletedModeleId, deletedBoisId, nullptr)
            : 0;

        if ((deletedStatus == "BROUILLON" || deletedStatus == "PUBLIE")
            && !hasDraftsForContext
            && publishedCountForContext <= 0) {
            QString workflowError;
            PieceWorkflowStateRepository::clearWorkflowState(deletedModeleId, deletedBoisId, workflowError);
        }

        QMessageBox::information(this, "Succes", "Piece supprimee avec succes !");
        refreshPieceTable();
        if (deletedModeleId == pieceContextModeleId && deletedBoisId == pieceContextBoisId) {
            restorePieceWorkflowState(
                PieceWorkflowStateRepository::loadWorkflowState(pieceContextModeleId, pieceContextBoisId, nullptr));
        }
        refreshPieceGenerationContext();
        clearPieceForm();
    } else {
        QMessageBox::critical(this, "Erreur",
            "Echec de la suppression.\n" + deleteError);
    }
}

// ============================================================
//  Matiere filter
// ============================================================

void smartcarpentry::on_combo_filter_matiere_currentTextChanged(const QString &matiere)
{
    Q_UNUSED(matiere);
    applyPieceCompositeFilter();
}

void smartcarpentry::applyPieceCompositeFilter()
{
    if (!pieceFilterProxy) {
        return;
    }

    pieceFilterProxy->setSearchText(ui->search_pc ? ui->search_pc->text() : QString());
    pieceFilterProxy->setMaterialFilter(ui->combo_filter_matiere ? ui->combo_filter_matiere->currentText() : QString());
    pieceFilterProxy->setStatusFilter(pieceStatusFilterCombo ? pieceStatusFilterCombo->currentText() : QString());
}

// ============================================================
//  Piece list sort
// ============================================================

void smartcarpentry::applyPieceListSort()
{
    if (!ui->tv_pc || !ui->tv_pc->model()) return;

    int column = 0;
    const QString sortBy = ui->pc_sort_by->currentText();

    if (sortBy == "Nom") {
        column = 1;
    } else if (sortBy == "Code") {
        column = 2;
    } else if (sortBy == "Quantite") {
        column = 3;
    } else if (sortBy == "Matiere") {
        column = 4;
    } else if (sortBy == "Longueur") {
        column = 5;
    } else if (sortBy == "Largeur") {
        column = 6;
    } else if (sortBy == "Epaisseur") {
        column = 7;
    }

    const Qt::SortOrder order =
        (ui->pc_sort_order->currentText() == "Croissant")
            ? Qt::AscendingOrder
            : Qt::DescendingOrder;

    ui->tv_pc->sortByColumn(column, order);
}

void smartcarpentry::on_pc_sort_by_currentTextChanged(const QString &)
{
    applyPieceListSort();
}

void smartcarpentry::on_pc_sort_order_currentTextChanged(const QString &)
{
    applyPieceListSort();
}

