// ============================================================
//  Piece form sync: selected Bois -> ID Bois
// ============================================================

void smartcarpentry::on_pc_matiere_currentIndexChanged(int index)
{
    if (index < 0) {
        ui->pc_idBois->setValue(0);
        return;
    }

    ui->pc_idBois->setValue(ui->pc_matiere->itemData(index).toInt());
}

// ============================================================
//  Piece form sync: selected Modele -> ID Modele
// ============================================================

void smartcarpentry::on_pc_modele_currentIndexChanged(int index)
{
    if (index < 0) {
        ui->pc_idModele->setValue(0);
        return;
    }

    ui->pc_idModele->setValue(ui->pc_modele->itemData(index).toInt());
}

void smartcarpentry::updatePieceModelImagePreview(const QString &imagePath)
{
    pieceModelImagePath = imagePath.trimmed();

    if (!ui->lb_pc_model_dropzone) {
        return;
    }

    ui->lb_pc_model_dropzone->setToolTip(pieceModelImagePath);
    ui->lb_pc_model_dropzone->setPixmap(QPixmap());

    if (pieceModelImagePath.isEmpty() || !QFileInfo::exists(pieceModelImagePath)) {
        ui->lb_pc_model_dropzone->setStyleSheet(
            "border:2px dashed rgba(129,140,248,0.38);"
            "border-radius:18px;"
            "background:qlineargradient(x1:0,y1:0,x2:1,y2:1,stop:0 rgba(99,102,241,0.10),stop:1 rgba(30,41,59,0.30));"
            "padding:24px;"
            "color:rgba(255,255,255,0.82);");
        ui->lb_pc_model_dropzone->setText(
            "<div style=\"font-family:'Segoe UI'; text-align:center;\">"
            "<div style=\"font-size:19px; font-weight:800; color:#eef2ff;\">Zone de capture modele</div>"
            "<div style=\"margin-top:10px; font-size:14px; color:#c7d2fe;\">Deposer ou glisser l'image du modele ici</div>"
            "<div style=\"margin-top:8px; font-size:12px; color:#cbd5e1;\">PNG / JPG / rendu 3D / plan de facade</div>"
            "</div>");
        updatePieceWorkflowState();
        return;
    }

    QPixmap pixmap(pieceModelImagePath);
    if (pixmap.isNull()) {
        ui->lb_pc_model_dropzone->setStyleSheet(
            "border:2px dashed rgba(248,113,113,0.34);"
            "border-radius:18px;"
            "background:rgba(127,29,29,0.18);"
            "padding:24px;"
            "color:#fecaca;");
        ui->lb_pc_model_dropzone->setText(
            "<div style=\"font-family:'Segoe UI'; text-align:center;\">"
            "<div style=\"font-size:18px; font-weight:800;\">Image invalide</div>"
            "<div style=\"margin-top:8px; font-size:12px;\">Le fichier selectionne ne peut pas etre charge.</div>"
            "</div>");
        updatePieceWorkflowState();
        return;
    }

    ui->lb_pc_model_dropzone->setStyleSheet(
        "border:1px solid rgba(129,140,248,0.34);"
        "border-radius:18px;"
        "background:qlineargradient(x1:0,y1:0,x2:1,y2:1,stop:0 rgba(15,23,42,0.92),stop:1 rgba(30,41,59,0.56));"
        "padding:12px;");
    ui->lb_pc_model_dropzone->setText(QString());
    ui->lb_pc_model_dropzone->setPixmap(
        pixmap.scaled(ui->lb_pc_model_dropzone->size(),
                      Qt::KeepAspectRatio,
                      Qt::SmoothTransformation));
    ui->lb_pc_model_dropzone->setToolTip(
        QString("%1\n%2 x %3 px")
            .arg(QFileInfo(pieceModelImagePath).fileName())
            .arg(pixmap.width())
            .arg(pixmap.height()));
    updatePieceWorkflowState();
}

