// ============================================================
//  Helper: Create chart views for employee statistics
// ============================================================

void smartcarpentry::setupEmployeeCharts()
{
    if (ui->hl_emp_stats_body) {
        ui->hl_emp_stats_body->setStretch(0, 2);
        ui->hl_emp_stats_body->setStretch(1, 1);
    }

    if (ui->emp_stats_role_chart_container && !empRoleChartView) {
        QVBoxLayout *layout = new QVBoxLayout(ui->emp_stats_role_chart_container);
        layout->setContentsMargins(0, 0, 0, 0);
        layout->setSpacing(0);

        empRoleChartView = new QChartView(ui->emp_stats_role_chart_container);
        empRoleChartView->setRenderHint(QPainter::Antialiasing);
        empRoleChartView->setStyleSheet("background:transparent;");
        empRoleChartView->setMinimumHeight(320);
        layout->addWidget(empRoleChartView);
    }

    if (ui->emp_stats_fab_chart_container && !empFabChartView) {
        QVBoxLayout *layout = new QVBoxLayout(ui->emp_stats_fab_chart_container);
        layout->setContentsMargins(0, 0, 0, 0);
        layout->setSpacing(0);

        empFabChartView = new QChartView(ui->emp_stats_fab_chart_container);
        empFabChartView->setRenderHint(QPainter::Antialiasing);
        empFabChartView->setStyleSheet("background:transparent;");
        empFabChartView->setMinimumHeight(260);
        layout->addWidget(empFabChartView);
    }

    if (ui->vl_emp_stats_pipeline && !empSkillStatusChartView) {
        QLabel *skillTitle = new QLabel("Distribution des statuts de competences", ui->gb_emp_stats_pipeline);
        skillTitle->setStyleSheet("color:#a5b4fc;background:transparent;font-size:13px;font-weight:600;");

        QWidget *skillChartContainer = new QWidget(ui->gb_emp_stats_pipeline);
        skillChartContainer->setObjectName("emp_stats_skill_chart_container");
        skillChartContainer->setMinimumHeight(180);
        skillChartContainer->setStyleSheet("background:transparent;");

        QVBoxLayout *skillChartLayout = new QVBoxLayout(skillChartContainer);
        skillChartLayout->setContentsMargins(0, 0, 0, 0);
        skillChartLayout->setSpacing(0);

        empSkillStatusChartView = new QChartView(skillChartContainer);
        empSkillStatusChartView->setRenderHint(QPainter::Antialiasing);
        empSkillStatusChartView->setStyleSheet("background:transparent;");
        empSkillStatusChartView->setMinimumHeight(180);
        skillChartLayout->addWidget(empSkillStatusChartView);

        const int insertIndex = ui->vl_emp_stats_pipeline->indexOf(ui->txt_emp_stats_pipeline);
        if (insertIndex >= 0) {
            ui->vl_emp_stats_pipeline->insertWidget(insertIndex, skillChartContainer);
            ui->vl_emp_stats_pipeline->insertWidget(insertIndex, skillTitle);
        } else {
            ui->vl_emp_stats_pipeline->addWidget(skillTitle);
            ui->vl_emp_stats_pipeline->addWidget(skillChartContainer);
        }
    }

    if (ui->emp_knn_chart_container && !empKnnChartView) {
        QVBoxLayout *layout = new QVBoxLayout(ui->emp_knn_chart_container);
        layout->setContentsMargins(0, 0, 0, 0);
        layout->setSpacing(0);

        empKnnChartView = new QChartView(ui->emp_knn_chart_container);
        empKnnChartView->setRenderHint(QPainter::Antialiasing);
        empKnnChartView->setStyleSheet("background:transparent;");
        layout->addWidget(empKnnChartView);
    }
}

void smartcarpentry::renderEmployeeKnnChart(const QVector<EmployeeKnnRecommendation> &recommendations,
                                            double taskX,
                                            double taskY,
                                            int k)
{
    if (!empKnnChartView) {
        return;
    }

    QScatterSeries *neighborsSeries = new QScatterSeries();
    neighborsSeries->setName("Top voisins");
    neighborsSeries->setMarkerShape(QScatterSeries::MarkerShapeCircle);
    neighborsSeries->setMarkerSize(12.0);
    neighborsSeries->setColor(QColor("#dc2626"));

    QScatterSeries *othersSeries = new QScatterSeries();
    othersSeries->setName("Autres");
    othersSeries->setMarkerShape(QScatterSeries::MarkerShapeCircle);
    othersSeries->setMarkerSize(10.0);
    othersSeries->setColor(QColor("#2563eb"));

    QScatterSeries *taskSeries = new QScatterSeries();
    taskSeries->setName("Teche cible");
    taskSeries->setMarkerShape(QScatterSeries::MarkerShapeRectangle);
    taskSeries->setMarkerSize(16.0);
    taskSeries->setColor(QColor("#6b7280"));
    taskSeries->append(taskX, taskY);

    QList<QLineSeries*> linkLines;
    const int neighborCount = qMin(k, recommendations.size());

    double minX = taskX;
    double maxX = taskX;
    double minY = taskY;
    double maxY = taskY;

    for (int i = 0; i < recommendations.size(); ++i) {
        const auto &rec = recommendations.at(i);
        const double x = rec.employee.classificationX;
        const double y = rec.employee.classificationY;

        minX = qMin(minX, x);
        maxX = qMax(maxX, x);
        minY = qMin(minY, y);
        maxY = qMax(maxY, y);

        if (i < neighborCount) {
            neighborsSeries->append(x, y);

            QLineSeries *line = new QLineSeries();
            line->setName(QString("Distance #%1").arg(i + 1));
            line->append(taskX, taskY);
            line->append(x, y);
            QPen pen(QColor("#16a34a"));
            pen.setWidth(2);
            line->setPen(pen);
            linkLines.append(line);
        } else {
            othersSeries->append(x, y);
        }
    }

    const double padX = qMax(0.03, (maxX - minX) * 0.15);
    const double padY = qMax(0.03, (maxY - minY) * 0.15);

    QValueAxis *axisX = new QValueAxis();
    axisX->setTitleText("Axe competence (classification_x)");
    axisX->setLabelFormat("%.2f");
    axisX->setTickCount(6);
    axisX->setGridLineColor(QColor("#334155"));
    axisX->setLinePenColor(QColor("#64748b"));
    axisX->setLabelsColor(QColor("#cbd5e1"));
    axisX->setTitleBrush(QBrush(QColor("#e2e8f0")));
    axisX->setRange(qMax(0.0, minX - padX), qMin(1.0, maxX + padX));

    QValueAxis *axisY = new QValueAxis();
    axisY->setTitleText("Axe execution (classification_y)");
    axisY->setLabelFormat("%.2f");
    axisY->setTickCount(6);
    axisY->setGridLineColor(QColor("#334155"));
    axisY->setLinePenColor(QColor("#64748b"));
    axisY->setLabelsColor(QColor("#cbd5e1"));
    axisY->setTitleBrush(QBrush(QColor("#e2e8f0")));
    axisY->setRange(qMax(0.0, minY - padY), qMin(1.0, maxY + padY));

    QChart *chart = new QChart();
    chart->setTitle("Projection KNN 2D - Recommandation par competences");
    chart->setBackgroundVisible(true);
    chart->setBackgroundBrush(QBrush(QColor("#0f172a")));
    chart->setPlotAreaBackgroundVisible(true);
    chart->setPlotAreaBackgroundBrush(QBrush(QColor("#111827")));
    chart->setAnimationOptions(QChart::SeriesAnimations);
    chart->setAnimationDuration(300);
    chart->legend()->setAlignment(Qt::AlignTop);
    chart->legend()->setLabelColor(QColor("#e2e8f0"));

    QBrush titleBrush(QColor("#e2e8f0"));
    chart->setTitleBrush(titleBrush);

    chart->addSeries(taskSeries);
    chart->addSeries(neighborsSeries);
    if (!othersSeries->points().isEmpty()) {
        chart->addSeries(othersSeries);
    } else {
        delete othersSeries;
        othersSeries = nullptr;
    }

    for (QLineSeries *line : linkLines) {
        chart->addSeries(line);
    }

    chart->addAxis(axisX, Qt::AlignBottom);
    chart->addAxis(axisY, Qt::AlignLeft);

    taskSeries->attachAxis(axisX);
    taskSeries->attachAxis(axisY);
    neighborsSeries->attachAxis(axisX);
    neighborsSeries->attachAxis(axisY);
    if (othersSeries) {
        othersSeries->attachAxis(axisX);
        othersSeries->attachAxis(axisY);
    }
    for (QLineSeries *line : linkLines) {
        line->attachAxis(axisX);
        line->attachAxis(axisY);
    }

    QChart *oldChart = empKnnChartView->chart();
    empKnnChartView->setChart(chart);
    delete oldChart;
}

// ============================================================
//  Helper: Refresh statistics widgets on employee page
// ============================================================

void smartcarpentry::refreshEmployeeStats()
{
    // ---- Basic KPIs ----
    int totalEmp    = 0;
    int affected    = 0;
    int unaffected  = 0;
    int knnReadyEmployees = 0;

    int totalSkills = 0;
    int certifiedActive = 0;
    int certifiedExpired = 0;
    int inTraining = 0;
    int nonQualified = 0;
    int employeesWithActiveCertification = 0;

    QSqlQuery kpiQuery;
    if (kpiQuery.exec(
            "SELECT COUNT(*), "
            "SUM(CASE WHEN IDFABRICATION IS NOT NULL THEN 1 ELSE 0 END), "
            "SUM(CASE WHEN IDFABRICATION IS NULL THEN 1 ELSE 0 END) "
            "FROM EMPLOYEE") && kpiQuery.next()) {
        totalEmp   = kpiQuery.value(0).toInt();
        affected   = kpiQuery.value(1).toInt();
        unaffected = kpiQuery.value(2).toInt();
    }

    QSqlQuery knnReadyQuery;
    if (knnReadyQuery.exec(
            "SELECT COUNT(*) "
            "FROM EMPLOYEE "
            "WHERE CLASSIFICATION_X IS NOT NULL AND CLASSIFICATION_Y IS NOT NULL")
        && knnReadyQuery.next()) {
        knnReadyEmployees = knnReadyQuery.value(0).toInt();
    }

    QSqlQuery skillKpiQuery;
    if (skillKpiQuery.exec(
            "SELECT "
            "COUNT(*) AS TOTAL_SKILLS, "
            "SUM(CASE WHEN NIVEAU_MAITRISE = 'CERTIFIE' "
            "          AND (DATE_EXPIRATION IS NULL OR DATE_EXPIRATION >= TRUNC(SYSDATE)) "
            "     THEN 1 ELSE 0 END) AS CERTIFIE_ACTIF, "
            "SUM(CASE WHEN NIVEAU_MAITRISE = 'CERTIFIE' "
            "          AND DATE_EXPIRATION IS NOT NULL AND DATE_EXPIRATION < TRUNC(SYSDATE) "
            "     THEN 1 ELSE 0 END) AS CERTIFIE_EXPIRE, "
            "SUM(CASE WHEN NIVEAU_MAITRISE = 'EN_FORMATION' THEN 1 ELSE 0 END) AS EN_FORMATION, "
            "SUM(CASE WHEN NIVEAU_MAITRISE = 'NON_QUALIFIE' THEN 1 ELSE 0 END) AS NON_QUALIFIE "
            "FROM EMPLOYEE_SKILL") && skillKpiQuery.next()) {
        totalSkills = skillKpiQuery.value(0).toInt();
        certifiedActive = skillKpiQuery.value(1).toInt();
        certifiedExpired = skillKpiQuery.value(2).toInt();
        inTraining = skillKpiQuery.value(3).toInt();
        nonQualified = skillKpiQuery.value(4).toInt();
    }

    QSqlQuery certifiedCoverageQuery;
    if (certifiedCoverageQuery.exec(
            "SELECT COUNT(DISTINCT IDEMPLOYEE) "
            "FROM EMPLOYEE_SKILL "
            "WHERE NIVEAU_MAITRISE = 'CERTIFIE' "
            "  AND (DATE_EXPIRATION IS NULL OR DATE_EXPIRATION >= TRUNC(SYSDATE))")
        && certifiedCoverageQuery.next()) {
        employeesWithActiveCertification = certifiedCoverageQuery.value(0).toInt();
    }

    const double affectedPct = (totalEmp > 0)
        ? (static_cast<double>(affected) / totalEmp) * 100.0
        : 0.0;
    const double certifiedCoveragePct = (totalEmp > 0)
        ? (100.0 * static_cast<double>(employeesWithActiveCertification) / static_cast<double>(totalEmp))
        : 0.0;
    const double knnReadinessPct = (totalEmp > 0)
        ? (100.0 * static_cast<double>(knnReadyEmployees) / static_cast<double>(totalEmp))
        : 0.0;
    const double avgSkillsPerEmployee = (totalEmp > 0)
        ? (static_cast<double>(totalSkills) / static_cast<double>(totalEmp))
        : 0.0;

    ui->lb_emp_stats_total_title->setText("Effectif + couverture skills");
    ui->lb_emp_stats_total_value->setText(QString::number(totalEmp));
    ui->lb_emp_stats_total_hint->setText(
        QString("%1 affecte(s) | %2 non affecte(s) | certifies actifs: %3")
            .arg(affected)
            .arg(unaffected)
            .arg(certifiedActive));
    ui->lb_emp_stats_affect_title->setText("Couverture operationnelle");
    ui->lb_emp_stats_affected_value->setText(
        QString("%1% (affectation)").arg(QString::number(affectedPct, 'f', 1)));
    ui->pb_emp_stats_affected->setFormat(
        QString("Affectes %1% | Certifies %2%")
            .arg(QString::number(affectedPct, 'f', 1))
            .arg(QString::number(certifiedCoveragePct, 'f', 1)));
    ui->pb_emp_stats_affected->setValue(qRound(affectedPct));

    // ---- Role distribution ----
    struct RoleStat {
        QString role;
        int count = 0;
    };

    QList<RoleStat> roleStats;
    QSqlQuery roleQuery;
    if (roleQuery.exec(
            "SELECT NVL(ROLE,'Non defini') AS R, COUNT(*) AS CNT "
            "FROM EMPLOYEE "
            "GROUP BY NVL(ROLE,'Non defini') "
            "ORDER BY CNT DESC, R")) {
        while (roleQuery.next()) {
            RoleStat rs;
            rs.role  = roleQuery.value(0).toString();
            rs.count = roleQuery.value(1).toInt();
            roleStats.append(rs);
        }
    }

    // Top role card
    if (!roleStats.isEmpty()) {
        ui->lb_emp_stats_toprole_value->setText(roleStats.first().role);
        ui->lb_emp_stats_toprole_hint->setText(
            QString("%1 employe(s) | KNN ready: %2%")
                .arg(roleStats.first().count)
                .arg(QString::number(knnReadinessPct, 'f', 1)));
    } else {
        ui->lb_emp_stats_toprole_value->setText("-");
        ui->lb_emp_stats_toprole_hint->setText("0 employe(s)");
    }

    // Top-3 role bars
    QLabel     *roleLabels[3] = { ui->lb_emp_stats_role_1, ui->lb_emp_stats_role_2, ui->lb_emp_stats_role_3 };
    QProgressBar *roleBars[3] = { ui->pb_emp_stats_role_1, ui->pb_emp_stats_role_2, ui->pb_emp_stats_role_3 };
    const int topCount = qMin(roleStats.size(), 3);

    for (int i = 0; i < 3; ++i) {
        if (i < topCount) {
            const RoleStat &rs = roleStats.at(i);
            const double share = (totalEmp > 0)
                ? (static_cast<double>(rs.count) / totalEmp) * 100.0
                : 0.0;
            roleLabels[i]->setText(QString("%1  |  %2 employe(s)").arg(rs.role).arg(rs.count));
            roleBars[i]->setValue(qRound(share));
        } else {
            roleLabels[i]->setText("Aucune donnee");
            roleBars[i]->setValue(0);
        }
    }

    // ---- Pipeline summary text ----
    QString topFab  = "Aucune";
    int     topFabN = 0;
    QSqlQuery fabQuery;
    if (fabQuery.exec(
            "SELECT IDFABRICATION, CNT FROM ("
            "  SELECT IDFABRICATION, COUNT(*) AS CNT "
            "  FROM EMPLOYEE "
            "  WHERE IDFABRICATION IS NOT NULL "
            "  GROUP BY IDFABRICATION "
            "  ORDER BY CNT DESC"
            ") WHERE ROWNUM = 1") && fabQuery.next()) {
        topFab  = QString("Fab #%1").arg(fabQuery.value(0).toInt());
        topFabN = fabQuery.value(1).toInt();
    }

    const QString topRoleName = roleStats.isEmpty() ? "Aucun" : roleStats.first().role;
    const QString summary =
        QString("Effectif total         : %1\n"
                "Employes affectes      : %2  (%3%)\n"
                "Employes non affectes  : %4\n"
                "Rele dominant          : %5\n"
                "Fabrication principale : %6 (%7 personne(s))\n"
                "Nombre de reles actifs : %8\n"
                "\n"
                "Skills (global)        : %9\n"
                "- Certifiees actives   : %10\n"
                "- Certifiees expirees  : %11\n"
                "- En formation         : %12\n"
                "- Non qualifiees       : %13\n"
                "Couverture certifiee   : %14% (%15/%1 employes)\n"
                "KNN profils prets      : %16% (%17/%1 employes)\n"
                "Moyenne skills/employe : %18")
            .arg(totalEmp)
            .arg(affected).arg(QString::number(affectedPct, 'f', 1))
            .arg(unaffected)
            .arg(topRoleName)
            .arg(topFab).arg(topFabN)
            .arg(roleStats.size())
            .arg(totalSkills)
            .arg(certifiedActive)
            .arg(certifiedExpired)
            .arg(inTraining)
            .arg(nonQualified)
            .arg(QString::number(certifiedCoveragePct, 'f', 1))
            .arg(employeesWithActiveCertification)
            .arg(QString::number(knnReadinessPct, 'f', 1))
            .arg(knnReadyEmployees)
            .arg(QString::number(avgSkillsPerEmployee, 'f', 2));

    ui->txt_emp_stats_pipeline->setPlainText(summary);

    // ---- Pie chart: role distribution ----
    if (empRoleChartView) {
        QPieSeries *pieSeries = new QPieSeries();
        pieSeries->setHoleSize(0.18);

        const int maxSlices  = qMin(roleStats.size(), 5);
        int       otherCount = 0;
        for (int i = 0; i < roleStats.size(); ++i) {
            if (i < maxSlices) {
                pieSeries->append(roleStats.at(i).role, roleStats.at(i).count);
            } else {
                otherCount += roleStats.at(i).count;
            }
        }
        if (otherCount > 0) {
            pieSeries->append("Autres", otherCount);
        }
        for (auto *slice : pieSeries->slices()) {
            slice->setLabelVisible(true);
        }

        QChart *roleChart = new QChart();
        roleChart->addSeries(pieSeries);
        roleChart->setTitle("Repartition des reles");
        roleChart->setTheme(QChart::ChartThemeDark);
        roleChart->setBackgroundVisible(false);
        roleChart->setPlotAreaBackgroundVisible(true);
        roleChart->setPlotAreaBackgroundBrush(QBrush(QColor("#0b1220")));
        roleChart->setAnimationOptions(QChart::SeriesAnimations);
        roleChart->setAnimationDuration(250);
        roleChart->setTitleBrush(QBrush(QColor("#e2e8f0")));
        roleChart->legend()->setAlignment(Qt::AlignBottom);
        roleChart->legend()->setLabelColor(QColor("#cbd5e1"));

        QChart *oldRoleChart = empRoleChartView->chart();
        empRoleChartView->setChart(roleChart);
        delete oldRoleChart;
    }

    // ---- Bar chart: employees per fabrication ----
    if (empFabChartView) {
        QBarSeries  *barSeries = new QBarSeries();
        QBarSet     *assignedSet = new QBarSet("Affectes");
        QBarSet     *certifiedSet = new QBarSet("Certifies actifs");
        assignedSet->setColor(QColor("#3b82f6"));
        certifiedSet->setColor(QColor("#14b8a6"));
        QStringList  categories;

        QSqlQuery fabDistQuery;
        if (fabDistQuery.exec(
                "SELECT E.IDFABRICATION, "
                "       COUNT(E.IDEMPLOYEE) AS EMP_CNT, "
                "       COUNT(DISTINCT CASE "
                "           WHEN S.NIVEAU_MAITRISE = 'CERTIFIE' "
                "            AND (S.DATE_EXPIRATION IS NULL OR S.DATE_EXPIRATION >= TRUNC(SYSDATE)) "
                "           THEN E.IDEMPLOYEE END) AS CERT_CNT "
                "FROM EMPLOYEE E "
                "LEFT JOIN EMPLOYEE_SKILL S ON S.IDEMPLOYEE = E.IDEMPLOYEE "
                "WHERE E.IDFABRICATION IS NOT NULL "
                "GROUP BY E.IDFABRICATION "
                "ORDER BY IDFABRICATION")) {
            while (fabDistQuery.next()) {
                categories << QString("Fab #%1").arg(fabDistQuery.value(0).toInt());
                *assignedSet << fabDistQuery.value(1).toInt();
                *certifiedSet << fabDistQuery.value(2).toInt();
            }
        }

        if (categories.isEmpty()) {
            categories << "Aucune";
            *assignedSet << 0;
            *certifiedSet << 0;
        }

        barSeries->append(assignedSet);
        barSeries->append(certifiedSet);

        QBarCategoryAxis *axisX = new QBarCategoryAxis();
        axisX->append(categories);

        QValueAxis *axisY = new QValueAxis();
        axisY->setLabelFormat("%d");
        axisY->setMin(0.0);
        int maxVal = 0;
        for (int i = 0; i < assignedSet->count(); ++i) {
            maxVal = qMax(maxVal, static_cast<int>(assignedSet->at(i)));
        }
        for (int i = 0; i < certifiedSet->count(); ++i) {
            maxVal = qMax(maxVal, static_cast<int>(certifiedSet->at(i)));
        }
        axisY->setMax(qMax(1.0, static_cast<double>(maxVal) * 1.2));

        QChart *fabChart = new QChart();
        fabChart->addSeries(barSeries);
        fabChart->setTitle("Fabrication: effectif affecte vs competences certifiees");
        fabChart->setTheme(QChart::ChartThemeDark);
        fabChart->setBackgroundVisible(false);
        fabChart->setPlotAreaBackgroundVisible(true);
        fabChart->setPlotAreaBackgroundBrush(QBrush(QColor("#0b1220")));
        fabChart->setAnimationOptions(QChart::SeriesAnimations);
        fabChart->setAnimationDuration(250);
        fabChart->setTitleBrush(QBrush(QColor("#e2e8f0")));
        fabChart->legend()->setAlignment(Qt::AlignBottom);
        fabChart->legend()->setLabelColor(QColor("#cbd5e1"));
        fabChart->addAxis(axisX, Qt::AlignBottom);
        fabChart->addAxis(axisY, Qt::AlignLeft);
        barSeries->attachAxis(axisX);
        barSeries->attachAxis(axisY);

        QChart *oldFabChart = empFabChartView->chart();
        empFabChartView->setChart(fabChart);
        delete oldFabChart;
    }

    // ---- Donut chart: skill status executive view ----
    if (empSkillStatusChartView) {
        QPieSeries *skillSeries = new QPieSeries();
        skillSeries->setHoleSize(0.58);

        const int certifiedBucket = qMax(0, certifiedActive);
        const int trainingBucket = qMax(0, inTraining);
        const int nonQualifiedBucket = qMax(0, nonQualified);

        if (certifiedBucket + trainingBucket + nonQualifiedBucket == 0) {
            QPieSlice *noDataSlice = skillSeries->append("Aucune donnee", 1.0);
            noDataSlice->setColor(QColor("#334155"));
            noDataSlice->setLabelVisible(true);
            noDataSlice->setProperty("skillStatus", QString());
        } else {
            QPieSlice *certSlice = skillSeries->append("Certifie", certifiedBucket);
            QPieSlice *trainingSlice = skillSeries->append("En formation", trainingBucket);
            QPieSlice *nonQualifiedSlice = skillSeries->append("Non qualifie", nonQualifiedBucket);

            certSlice->setProperty("skillStatus", "CERTIFIE");
            trainingSlice->setProperty("skillStatus", "EN_FORMATION");
            nonQualifiedSlice->setProperty("skillStatus", "NON_QUALIFIE");

            certSlice->setColor(QColor("#14b8a6"));
            trainingSlice->setColor(QColor("#f59e0b"));
            nonQualifiedSlice->setColor(QColor("#ef4444"));

            for (QPieSlice *slice : skillSeries->slices()) {
                slice->setLabelVisible(true);
                slice->setLabelColor(QColor("#e2e8f0"));
                slice->setLabel(QString("%1 (%2)").arg(slice->label()).arg(qRound(slice->value())));
                connect(slice, &QPieSlice::clicked, this, [this, slice]() {
                    const QString status = slice->property("skillStatus").toString();
                    if (status.isEmpty()) {
                        return;
                    }
                    setEmployeeSkillStatusFilter(status);
                    if (ui->tabWidget_emp && ui->tab_emp_list) {
                        ui->tabWidget_emp->setCurrentWidget(ui->tab_emp_list);
                    }
                });
            }
        }

        QChart *skillChart = new QChart();
        skillChart->addSeries(skillSeries);
        skillChart->setTitle("Skills: certifie vs formation vs non qualifie");
        skillChart->setTheme(QChart::ChartThemeDark);
        skillChart->setBackgroundVisible(false);
        skillChart->setPlotAreaBackgroundVisible(true);
        skillChart->setPlotAreaBackgroundBrush(QBrush(QColor("#0b1220")));
        skillChart->setAnimationOptions(QChart::SeriesAnimations);
        skillChart->setAnimationDuration(250);
        skillChart->setTitleBrush(QBrush(QColor("#e2e8f0")));
        skillChart->legend()->setAlignment(Qt::AlignBottom);
        skillChart->legend()->setLabelColor(QColor("#cbd5e1"));

        QChart *oldSkillChart = empSkillStatusChartView->chart();
        empSkillStatusChartView->setChart(skillChart);
        delete oldSkillChart;
    }
}

// ============================================================
//  Employee stats: Refresh button
// ============================================================

void smartcarpentry::on_btn_emp_stats_refresh_clicked()
{
    refreshEmployeeStats();
}

// ============================================================
//  Employee KNN: Calculate best employees for a target task
// ============================================================

void smartcarpentry::on_btn_emp_knn_run_clicked()
{
    double taskX = 0.0;
    double taskY = 0.0;
    const int k = settingsKnnKSpin
                      ? settingsKnnKSpin->value()
                      : (ui->emp_knn_k ? ui->emp_knn_k->value() : 5);
    const QString roleFilter = ui->emp_knn_role->currentText();

    const int sourceId = ui->emp_knn_source_id ? ui->emp_knn_source_id->value() : 0;
    if (sourceId <= 0 || !Employee::pointTacheDepuisFabrication(sourceId, taskX, taskY)) {
        QMessageBox::warning(this,
                             "Classification KNN",
                             "Impossible de calculer la teche depuis la fabrication selectionnee.");
        return;
    }

    if (ui->emp_knn_task_x) {
        ui->emp_knn_task_x->setValue(taskX);
    }
    if (ui->emp_knn_task_y) {
        ui->emp_knn_task_y->setValue(taskY);
    }

    int trainingUpdates = 0;
    QString trainingError;
    if (!Employee::entrainerModeleKnn(trainingUpdates, trainingError)) {
        qWarning() << "KNN training skipped:" << trainingError;
    }

    QVector<EmployeeKnnRecommendation> recommendations =
        Employee::recommanderEmployesPourTache(taskX, taskY, k, roleFilter);
    const QVector<double> probabilities = Employee::calculerProbabilitesKnn(recommendations);

    QStandardItemModel *model = new QStandardItemModel(this);
    model->setColumnCount(12);
    model->setHorizontalHeaderLabels({
        "Rang", "ID", "Nom", "Prenom", "Role", "Profil (x,y)", "Skills cert./total", "Detail skills", "Distance", "Score KNN", "Classe", "Probabilite"
    });

    for (int i = 0; i < recommendations.size(); ++i) {
        const EmployeeKnnRecommendation &rec = recommendations.at(i);
        const SkillEvidence evidence = fetchSkillEvidence(rec.employee.idEmployee);
          const double probability = i < probabilities.size() ? probabilities.at(i) : 0.0;
          const double certifiedRatio = (evidence.total > 0)
                                                        ? (100.0 * static_cast<double>(evidence.certifiedActive)
                                                            / static_cast<double>(evidence.total))
                                                        : 0.0;

        QList<QStandardItem*> rowItems;
        rowItems << new QStandardItem(QString::number(i + 1));
        rowItems << new QStandardItem(QString::number(rec.employee.idEmployee));
        rowItems << new QStandardItem(rec.employee.nom);
        rowItems << new QStandardItem(rec.employee.prenom);
        rowItems << new QStandardItem(rec.employee.role);
        rowItems << new QStandardItem(
            QString("(%1, %2)").arg(rec.employee.classificationX, 0, 'f', 2)
                               .arg(rec.employee.classificationY, 0, 'f', 2));
        rowItems << new QStandardItem(QString("%1/%2").arg(evidence.certifiedActive).arg(evidence.total));
        rowItems << new QStandardItem(
            QString("Certifies=%1 | Expires=%2 | Formation=%3 | Non qualifies=%4")
                .arg(evidence.certifiedActive)
                .arg(evidence.certifiedExpired)
                .arg(evidence.inTraining)
                .arg(evidence.nonQualified));
        rowItems << new QStandardItem(QString::number(rec.distance, 'f', 4));
        rowItems << new QStandardItem(QString::number(rec.competenceScore, 'f', 2));
        rowItems << new QStandardItem(rec.qualityClass);
        rowItems << new QStandardItem(
            i < probabilities.size()
                ? QString("%1 %").arg(QString::number(probability, 'f', 1))
                : QString("0.0 %"));

        Employee::sauvegarderClasseEmploye(rec.employee.idEmployee,
                                           rec.qualityClass,
                                           rec.competenceScore);

        QColor rowBackground("#111827");
        QColor rowForeground("#e5e7eb");
        QString decisionTag;
        if (probability >= 60.0 && certifiedRatio >= 50.0) {
            decisionTag = "PRIORITE HAUTE";
        } else if (probability >= 40.0 && certifiedRatio >= 30.0) {
            decisionTag = "A VALIDER";
        } else {
            decisionTag = "RISQUE";
        }

        const QString classKey = rec.qualityClass.trimmed().toUpper();
        if (classKey == "A") {
            rowBackground = QColor("#14532d");
            rowForeground = QColor("#dcfce7");
        } else if (classKey == "B") {
            rowBackground = QColor("#1e3a8a");
            rowForeground = QColor("#dbeafe");
        } else if (classKey == "C") {
            rowBackground = QColor("#78350f");
            rowForeground = QColor("#fef3c7");
        } else if (classKey == "D") {
            rowBackground = QColor("#7f1d1d");
            rowForeground = QColor("#fee2e2");
        }

        const QString tooltip = QString(
            "%1\nProbabilite KNN: %2%%\nCertifiees actives: %3/%4 (%5%%)\n"
            "Expirees: %6 | En formation: %7 | Non qualifiees: %8")
                                    .arg(decisionTag)
                                    .arg(QString::number(probability, 'f', 1))
                                    .arg(evidence.certifiedActive)
                                    .arg(evidence.total)
                                    .arg(QString::number(certifiedRatio, 'f', 1))
                                    .arg(evidence.certifiedExpired)
                                    .arg(evidence.inTraining)
                                    .arg(evidence.nonQualified);

        for (QStandardItem *item : rowItems) {
            item->setBackground(rowBackground);
            item->setForeground(rowForeground);
            item->setToolTip(tooltip);
        }

        if (rowItems.size() > 11) {
            rowItems.at(11)->setText(
                QString("%1 (%2)")
                    .arg(QString::number(probability, 'f', 1) + " %")
                    .arg(decisionTag));
        }

        if (rowItems.size() > 11) {
            rowItems.at(0)->setTextAlignment(Qt::AlignCenter);
            rowItems.at(1)->setTextAlignment(Qt::AlignCenter);
            rowItems.at(6)->setTextAlignment(Qt::AlignCenter);
            rowItems.at(8)->setTextAlignment(Qt::AlignRight | Qt::AlignVCenter);
            rowItems.at(9)->setTextAlignment(Qt::AlignRight | Qt::AlignVCenter);
            rowItems.at(10)->setTextAlignment(Qt::AlignCenter);
            rowItems.at(11)->setTextAlignment(Qt::AlignCenter);
        }
        if (i == 0) {
            for (QStandardItem *item : rowItems) {
                QFont f = item->font();
                f.setBold(true);
                item->setFont(f);
            }
        }

        model->appendRow(rowItems);
    }

    if (ui->tv_emp_knn->model()) ui->tv_emp_knn->model()->deleteLater();
    ui->tv_emp_knn->setModel(model);
    ui->tv_emp_knn->setWordWrap(false);
    ui->tv_emp_knn->setTextElideMode(Qt::ElideRight);
    ui->tv_emp_knn->resizeColumnsToContents();
    ui->tv_emp_knn->horizontalHeader()->setStretchLastSection(true);
    ui->tv_emp_knn->setSortingEnabled(false);

    if (model->columnCount() >= 12) {
        ui->tv_emp_knn->setColumnWidth(0, 56);
        ui->tv_emp_knn->setColumnWidth(1, 68);
        ui->tv_emp_knn->setColumnWidth(2, 130);
        ui->tv_emp_knn->setColumnWidth(3, 130);
        ui->tv_emp_knn->setColumnWidth(4, 140);
        ui->tv_emp_knn->setColumnWidth(5, 130);
        ui->tv_emp_knn->setColumnWidth(6, 120);
        ui->tv_emp_knn->setColumnWidth(8, 90);
        ui->tv_emp_knn->setColumnWidth(9, 90);
        ui->tv_emp_knn->setColumnWidth(10, 70);
        ui->tv_emp_knn->setColumnWidth(11, 170);
    }

    renderEmployeeKnnChart(recommendations, taskX, taskY, k);

    if (recommendations.isEmpty()) {
        ui->lb_emp_knn_summary->setText(
            "Aucune recommandation trouvee pour cette fabrication. Verifiez le rele filtre et la qualite des competences EMPLOYEE_SKILL.");
        return;
    }

    const EmployeeKnnRecommendation &best = recommendations.first();
    const SkillEvidence bestEvidence = fetchSkillEvidence(best.employee.idEmployee);
    const double bestProbability = probabilities.isEmpty() ? 0.0 : probabilities.first();
    const double secondDistance = (recommendations.size() > 1) ? recommendations.at(1).distance : best.distance;
    const double distanceScore = qBound(0.0, (1.0 - (best.distance / 0.60)) * 100.0, 100.0);
    const double marginRatio = qBound(0.0,
                                      (secondDistance - best.distance) / qMax(1e-6, secondDistance),
                                      1.0);
    const double marginScore = marginRatio * 100.0;
    const double confidenceScore = (0.50 * bestProbability) + (0.30 * distanceScore) + (0.20 * marginScore);
    const QString confidenceLevel = (confidenceScore >= 70.0)
        ? QString("Confiance elevee")
        : (confidenceScore >= 45.0 ? QString("Confiance moyenne") : QString("Confiance faible"));

    ui->lb_emp_knn_summary->setText(
        QString("Fabrication #%14 | Top 1: %1 %2 (ID %3, rele %4) | Profil=(%5,%6) | Skills certifiees=%7/%8 | Distance=%9 | Score=%10 | Classe=%11 | Probabilite=%12%% | Fiabilite=%13 (%15/100)")
            .arg(best.employee.prenom)
            .arg(best.employee.nom)
            .arg(best.employee.idEmployee)
            .arg(best.employee.role)
            .arg(QString::number(best.employee.classificationX, 'f', 2))
            .arg(QString::number(best.employee.classificationY, 'f', 2))
            .arg(bestEvidence.certifiedActive)
            .arg(bestEvidence.total)
            .arg(QString::number(best.distance, 'f', 4))
            .arg(QString::number(best.competenceScore, 'f', 2))
            .arg(best.qualityClass)
            .arg(QString::number(bestProbability, 'f', 1))
            .arg(confidenceLevel)
            .arg(sourceId)
            .arg(QString::number(confidenceScore, 'f', 1)));

    const QMessageBox::StandardButton feedback = QMessageBox::question(
        this,
        "Apprentissage Actif",
        QString("Meilleure recommandation : %1 %2 (%3)\n\n"
                "Confirmez-vous que ce choix est pertinent pour cette tache ?")
            .arg(best.employee.prenom)
            .arg(best.employee.nom)
            .arg(best.employee.role),
        QMessageBox::Yes | QMessageBox::No | QMessageBox::Cancel,
        QMessageBox::Cancel);

    if (feedback == QMessageBox::Cancel) {
        return;
    }

    const bool confirmed = (feedback == QMessageBox::Yes);
    const bool feedbackApplied = Employee::appliquerFeedbackKnn(best.employee.idEmployee,
                                                                taskX,
                                                                taskY,
                                                                confirmed);

    if (feedbackApplied) {
        QMessageBox::information(this,
                                 "Apprentissage Actif",
                                 confirmed
                                     ? "Feedback positif enregistre (ajustement prudent applique)."
                                     : "Feedback negatif enregistre (ajustement prudent applique).");
    } else {
        QMessageBox::warning(this,
                             "Apprentissage Actif",
                             "Le feedback n'a pas pu etre enregistre.");
    }
}

void smartcarpentry::performSignOut()
{
    // DEBUG: help user identify if this is being triggered by Enter
    // QMessageBox::information(this, "DEBUG", "Tentative de deconnexion detectee!");
    const QMessageBox::StandardButton answer = QMessageBox::question(
        this,
        "Deconnexion",
        "Voulez-vous vous deconnecter ?",
        QMessageBox::Yes | QMessageBox::No,
        QMessageBox::No);

    if (answer != QMessageBox::Yes) {
        return;
    }

    login *loginWindow = new login();
    loginWindow->show();
    close();
}

