void smartcarpentry::on_btn_fab_export_pdf_clicked()
{
    QAbstractItemModel *model = ui->tv_fab->model();
    if (!model || model->rowCount() == 0) {
        QMessageBox::warning(this, "Export PDF", "Aucune donnee a exporter.");
        return;
    }

    QString fileName = QFileDialog::getSaveFileName(
        this, "Exporter la liste Fabrication en PDF",
        QString("fabrications_%1.pdf").arg(QDate::currentDate().toString("yyyyMMdd")),
        "Fichiers PDF (*.pdf)");
    if (fileName.isEmpty()) return;

    QPdfWriter pdf(fileName);
    pdf.setPageSize(QPageSize(QPageSize::A4));
    pdf.setPageOrientation(QPageLayout::Landscape);

    QPainter painter(&pdf);
    painter.setPen(Qt::black);
    painter.setFont(QFont("Arial", 14, QFont::Bold));
    painter.drawText(pdf.width() / 2 - 300, 300, "Rapport des Fabrications");

    int y = 900;
    int colCount = qMin(model->columnCount(), 8);
    int colWidth = pdf.width() / qMax(1, colCount);

    painter.setFont(QFont("Arial", 9, QFont::Bold));
    for (int c = 0; c < colCount; ++c)
        painter.drawText(c * colWidth, y, model->headerData(c, Qt::Horizontal).toString().left(18));
    y += 250;
    painter.drawLine(0, y - 80, pdf.width(), y - 80);

    painter.setFont(QFont("Arial", 9));
    for (int r = 0; r < model->rowCount(); ++r) {
        for (int c = 0; c < colCount; ++c)
            painter.drawText(c * colWidth, y, model->data(model->index(r, c)).toString().left(18));
        y += 200;
        if (y > pdf.height() - 400) { pdf.newPage(); y = 400; }
    }
    painter.end();
    QMessageBox::information(this, "Succes", "Export PDF fabrications reussi !");
}

// ============================================================
//  Phase Form Dialog
// ============================================================

void smartcarpentry::showPhaseFormDialog(int idPhase)
{
    PhaseEditorState state;
    bool editMode = (idPhase > 0);

    if (editMode) {
        // Load existing phase data
        QSqlQuery query;
        query.prepare("SELECT nom_phase, competence_requise, etat, date_debut, date_fin_prevue, date_fin_reelle, idFabrication "
                      "FROM PHASE WHERE id_phase = :id");
        query.bindValue(":id", idPhase);
        if (query.exec() && query.next()) {
            state.id = idPhase;
            state.nomPhase = query.value(0).toString();
            state.competenceRequise = query.value(1).toString();
            state.etat = query.value(2).toString();
            state.dateDebut = query.value(3).toDateTime();
            state.dateFinPrevue = query.value(4).toDateTime();
            state.dateFinReelle = query.value(5).toDateTime();
            state.idFabrication = query.value(6).toInt();
        } else {
            QMessageBox::warning(this, "Erreur", "Impossible de charger la phase.");
            return;
        }
    } else {
        // For new phase, set default fabrication from combo
        if (fabricationAdvancedCombo) {
            state.idFabrication = fabricationAdvancedCombo->currentData().toInt();
        }
        state.etat = "NON_COMMENCE";
        state.dateDebut = QDateTime();
        state.dateFinPrevue = QDateTime();
        state.dateFinReelle = QDateTime();
    }

    if (!openPhaseEditorDialog(this, state, editMode)) {
        return;
    }

    Phase p;
    p.setNomPhase(state.nomPhase);
    p.setCompetenceRequise(state.competenceRequise);
    p.setEtat(Phase::normaliserEtat(state.etat));
    p.setDateDebut(state.dateDebut);
    p.setDateFinPrevue(state.dateFinPrevue);
    p.setDateFinReelle(state.dateFinReelle);
    p.setIdFabrication(state.idFabrication);

    bool success;
    if (editMode) {
        p.setIdPhase(idPhase);
        success = p.modifier(idPhase);
    } else {
        success = p.ajouter();
    }

    if (success) {
        QMessageBox::information(this, "Succes", editMode ? "Phase modifiee." : "Phase ajoutee.");
        refreshFabricationAdvancedPanel();
        refreshPlanificationPanel();
    } else {
        QMessageBox::warning(this, "Erreur", p.getLastError());
    }
}

