// ============================================================
//  Inline Editing - Modele
// ============================================================
void smartcarpentry::on_tv_mod_cellChanged(int row, int column)
{
    QSortFilterProxyModel *proxy = qobject_cast<QSortFilterProxyModel *>(ui->tv_mod->model());
    if (!proxy) return;
    QStandardItemModel *model = qobject_cast<QStandardItemModel *>(proxy->sourceModel());
    if (!model) return;

    QStandardItem *idItem = model->item(row, 0);
    if (!idItem) return;
    int id = idItem->text().toInt();
    
    QString newValue = model->item(row, column)->text().trimmed();
    QString colName;

    switch (column) {
        case 1: colName = "NOMMODELE"; break;
        case 2: colName = "DESCRIPTION"; break;
        case 3: colName = "TEMPS_ESTIME"; break;
        case 4: colName = "PRIX_VENTE"; break;
        case 5: colName = "CATEGORIE"; break;
        default: return;
    }

    QSqlQuery query;
    query.prepare(QString("UPDATE MODELE SET %1 = :val WHERE IDMODELE = :id").arg(colName));
    query.bindValue(":val", newValue);
    query.bindValue(":id", id);

    if (query.exec()) {
        qDebug() << "Inline edit Modele success ID:" << id << " Col:" << colName;
        QTimer::singleShot(0, this, [this]() { refreshModeleTable(); });
    } else {
        QMessageBox::warning(this, "Erreur", "Modification echec : " + query.lastError().text());
        refreshModeleTable();
    }
}

// ============================================================
//  Inline Editing - Piece
// ============================================================
void smartcarpentry::on_tv_pc_cellChanged(int row, int column)
{
    if (pieceInlineEditGuard) return;

    QSortFilterProxyModel *proxy = qobject_cast<QSortFilterProxyModel *>(ui->tv_pc->model());
    if (!proxy) return;
    QStandardItemModel *model = qobject_cast<QStandardItemModel *>(proxy->sourceModel());
    if (!model) return;

    QStandardItem *idItem = model->item(row, 0);
    QStandardItem *valueItem = model->item(row, column);
    if (!idItem || !valueItem) return;

    const int id = idItem->text().toInt();
    if (id <= 0) {
        refreshPieceTable();
        return;
    }
    const QString pieceStatus = model->item(row, 8) ? model->item(row, 8)->text().trimmed().toUpper() : QString();
    const int modeleId = model->item(row, 12) ? model->item(row, 12)->text().toInt() : 0;
    const int boisId = model->item(row, 13) ? model->item(row, 13)->text().toInt() : 0;

    const QVariant editedValue = valueItem->data(Qt::EditRole);
    QString errorMessage;
    pieceInlineEditGuard = true;
    const bool ok = PieceRepository::updatePieceField(id, column, editedValue, errorMessage);
    pieceInlineEditGuard = false;

    if (ok) {
        QTimer::singleShot(0, this, [this, pieceStatus, modeleId, boisId]() {
            if ((pieceStatus == "PUBLIE" || pieceStatus == "BROUILLON")
                && modeleId == pieceContextModeleId
                && boisId == pieceContextBoisId) {
                restorePieceWorkflowState(PieceWorkflowStateRepository::loadWorkflowState(modeleId, boisId, nullptr));
                refreshPieceGenerationContext();
            }
            refreshPieceTable();
        });
        return;
    }

    QMessageBox::warning(this, "Erreur", "Modification invalide : " + errorMessage);
    refreshPieceTable();
}

// ============================================================
//  Inline Editing - Employee
// ============================================================
void smartcarpentry::on_tv_emp_cellChanged(int row, int column)
{
    QStandardItemModel *model = qobject_cast<QStandardItemModel *>(ui->tv_emp->model());
    if (!model) return;

    if (column == 10) {
        return;
    }

    QStandardItem *idItem = model->item(row, 0);
    if (!idItem) return;
    const int id = idItem->data(Qt::UserRole).toInt();
    if (id <= 0) return;
    
    QStandardItem *editedItem = model->item(row, column);
    if (!editedItem) return;

    QString newValue = editedItem->text().trimmed();
    QString colName;
    bool isDateColumn = false;
    bool isNumericColumn = false;

    switch (column) {
        case 0: colName = "CIN"; break;
        case 1: colName = "MAIL"; break;
        case 2: colName = "NOM"; break;
        case 3: colName = "PRENOM"; break;
        case 4: colName = "TELEPHONE"; break;
        case 5: colName = "DATE_NAISSANCE"; isDateColumn = true; break;
        case 6: colName = "DATE_EMBAUCHE"; isDateColumn = true; break;
        case 7: colName = "TYPE_CONTRAT"; break;
        case 8: colName = "SALAIRE_BASE"; isNumericColumn = true; break;
        case 9: colName = "ROLE"; break;
        default: return;
    }

    QSqlQuery query;
    if (isDateColumn) {
        query.prepare(QString("UPDATE EMPLOYEE SET %1 = TO_DATE(:val, 'DD/MM/YYYY') WHERE IDEMPLOYEE = :id").arg(colName));
    } else if (isNumericColumn) {
        query.prepare(QString("UPDATE EMPLOYEE SET %1 = :val WHERE IDEMPLOYEE = :id").arg(colName));
        bool ok = false;
        const double salaryValue = newValue.replace(',', '.').toDouble(&ok);
        if (!ok) {
            QMessageBox::warning(this, "Erreur", "Salaire invalide.");
            refreshEmployeeTable();
            return;
        }
        query.bindValue(":val", salaryValue);
    } else {
        query.prepare(QString("UPDATE EMPLOYEE SET %1 = :val WHERE IDEMPLOYEE = :id").arg(colName));
        query.bindValue(":val", newValue);
    }
    
    query.bindValue(":id", id);

    if (query.exec()) {
        qDebug() << "Inline edit Employee success ID:" << id << " Col:" << colName;
        insertEmployeeHistoryEntry(
            id,
            "UPDATE",
            currentUserEmail,
            QString("Mise a jour inline: %1='%2'").arg(colName, newValue));
        QTimer::singleShot(0, this, [this]() { refreshEmployeeTable(); });
    } else {
        QMessageBox::warning(this, "Erreur", "Modification echec : " + query.lastError().text());
        refreshEmployeeTable();
    }
}

// ============================================================
//  Keyboard Protection - Prevent Enter from closing the app
// ============================================================
void smartcarpentry::keyPressEvent(QKeyEvent *event)
{
    if (event->key() == Qt::Key_Return || event->key() == Qt::Key_Enter) {
        qDebug() << "Caught unhandled Enter key in MainWindow. Ignoring.";
        event->accept(); 
        return;
    }
    QMainWindow::keyPressEvent(event);
}

