    QLabel *subtitleLabel = new QLabel(
        "Detection IR + mesure dimensionnelle en temps reel (Arduino UNO / HC-SR04 / VL53L0X)",
        arduinoScannerTab);
    subtitleLabel->setStyleSheet("font-size:12px;color:#bfdbfe;");

    rootLayout->addWidget(titleLabel);
    rootLayout->addWidget(subtitleLabel);

    QFrame *connectionCard = new QFrame(arduinoScannerTab);
    connectionCard->setObjectName("scannerCard");
    QVBoxLayout *connectionLayout = new QVBoxLayout(connectionCard);
    connectionLayout->setContentsMargins(14, 14, 14, 14);
    connectionLayout->setSpacing(10);

    QHBoxLayout *portLayout = new QHBoxLayout();
    QLabel *portLabel = new QLabel("Port serie", connectionCard);
    portLabel->setStyleSheet("font-size:12px;font-weight:700;color:#cbd5e1;");

    arduinoPortCombo = new QComboBox(connectionCard);
    arduinoPortCombo->setObjectName("arduinoPortCombo");
    arduinoPortCombo->setMinimumWidth(260);

    QPushButton *btnRefreshPorts = new QPushButton("Actualiser", connectionCard);
    btnRefreshPorts->setObjectName("btn_arduino_refresh_ports");
    btnRefreshPorts->setStyleSheet(
        "QPushButton { background: rgba(148,163,184,0.16); color: #e2e8f0; border: 1px solid rgba(148,163,184,0.32);}"
        "QPushButton:hover { background: rgba(148,163,184,0.28); }");

    QPushButton *btnConnect = new QPushButton("Connecter", connectionCard);
    btnConnect->setObjectName("btn_arduino_connect");
    btnConnect->setStyleSheet(
        "QPushButton { background: #16a34a; color: white; border: 1px solid rgba(134,239,172,0.35); }"
        "QPushButton:hover { background: #22c55e; }");

