/**
 * @brief Test routine: Simulate ALARME -> 3 sec delay -> NORMAL (valid alert)
 * Verifies banner display, counters, and logging
 */
void smartcarpentry::testFireAlertBannerNormal()
{
    qDebug() << "TEST: Fire Alert Banner - Normal Alert (>10s)";

    // Simulate ALARME
    onFireRanimAlarmReceived();

    // After 3 seconds, simulate NORMAL
    QTimer::singleShot(3000, this, [this]() {
        qDebug() << "TEST: Received NORMAL after 3 seconds";
        onFireRanimNormalReceived();
        refreshFabricationFireUi();
    });
}

/**
 * @brief Test routine: Simulate ALARME ? <10 sec delay ? NORMAL (false alert)
 * Verifies false alert detection, banner behavior, and logging categorization
 */
void smartcarpentry::testFireAlertBannerFalseAlert()
{
    qDebug() << "TEST: Fire Alert Banner - False Alert (<10s)";

    // Reset counters
    fireSessionAlertCount = 0;
    fireFalseAlertCount = 0;

    // Simulate ALARME
    onFireRanimAlarmReceived();

    // After 6 seconds (< 10), simulate NORMAL
    QTimer::singleShot(6000, this, [this]() {
        qDebug() << "TEST: Received NORMAL after 6 seconds (should count as false alert)";
        onFireRanimNormalReceived();
        refreshFabricationFireUi();

        // Verify results
        qDebug() << "TEST RESULT: Session alerts =" << fireSessionAlertCount;
        qDebug() << "TEST RESULT: False alerts =" << fireFalseAlertCount;
        qDebug() << "TEST RESULT: Current state =" << fireCurrentState;

        if (fireFalseAlertCount >= 1 && fireCurrentState == "NORMAL") {
            qDebug() << "[OK] TEST PASSED: False alert correctly detected and logged";
        } else {
            qDebug() << "[FAIL] TEST FAILED: False alert not properly detected";
        }
    });
}

void smartcarpentry::readArduinoData()
{
    while (!arduinoFrameQueue.isEmpty()) {
        const QString frame = arduinoFrameQueue.takeFirst().trimmed();
        if (frame.isEmpty()) {
            continue;
        }

        if (arduinoLiveFrameLabel) {
            arduinoLiveFrameLabel->setText(frame);
        }

        if (!parseArduinoFrame(frame)) {
            appendArduinoScannerLog(QString("Trame ignoree : %1").arg(frame));
        }
    }
}

bool smartcarpentry::parseArduinoFrame(const QString &frame)
{
    const QString trimmedFrame = frame.trimmed();
    if (trimmedFrame.isEmpty()) {
        return false;
    }

    double lengthMm = 0.0;
    double widthMm = 0.0;
    double thicknessMm = 0.0;

    auto parseFirstThreeNumbers = [&](const QString &rawPayload) -> bool {
        const QRegularExpression numberPattern("(-?\\d+(?:[\\.,]\\d+)?)");
        QRegularExpressionMatchIterator it = numberPattern.globalMatch(rawPayload);
        QVector<double> values;
        values.reserve(3);

        while (it.hasNext() && values.size() < 3) {
            const QRegularExpressionMatch m = it.next();
            bool ok = false;
            const double parsedValue = m.captured(1).replace(',', '.').toDouble(&ok);
            if (ok) {
                values.append(parsedValue);
            }
        }

        if (values.size() < 3) {
            return false;
        }

        lengthMm = values.at(0);
        widthMm = values.at(1);
        thicknessMm = values.at(2);
        return true;
    };

    bool parsed = false;
    if (trimmedFrame.startsWith("DATA", Qt::CaseInsensitive)) {
        parsed = parseFirstThreeNumbers(trimmedFrame);
    } else if (trimmedFrame.startsWith('<') && trimmedFrame.endsWith('>')) {
        const QString payload = trimmedFrame.mid(1, trimmedFrame.size() - 2);
        parsed = parseFirstThreeNumbers(payload);
    }

    if (!parsed) {
        return false;
    }

    arduinoDetectedLengthMm = lengthMm;
    arduinoDetectedWidthMm = widthMm;
    arduinoDetectedThicknessMm = thicknessMm;
    if (!arduinoScanCycleStartedAt.isValid()) {
        arduinoScanCycleStartedAt = QDateTime::currentDateTime();
        arduinoScanCompletionAnnounced = false;
    }
    appendArduinoScannerLog(QString("Dimensions detectees: L=%1 mm, l=%2 mm, e=%3 mm")
                                .arg(formatPieceStatNumber(arduinoDetectedLengthMm, 1),
                                     formatPieceStatNumber(arduinoDetectedWidthMm, 1),
                                     formatPieceStatNumber(arduinoDetectedThicknessMm, 1)));

    if (arduinoLiveLengthLabel) {
        arduinoLiveLengthLabel->setText(QString("%1 mm").arg(formatPieceStatNumber(arduinoDetectedLengthMm, 1)));
    }
    if (arduinoLiveWidthLabel) {
        arduinoLiveWidthLabel->setText(QString("%1 mm").arg(formatPieceStatNumber(arduinoDetectedWidthMm, 1)));
    }
    if (arduinoLiveThicknessLabel) {
        arduinoLiveThicknessLabel->setText(QString("%1 mm").arg(formatPieceStatNumber(arduinoDetectedThicknessMm, 1)));
    }

    if (ui->pc_long) {
        ui->pc_long->setValue(arduinoDetectedLengthMm);
    }
    if (ui->pc_larg) {
        ui->pc_larg->setValue(arduinoDetectedWidthMm);
    }
    if (ui->pc_epais) {
        ui->pc_epais->setValue(arduinoDetectedThicknessMm);
    }

    updateArduinoScannerStatus("Scan en cours", "warning");
    if (arduinoScanProgressBar) {
        const int boostedValue = qMax(arduinoScanProgressBar->value(),
                                      QRandomGenerator::global()->bounded(58, 79));
        arduinoScanProgressBar->setValue(boostedValue);
    }
    if (arduinoScanPulseTimer && !arduinoScanPulseTimer->isActive()) {
        arduinoScanPulseTimer->start();
    }

    appendArduinoScannerLog("Trame DATA analysee.");
    calculatePanelMetrics();

    if (!arduinoPanelMetricsValid) {
        if (arduinoScanProgressBar && arduinoScanProgressBar->value() > 92) {
            arduinoScanProgressBar->setValue(92);
        }
        return true;
    }

    completeArduinoScanWithLatency();

    return true;
}

void smartcarpentry::calculatePanelMetrics()
{
    arduinoDetectedSurface = arduinoDetectedLengthMm * arduinoDetectedWidthMm;
    arduinoDetectedVolume = arduinoDetectedSurface * arduinoDetectedThicknessMm;

    if (arduinoKpiLengthLabel) {
        arduinoKpiLengthLabel->setText(QString("%1 mm").arg(QString::number(arduinoDetectedLengthMm, 'f', 1)));
    }
    if (arduinoKpiWidthLabel) {
        arduinoKpiWidthLabel->setText(QString("%1 mm").arg(QString::number(arduinoDetectedWidthMm, 'f', 1)));
    }
    if (arduinoKpiThicknessLabel) {
        arduinoKpiThicknessLabel->setText(QString("%1 mm").arg(QString::number(arduinoDetectedThicknessMm, 'f', 1)));
    }
    if (arduinoKpiSurfaceLabel) {
        arduinoKpiSurfaceLabel->setText(QString::number(arduinoDetectedSurface, 'f', 0));
    }

    QString validationError;
    arduinoPanelMetricsValid = validatePanelDimensions(&validationError);

    if (arduinoPanelMetricsValid) {
        arduinoPanelQualityStatus = "Mesure valide";
        arduinoPanelValidationMessage.clear();
        updateArduinoKpiTheme("ok");
        appendArduinoScannerLog("Dimensions calculees et validees.");
    } else {
        arduinoPanelValidationMessage = validationError;
        if (arduinoDetectedLengthMm <= 0.0 || arduinoDetectedWidthMm <= 0.0 || arduinoDetectedThicknessMm <= 0.0) {
            arduinoPanelQualityStatus = "Scan incomplet";
            updateArduinoKpiTheme("warning");
            updateArduinoScannerStatus("Scan en cours", "warning");
            if (arduinoScanProgressBar && arduinoScanProgressBar->value() > 85) {
                arduinoScanProgressBar->setValue(85);
            }
        } else {
            arduinoPanelQualityStatus = "Erreur capteur";
            updateArduinoKpiTheme("error");
            updateArduinoScannerStatus("Scan en cours", "error");
        }
        appendArduinoScannerLog(QString("Validation echouee : %1").arg(validationError));
    }

    if (arduinoKpiQualityLabel) {
        arduinoKpiQualityLabel->setText(arduinoPanelQualityStatus);
    }
}

bool smartcarpentry::validatePanelDimensions(QString *errorMessage) const
{
    if (errorMessage) {
        errorMessage->clear();
    }

    if (arduinoDetectedLengthMm <= 0.0) {
        if (errorMessage) {
            *errorMessage = "La longueur doit etre superieure a 0.";
        }
        return false;
    }
    if (arduinoDetectedWidthMm <= 0.0) {
        if (errorMessage) {
            *errorMessage = "La largeur doit etre superieure a 0.";
        }
        return false;
    }
    if (arduinoDetectedThicknessMm <= 0.0) {
        if (errorMessage) {
            *errorMessage = "L'epaisseur doit etre superieure a 0.";
        }
        return false;
    }

    const double maxLengthMm = 6000.0;
    const double maxWidthMm = 3000.0;
    const double maxThicknessMm = 150.0;

    if (arduinoDetectedLengthMm > maxLengthMm) {
        if (errorMessage) {
            *errorMessage = QString("Longueur irrealiste (> %1 mm).")
                                .arg(formatPieceStatNumber(maxLengthMm, 0));
        }
        return false;
    }
    if (arduinoDetectedWidthMm > maxWidthMm) {
        if (errorMessage) {
            *errorMessage = QString("Largeur irrealiste (> %1 mm).")
                                .arg(formatPieceStatNumber(maxWidthMm, 0));
        }
        return false;
    }
    if (arduinoDetectedThicknessMm > maxThicknessMm) {
        if (errorMessage) {
            *errorMessage = QString("Epaisseur irrealiste (> %1 mm).")
                                .arg(formatPieceStatNumber(maxThicknessMm, 0));
        }
        return false;
    }

    return true;
}

bool smartcarpentry::saveDetectedPanelToDatabase()
{
    QString validationError;
    if (!validatePanelDimensions(&validationError)) {
        QMessageBox::warning(this,
                             "Scanner",
                             QString("Impossible d'enregistrer la plaque.\n%1").arg(validationError));
        return false;
    }

    QString storageError;
    if (!PieceRepository::ensureStorage(&storageError)) {
        QMessageBox::critical(this,
                              "Scanner",
                              QString("Schema PIECE indisponible.\n%1").arg(storageError));
        return false;
    }

    const int idModele = ui->pc_modele ? ui->pc_modele->currentData().toInt() : 0;
    const int idBois = ui->pc_matiere ? ui->pc_matiere->currentData().toInt() : 0;
    QString matiere = ui->pc_matiere
        ? ui->pc_matiere->currentData(Qt::UserRole + 1).toString().trimmed()
        : QString();
    if (matiere.isEmpty() && ui->pc_matiere) {
        matiere = ui->pc_matiere->currentText().trimmed();
    }
    if (matiere.isEmpty()) {
        matiere = "Bois brut";
    }

    if (!Piece::validerForeignKey(idModele) || !Piece::validerForeignKey(idBois)) {
        QMessageBox::warning(this,
                             "Scanner",
                             "Selectionnez un modele et un bois valides avant l'enregistrement.");
        return false;
    }

    const QString nowDateTime = QDateTime::currentDateTime().toString("yyyy-MM-dd HH:mm:ss");
    const QString dateOnly = QDate::currentDate().toString("yyyy-MM-dd");
    const QString detectionSource = "Arduino Scanner | Plaque detectee";
    const bool updateExistingPiece = selectedPieceId > 0;

    QSqlQuery query;
    if (updateExistingPiece) {
        query.prepare(
            "UPDATE PIECE SET "
            "LONGUEUR_MM = :longueurMm, "
            "LARGEUR_MM = :largeurMm, "
            "EPAISSEUR_MM = :epaisseurMm, "
            "LONGUEUR_PLAQUE = :longueurPlaque, "
            "LARGEUR_PLAQUE = :largeurPlaque, "
            "EPAISSEUR_PLAQUE = :epaisseurPlaque, "
            "SURFACE_PLAQUE = :surfacePlaque, "
            "VOLUME_PLAQUE = :volumePlaque, "
            "SOURCE_DETECTION = :sourceDetection, "
            "DATE_SCAN = TO_DATE(:dateScan, 'YYYY-MM-DD HH24:MI:SS'), "
            "SOURCE_GENERATION = :sourceGeneration, "
            "UPDATED_AT = TO_DATE(:updatedAt, 'YYYY-MM-DD HH24:MI:SS') "
            "WHERE IDPIECE = :idPiece");

        query.bindValue(":idPiece", selectedPieceId);
        query.bindValue(":sourceGeneration", "CAPTEUR_ARDUINO");
    } else {
        QSqlQuery idQuery;
        if (!idQuery.exec("SELECT NVL(MAX(IDPIECE), 0) + 1 FROM PIECE") || !idQuery.next()) {
            QMessageBox::critical(this,
                                  "Scanner",
                                  QString("Impossible de generer l'identifiant PIECE.\n%1")
                                      .arg(idQuery.lastError().text()));
            return false;
        }

        const int nextPieceId = idQuery.value(0).toInt();
        const QString generatedCode = QString("PLQ-%1")
                                          .arg(QDateTime::currentDateTime().toString("yyMMddHHmmss"));
        const QString generatedName = QString("Piece brute %1")
                                          .arg(QDateTime::currentDateTime().toString("dd/MM/yyyy HH:mm"));

        query.prepare(
            "INSERT INTO PIECE "
            "(IDPIECE, NOMPIECE, CODEPIECE, QUANTITE, MATIERE, "
            "LONGUEUR_MM, LARGEUR_MM, EPAISSEUR_MM, "
            "LONGUEUR_PLAQUE, LARGEUR_PLAQUE, EPAISSEUR_PLAQUE, SURFACE_PLAQUE, VOLUME_PLAQUE, "
            "SOURCE_DETECTION, DATE_SCAN, STATUT, SOURCE_GENERATION, UPDATED_AT, DATE_CREATION, IDMODELE, IDBOIS) "
            "VALUES "
            "(:idPiece, :nomPiece, :codePiece, :quantite, :matiere, "
            ":longueurMm, :largeurMm, :epaisseurMm, "
            ":longueurPlaque, :largeurPlaque, :epaisseurPlaque, :surfacePlaque, :volumePlaque, "
            ":sourceDetection, TO_DATE(:dateScan, 'YYYY-MM-DD HH24:MI:SS'), :statut, :sourceGeneration, "
            "TO_DATE(:updatedAt, 'YYYY-MM-DD HH24:MI:SS'), TO_DATE(:dateCreation, 'YYYY-MM-DD'), :idModele, :idBois)");

        query.bindValue(":idPiece", nextPieceId);
        query.bindValue(":nomPiece", generatedName);
        query.bindValue(":codePiece", generatedCode);
        query.bindValue(":quantite", 1);
        query.bindValue(":matiere", matiere);
        query.bindValue(":statut", "PUBLIE");
        query.bindValue(":sourceGeneration", "CAPTEUR_ARDUINO");
        query.bindValue(":dateCreation", dateOnly);
        query.bindValue(":idModele", idModele);
        query.bindValue(":idBois", idBois);

        selectedPieceId = nextPieceId;

        if (ui->pc_nom) {
            ui->pc_nom->setText(generatedName);
        }
        if (ui->pc_code) {
            ui->pc_code->setText(generatedCode);
        }
        if (ui->pc_qty) {
            ui->pc_qty->setValue(1);
        }
    }

    query.bindValue(":longueurMm", arduinoDetectedLengthMm);
    query.bindValue(":largeurMm", arduinoDetectedWidthMm);
    query.bindValue(":epaisseurMm", arduinoDetectedThicknessMm);
    query.bindValue(":longueurPlaque", arduinoDetectedLengthMm);
    query.bindValue(":largeurPlaque", arduinoDetectedWidthMm);
    query.bindValue(":epaisseurPlaque", arduinoDetectedThicknessMm);
    query.bindValue(":surfacePlaque", arduinoDetectedSurface);
    query.bindValue(":volumePlaque", arduinoDetectedVolume);
    query.bindValue(":sourceDetection", detectionSource);
    query.bindValue(":dateScan", nowDateTime);
    query.bindValue(":updatedAt", nowDateTime);

    if (!query.exec()) {
        QMessageBox::critical(this,
                              "Scanner",
                              QString("Erreur Oracle lors de l'enregistrement de la plaque.\n%1")
                                  .arg(query.lastError().text()));
        appendArduinoScannerLog(QString("Erreur Oracle : %1").arg(query.lastError().text()));
        return false;
    }

    if (ui->pc_long) {
        ui->pc_long->setValue(arduinoDetectedLengthMm);
    }
    if (ui->pc_larg) {
        ui->pc_larg->setValue(arduinoDetectedWidthMm);
    }
    if (ui->pc_epais) {
        ui->pc_epais->setValue(arduinoDetectedThicknessMm);
    }

    Piece historyPiece;
    historyPiece.setNomPiece(ui->pc_nom ? ui->pc_nom->text().trimmed() : QString("Piece brute capteur"));
    historyPiece.setMatiere(matiere);
    historyPiece.setLongueurMm(arduinoDetectedLengthMm);
    historyPiece.setLargeurMm(arduinoDetectedWidthMm);
    historyPiece.setQuantite(1);
    historyPiece.setSourceGeneration("CAPTEUR_ARDUINO");
    const QString modeleLabel = ui->pc_modele ? ui->pc_modele->currentText().trimmed() : QString::number(idModele);
    const QString boisLabel = ui->pc_matiere ? ui->pc_matiere->currentText().trimmed() : QString::number(idBois);
    appendPieceAiHistoryRow(historyPiece, modeleLabel, boisLabel);

    refreshPieceTable();
    refreshPieceGenerationContext();

    appendArduinoScannerLog("Plaque enregistree dans la base Oracle.");
    QMessageBox::information(this,
                             "Scanner",
                             updateExistingPiece
                                 ? "La piece selectionnee a ete mise a jour avec les mesures de la plaque."
                                 : "La piece brute detectee a ete creee avec succes dans la table PIECE.");
    return true;
}

// ============================================================
//  ArduinoManager legacy slots (required by connect() calls)
// ============================================================

void smartcarpentry::onArduinoBoardScanned(double length, double width, double thickness)
{
    if (ui->pc_long) {
        ui->pc_long->setValue(length);
    }
    if (ui->pc_larg) {
        ui->pc_larg->setValue(width);
    }
    if (ui->pc_epais) {
        ui->pc_epais->setValue(thickness);
    }
}

void smartcarpentry::onArduinoConnectionStatusChanged(bool isConnected, const QString &message)
{
    Q_UNUSED(isConnected);
    Q_UNUSED(message);
}

void smartcarpentry::onArduinoConnectionSucceeded(const QString &portName)
{
    fireConnectedPortName = portName;
    if (arduinoStatusLabel) {
        arduinoStatusLabel->setText(QString("Etat liaison : connecte sur %1").arg(portName));
        arduinoStatusLabel->setStyleSheet(
            "font-size:12px;font-weight:700;color:#dcfce7;"
            "background: rgba(20,83,45,0.34);"
            "border: 1px solid rgba(74,222,128,0.45);"
            "border-radius: 10px;"
            "padding: 7px 10px;");
    }

    appendArduinoScannerLog(QString("Connexion Arduino reussie sur %1.").arg(portName));
    if (arduinoScanPulseTimer) {
        arduinoScanPulseTimer->stop();
    }
    if (arduinoScanProgressBar) {
        arduinoScanProgressBar->setValue(0);
    }
    arduinoIrPreviouslyDetected = false;
    clearArduinoScanCycle();
    updateArduinoScannerStatus("Aucune plaque", "neutral");
    refreshArduinoPortList();
    refreshFabricationFireUi();
}

void smartcarpentry::onArduinoConnectionFailed(const QString &portName, const QString &errorMessage)
{
    fireConnectedPortName.clear();
    if (arduinoStatusLabel) {
        QString shortError = errorMessage;
        if (shortError.contains('\n')) {
            shortError = shortError.section('\n', 0, 0);
        }
        arduinoStatusLabel->setText(QString("Etat liaison : echec sur %1 - %2").arg(portName, shortError));
        arduinoStatusLabel->setToolTip(errorMessage);
        arduinoStatusLabel->setStyleSheet(
            "font-size:12px;font-weight:700;color:#fee2e2;"
            "background: rgba(127,29,29,0.42);"
            "border: 1px solid rgba(248,113,113,0.45);"
            "border-radius: 10px;"
            "padding: 7px 10px;");
    }

    appendArduinoScannerLog(QString("Echec de connexion sur %1 : %2").arg(portName, errorMessage));

    QMessageBox msgBox(this);
    msgBox.setWindowTitle("Erreur de connexion Arduino");
    msgBox.setIcon(QMessageBox::Warning);
    msgBox.setText(QString("Impossible de se connecter au port %1").arg(portName));
    msgBox.setDetailedText(errorMessage);
    msgBox.exec();

    if (arduinoScanPulseTimer) {
        arduinoScanPulseTimer->stop();
    }
    if (arduinoScanProgressBar) {
        arduinoScanProgressBar->setValue(0);
    }
    arduinoIrPreviouslyDetected = false;
    clearArduinoScanCycle();
    updateArduinoScannerStatus("Aucune plaque", "error");
    refreshArduinoPortList();
    refreshFabricationFireUi();
}

void smartcarpentry::onArduinoDisconnected()
{
    fireConnectedPortName.clear();
    if (arduinoStatusLabel) {
        arduinoStatusLabel->setText("Etat liaison : deconnecte");
        arduinoStatusLabel->setStyleSheet(
            "font-size:12px;font-weight:700;color:#94a3b8;"
            "background: rgba(15,23,42,0.8);"
            "border: 1px solid rgba(148,163,184,0.22);"
            "border-radius: 10px;"
            "padding: 7px 10px;");
    }

    if (arduinoScanPulseTimer) {
        arduinoScanPulseTimer->stop();
    }
    if (arduinoScanProgressBar) {
        arduinoScanProgressBar->setValue(0);
    }
    arduinoIrPreviouslyDetected = false;
    clearArduinoScanCycle();
    updateArduinoScannerStatus("Aucune plaque", "neutral");
    appendArduinoScannerLog("Arduino deconnecte.");
    refreshArduinoPortList();
    refreshFabricationFireUi();
}


